  applyChestGlow(torso, c) {
    if (!this.data.model.chestGlow) return;
    const light = new THREE.PointLight(c.secondary, 0.38, 2.4, 2);
    light.position.set(0, 0.3, 0.28);
    torso.add(light);
    const bar = addMesh(torso, new THREE.BoxGeometry(0.21, 0.014, 0.01), new THREE.MeshBasicMaterial({ color: c.secondary }), [0, 0.35, 0.198]);
    bar.material.transparent = true;
    bar.material.opacity = 0.9;
  }

  setState(state) {
    if (this.state !== state) this.state = state;
  }

  update(dt, speed = 0, aiming = false) {
    this.clock += dt;
    const t = this.clock;
    const moving = speed > 0.1;
    const run = speed > 4.5;
    this.walkCycle += dt * (run ? 12 : moving ? 8 : 1.8);

    if (this.menuPose) {
      const breath = Math.sin(t * 1.55) * 0.012;
      this.torso.position.y = 1.11 * (this.data.model.height / 1.74) + breath;
      this.head.rotation.y = Math.sin(t * 0.42) * 0.11;
      this.head.rotation.x = Math.sin(t * 0.6) * 0.025;
      this.leftArm.rotation.z = -0.13 - Math.sin(t * 0.8) * 0.025;
      this.rightArm.rotation.z = 0.13 + Math.sin(t * 0.8 + 0.8) * 0.02;
      this.leftArm.rotation.x = Math.sin(t * 0.7) * 0.03;
      this.rightArm.rotation.x = -Math.sin(t * 0.7) * 0.03;
      if (this.data.model.hairStyle === 'long-braid') this.head.rotation.z = Math.sin(t * 0.5) * 0.015;
      this.leftLeg.rotation.z = -0.02;
      this.rightLeg.rotation.z = 0.02;
      return;
    }

    const swing = moving ? Math.sin(this.walkCycle) * (run ? 0.58 : 0.36) : 0;
    const counter = moving ? Math.cos(this.walkCycle) * (run ? 0.1 : 0.06) : 0;
    this.leftLeg.rotation.x = THREE.MathUtils.lerp(this.leftLeg.rotation.x, swing, 0.55);
    this.rightLeg.rotation.x = THREE.MathUtils.lerp(this.rightLeg.rotation.x, -swing, 0.55);
    this.leftArm.rotation.x = THREE.MathUtils.lerp(this.leftArm.rotation.x, -swing * 0.62, 0.4);
    this.rightArm.rotation.x = THREE.MathUtils.lerp(this.rightArm.rotation.x, swing * 0.45, 0.4);
    this.leftArm.rotation.z = -0.13;
    this.rightArm.rotation.z = 0.13;
    this.torso.position.y = 1.11 * (this.data.model.height / 1.74) + (moving ? Math.abs(Math.sin(this.walkCycle * 2)) * 0.018 : Math.sin(t * 1.7) * 0.006);
    this.torso.rotation.y = counter * 0.35;
    this.head.rotation.y = -counter * 0.18;
    this.root.rotation.z = moving ? Math.sin(this.walkCycle) * 0.018 : 0;
    if (aiming) {
      this.leftArm.rotation.x = -1.05;
      this.rightArm.rotation.x = -1.0;
      this.leftArm.rotation.z = 0.25;
      this.rightArm.rotation.z = -0.25;
    }
  }

  dispose() {
    this.group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
    });
    this.materials.forEach((m) => m.dispose());
  }
}

export function createCharacterModel(data, options = {}) {
  return new CharacterModel(data, options);
}

export class CharacterViewer {
  constructor(renderer, container) {
    this.renderer = renderer;
    this.container = container;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(28, 1, 0.1, 100);
    this.camera.position.set(0, 1.5, 5.6);
    this.camera.lookAt(0, 1.05, 0);
    this.holder = new THREE.Group();
    this.scene.add(this.holder);
    this.current = null;
    this.rotation = 0;
    this.targetRotation = 0;
    this.targetZoom = 5.6;
    this.zoom = 5.6;
    this.drag = null;
    this.buildStage();
    this.resize();
  }

  buildStage() {
    const hemi = new THREE.HemisphereLight('#9edbff', '#19121f', 1.65);
    this.scene.add(hemi);
    const key = new THREE.SpotLight('#ffd3b2', 38, 14, 0.58, 0.6, 1.5);
    key.position.set(3.5, 5.2, 4);
    key.target.position.set(0, 1.1, 0);
    this.scene.add(key, key.target);
    const rim = new THREE.SpotLight('#ff5f47', 28, 12, 0.65, 0.75, 1.7);
    rim.position.set(-4, 3.2, -3.5);
    rim.target.position.set(0, 1.1, 0);
    this.scene.add(rim, rim.target);
    const fill = new THREE.PointLight('#6fe8ff', 12, 9, 2);
    fill.position.set(3, 1.2, -2.5);
    this.scene.add(fill);

    const platformMat = new THREE.MeshStandardMaterial({ color: '#10141b', roughness: 0.34, metalness: 0.75 });
    const platform = new THREE.Mesh(new THREE.CylinderGeometry(1.15, 1.25, 0.16, 64), platformMat);
    platform.position.y = 0.02;
    platform.receiveShadow = true;
    this.scene.add(platform);
    const ringMat = new THREE.MeshBasicMaterial({ color: '#ff6347' });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(1.12, 0.006, 6, 64), ringMat);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.11;
    this.scene.add(ring);
    const ring2 = new THREE.Mesh(new THREE.TorusGeometry(1.42, 0.004, 6, 64), new THREE.MeshBasicMaterial({ color: '#5ce7ff', transparent: true, opacity: 0.4 }));
    ring2.rotation.x = Math.PI / 2;
    ring2.position.y = 0.065;
    this.scene.add(ring2);
    const grid = new THREE.GridHelper(8, 24, '#273544', '#161d27');
    grid.position.y = -0.06;
    this.scene.add(grid);
    const backRing = new THREE.Mesh(new THREE.TorusGeometry(2.4, 0.008, 5, 100), new THREE.MeshBasicMaterial({ color: '#ff6b4a', transparent: true, opacity: 0.22 }));
    backRing.position.set(0, 2, -1.4);
    this.scene.add(backRing);
    this.stageRing = backRing;
    this.ring = ring;

    const particlesGeo = new THREE.BufferGeometry();
    const positions = [];
    for (let i = 0; i < 80; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 2.5 + Math.random() * 4;
      positions.push(Math.cos(a) * r, Math.random() * 5, Math.sin(a) * r - 1);
    }
    particlesGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    this.particles = new THREE.Points(particlesGeo, new THREE.PointsMaterial({ color: '#ff8f6b', size: 0.018, transparent: true, opacity: 0.65 }));
    this.scene.add(this.particles);

    this.clock = 0;
  }

  setCharacter(data, skinId = 'default') {
    if (this.current) {
      this.holder.remove(this.current.group);
      this.current.dispose();
    }
    this.current = new CharacterModel(data, { menuPose: true, skin: skinId });
    this.current.group.position.y = 0.12;
    this.current.group.rotation.y = Math.PI;
    this.holder.add(this.current.group);
    this.rotation = 0;
    this.targetRotation = 0;
    this.zoom = 5.6;
    this.targetZoom = 5.6;
    this.ring.material.color.set(data.palette.secondary);
    this.stageRing.material.color.set(data.palette.secondary);
  }

  setSkin(skinId) {
    if (!this.current) return;
    this.current.skinId = skinId;
    this.current.applySkin();
  }

  resize(width = this.container.clientWidth, height = this.container.clientHeight) {
    if (!width || !height) return;
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
  }

  startDrag(x) {
    this.drag = { x, startRotation: this.targetRotation };
  }

  dragTo(x) {
    if (!this.drag) return;
    this.targetRotation = this.drag.startRotation + (x - this.drag.x) * 0.012;
  }

  stopDrag() {
    this.drag = null;
  }

  zoomBy(delta) {
    this.targetZoom = THREE.MathUtils.clamp(this.targetZoom + delta, 3.2, 8);
  }

  update(dt) {
    this.clock += dt;
    this.rotation = THREE.MathUtils.lerp(this.rotation, this.targetRotation, 0.1);
    this.zoom = THREE.MathUtils.lerp(this.zoom, this.targetZoom, 0.09);
    if (this.current) {
      this.current.group.rotation.y = Math.PI + this.rotation;
      this.current.update(dt, 0);
    }
    this.camera.position.set(Math.sin(this.clock * 0.1) * 0.08, 1.42, this.zoom);
    this.camera.lookAt(0, 1.0, 0);
    this.holder.rotation.y = 0;
    this.stageRing.rotation.z += dt * 0.02;
    this.particles.rotation.y += dt * 0.008;
    this.ring.material.emissive;
  }

  render() {
    this.renderer.setViewport(0, 0, this.renderer.domElement.width, this.renderer.domElement.height);
    this.renderer.clear();
    this.renderer.render(this.scene, this.camera);
  }
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

const WALL_MAT = {
  dark: new THREE.MeshStandardMaterial({ color: '#1a2027', roughness: 0.82, metalness: 0.28 }),
  panel: new THREE.MeshStandardMaterial({ color: '#252e37', roughness: 0.68, metalness: 0.48 }),
  rust: new THREE.MeshStandardMaterial({ color: '#4b3024', roughness: 0.83, metalness: 0.3 }),
  steel: new THREE.MeshStandardMaterial({ color: '#38434b', roughness: 0.5, metalness: 0.65 }),
  black: new THREE.MeshStandardMaterial({ color: '#0c1015', roughness: 0.65, metalness: 0.45 }),
  concrete: new THREE.MeshStandardMaterial({ color: '#33363a', roughness: 0.92, metalness: 0.03 })
};

function makeCanvasTexture(width, height, draw, repeatX = 1, repeatY = 1) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  draw(ctx, width, height);
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(repeatX, repeatY);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

function addEdges(mesh, color = '#4d5b65', opacity = 0.55) {
  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(mesh.geometry, 24),
    new THREE.LineBasicMaterial({ color, transparent: true, opacity })
  );
  edges.position.copy(mesh.position);
  edges.rotation.copy(mesh.rotation);
  edges.scale.copy(mesh.scale);
  mesh.parent.add(edges);
  return edges;
}

export class World {
  constructor(scene, options = {}) {
    this.scene = scene;
    this.quality = options.quality || 'high';
    this.blockers = [];
    this.collisionMeshes = [];
    this.temporary = [];
    this.smokes = [];
    this.bounds = { minX: -30, maxX: 30, minZ: -36, maxZ: 36 };
    this.sites = {
      A: { id: 'A', center: new THREE.Vector3(-18.5, 0, -16), radius: 5.4 },
      B: { id: 'B', center: new THREE.Vector3(18.5, 0, -16), radius: 5.4 }
    };
    this.spawns = {
      attackers: { center: new THREE.Vector3(0, 0, 30), spread: 5 },
      defenders: { center: new THREE.Vector3(0, 0, -29), spread: 5 }
    };
    this.staticGroup = new THREE.Group();
    this.dynamicGroup = new THREE.Group();
    this.scene.add(this.staticGroup, this.dynamicGroup);
    this.clock = 0;
    this.build();
  }

  build() {
    this.buildSky();
    this.buildLights();
    this.buildGround();
    this.buildBoundaries();
    this.buildStructures();
    this.buildSites();
    this.buildDetails();
    this.buildNavGrid();
  }

  buildSky() {
    const geo = new THREE.SphereGeometry(130, 32, 20);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      uniforms: {
        top: { value: new THREE.Color('#070b12') },
        horizon: { value: new THREE.Color('#1a2634') },
        glow: { value: new THREE.Color('#9c3a2c') }
      },
      vertexShader: `varying vec3 vPos; void main(){ vPos = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `varying vec3 vPos; uniform vec3 top; uniform vec3 horizon; uniform vec3 glow;
        void main(){
          float h = normalize(vPos).y;
          float t = smoothstep(-0.1, 0.65, h);
          vec3 col = mix(horizon, top, t);
          float band = exp(-pow((h - 0.01) * 8.5, 2.0));
          col += glow * band * 0.2;
          gl_FragColor = vec4(col, 1.0);
        }`
    });
    this.scene.add(new THREE.Mesh(geo, mat));
    this.scene.fog = new THREE.FogExp2('#0b1119', 0.0105);

    // A low, huge moon behind the defender spawn.
    const moon = new THREE.Mesh(
      new THREE.CircleGeometry(5.5, 48),
      new THREE.MeshBasicMaterial({ color: '#ffcf9f', transparent: true, opacity: 0.12 })
    );
    moon.position.set(22, 26, -95);
    this.scene.add(moon);
    const moonCore = new THREE.Mesh(new THREE.CircleGeometry(3.5, 32), new THREE.MeshBasicMaterial({ color: '#ffe2c1', transparent: true, opacity: 0.3 }));
    moonCore.position.copy(moon.position).add(new THREE.Vector3(0, 0, 0.1));
    this.scene.add(moonCore);
  }

  buildLights() {
    const hemi = new THREE.HemisphereLight('#9ec9e8', '#1a1015', 1.2);
    this.scene.add(hemi);
    const moon = new THREE.DirectionalLight('#b8d4ee', 2.3);
    moon.position.set(-16, 30, -24);
    moon.castShadow = this.quality !== 'low';
    moon.shadow.mapSize.set(this.quality === 'high' ? 2048 : 1024, this.quality === 'high' ? 2048 : 1024);
    moon.shadow.camera.left = -38;
    moon.shadow.camera.right = 38;
    moon.shadow.camera.top = 44;
    moon.shadow.camera.bottom = -44;
    moon.shadow.camera.far = 100;
    moon.shadow.bias = -0.0008;
    this.scene.add(moon);
    this.moon = moon;

    const siteALight = new THREE.PointLight('#ff5f3d', 95, 25, 2);
    siteALight.position.set(-18.5, 5, -13);
    this.scene.add(siteALight);
    const siteBLight = new THREE.PointLight('#4adfff', 95, 25, 2);
    siteBLight.position.set(18.5, 5, -13);
    this.scene.add(siteBLight);

    const midLight = new THREE.PointLight('#ff9b58', 45, 18, 2);
    midLight.position.set(0, 4.2, 14);
    this.scene.add(midLight);

    const aShaft = new THREE.SpotLight('#ff5f3d', 30, 32, 0.36, 0.7, 1.6);
    aShaft.position.set(-26, 16, -7);
    aShaft.target.position.set(-18, 0, -16);
    this.scene.add(aShaft, aShaft.target);
    const bShaft = new THREE.SpotLight('#4adfff', 30, 32, 0.36, 0.7, 1.6);
    bShaft.position.set(26, 16, -7);
    bShaft.target.position.set(18, 0, -16);
    this.scene.add(bShaft, bShaft.target);
  }

  buildGround() {
    const floorTexture = makeCanvasTexture(1024, 1024, (ctx, w, h) => {
      ctx.fillStyle = '#1b2128';
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = 'rgba(130,150,165,0.12)';
      ctx.lineWidth = 2;
      for (let i = 0; i <= 16; i++) {
        const p = (i / 16) * w;
        ctx.beginPath(); ctx.moveTo(p, 0); ctx.lineTo(p, h); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, p); ctx.lineTo(w, p); ctx.stroke();
      }
      for (let i = 0; i < 3500; i++) {
        const x = Math.random() * w;
        const y = Math.random() * h;
        ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.04})`;
        ctx.fillRect(x, y, Math.random() * 2.5, Math.random() * 2.5);
      }
      ctx.strokeStyle = 'rgba(255,137,80,0.25)';
      ctx.lineWidth = 5;
      ctx.strokeRect(8, 8, w - 16, h - 16);
      ctx.setLineDash([28, 16]);
      ctx.strokeStyle = 'rgba(255,137,80,0.2)';
      ctx.lineWidth = 3;
      ctx.strokeRect(24, 24, w - 48, h - 48);
    }, 12, 12);
    const floorGeo = new THREE.PlaneGeometry(62, 74);
    const floorMat = new THREE.MeshStandardMaterial({ map: floorTexture, color: '#ffffff', roughness: 0.88, metalness: 0.18 });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    this.scene.add(floor);

    const outer = new THREE.Mesh(new THREE.PlaneGeometry(400, 400), new THREE.MeshStandardMaterial({ color: '#090d12', roughness: 1 }));
    outer.rotation.x = -Math.PI / 2;
    outer.position.y = -0.06;
    this.scene.add(outer);

    // Navigation flow markings.
    const laneMat = new THREE.MeshBasicMaterial({ color: '#ff7048', transparent: true, opacity: 0.22 });
    const laneB = new THREE.MeshBasicMaterial({ color: '#54dcff', transparent: true, opacity: 0.2 });
    [
      [0, 0.012, 19, 0.1, 7, laneMat],
      [0, 0.012, -8, 0.1, 4, laneB],
      [-14, 0.012, 17, 9, 0.07, laneMat],
      [14, 0.012, 17, 9, 0.07, laneMat],
      [-13, 0.012, -21, 0.07, 8, laneB],
      [13, 0.012, -21, 0.07, 8, laneB]
    ].forEach(([x, y, z, w, d, mat]) => {
      const strip = new THREE.Mesh(new THREE.PlaneGeometry(w, d), mat);
      strip.rotation.x = -Math.PI / 2;
      strip.position.set(x, y, z);
      this.scene.add(strip);
    });
  }

  addBlock(x, z, width, depth, height, material = WALL_MAT.panel, options = {}) {
    const geo = new RoundedBoxGeometry(width, height, depth, 2, Math.min(0.08, width * 0.02));
    const mesh = new THREE.Mesh(geo, material);
    mesh.position.set(x, height / 2, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.staticGroup.add(mesh);
    if (options.edges !== false) addEdges(mesh, options.edgeColor || '#52606b', 0.35);
    this.blockers.push({
      minX: x - width / 2,
      maxX: x + width / 2,
      minZ: z - depth / 2,
      maxZ: z + depth / 2,
      minY: 0,
      maxY: height,
      mesh,
      kind: options.kind || 'wall'
    });
    this.collisionMeshes.push(mesh);
    return mesh;
  }

  addContainer(x, z, width, depth, height, color = 0, rotation = 0) {
    const colors = [WALL_MAT.rust, WALL_MAT.steel, WALL_MAT.panel];
    const mat = typeof color === 'number' ? colors[color % colors.length] : color;
    const geo = new THREE.BoxGeometry(width, height, depth);
    const container = new THREE.Mesh(geo, mat);
    container.position.set(x, height / 2, z);
    container.castShadow = true;
    container.receiveShadow = true;
    this.staticGroup.add(container);
    addEdges(container, '#6d5a4d', 0.32);
    // Corrugated ribs.
    const ribMat = new THREE.MeshStandardMaterial({ color: '#141a1f', roughness: 0.8, metalness: 0.4 });
    const count = Math.floor(width * 2.5);
    for (let i = 0; i < count; i++) {
      const rib = new THREE.Mesh(new THREE.BoxGeometry(0.045, height * 0.88, 0.035), ribMat);
      rib.position.set(-width / 2 + 0.3 + i * (width - 0.6) / count, height / 2, depth / 2 + 0.02);
      this.staticGroup.add(rib);
    }
    this.blockers.push({
      minX: x - width / 2, maxX: x + width / 2, minZ: z - depth / 2, maxZ: z + depth / 2,
      minY: 0, maxY: height, mesh: container, kind: 'container'
    });
    this.collisionMeshes.push(container);
    return container;
  }

  addLowCover(x, z, width, depth, height = 1.15) {
    const geo = new RoundedBoxGeometry(width, height, depth, 2, 0.04);
    const mesh = new THREE.Mesh(geo, WALL_MAT.dark);
    mesh.position.set(x, height / 2, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.staticGroup.add(mesh);
    addEdges(mesh, '#6b7a86', 0.45);
    const top = new THREE.Mesh(new THREE.BoxGeometry(width + 0.03, 0.05, depth + 0.03), WALL_MAT.steel);
    top.position.set(x, height + 0.025, z);
    this.staticGroup.add(top);
    // hazard markings
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(width * 0.55, 0.008, 0.04), new THREE.MeshBasicMaterial({ color: '#ffbb4a', transparent: true, opacity: 0.48 }));
    stripe.position.set(x, height + 0.055, z + depth / 2);
    this.staticGroup.add(stripe);
    this.blockers.push({
      minX: x - width / 2, maxX: x + width / 2, minZ: z - depth / 2, maxZ: z + depth / 2,
      minY: 0, maxY: height, mesh, kind: 'cover'
    });
    this.collisionMeshes.push(mesh);
    return mesh;
  }

  buildBoundaries() {
    this.addBlock(0, -36.5, 62, 1, 6, WALL_MAT.dark);
    this.addBlock(0, 36.5, 62, 1, 6, WALL_MAT.dark);
    this.addBlock(-30.5, 0, 1, 74, 6, WALL_MAT.dark);
    this.addBlock(30.5, 0, 1, 74, 6, WALL_MAT.dark);
    // Corner buttresses.
    for (const x of [-29, 29]) {
      for (const z of [-35, 35]) this.addBlock(x, z, 2.2, 2.2, 7.5, WALL_MAT.panel);
    }
  }

  buildStructures() {
    // Central reactor hall.
    this.addBlock(0, -1.5, 14, 170 * 0.105, 5.6, WALL_MAT.panel, { edgeColor: '#7a6d5b' });
    this.addBlock(0, -1.5, 13.2, 1.4, 5.8, WALL_MAT.steel);
    // Roof cap detail.
    const cap = new THREE.Mesh(new RoundedBoxGeometry(14.4, 0.4, 14.4, 2, 0.08), WALL_MAT.dark);
    cap.position.set(0, 5.8, -1.5);
    cap.castShadow = true;
    this.staticGroup.add(cap);
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.13, 6, 6), WALL_MAT.steel);
    antenna.position.set(-4, 9, -4);
    this.staticGroup.add(antenna);
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 6), new THREE.MeshBasicMaterial({ color: '#ff503d' }));
    beacon.position.set(-4, 12, -4);
    this.staticGroup.add(beacon);
    this.beacon = beacon;

    // Side warehouse masses.
    this.addBlock(-23, 7, 10, 17, 4.6, WALL_MAT.dark);
    this.addBlock(23, 7, 10, 17, 4.6, WALL_MAT.dark);
    // Cut large luminous panels into the side masses visually.
    for (const side of [-1, 1]) {
      const panel = new THREE.Mesh(new THREE.BoxGeometry(0.04, 1.3, 6.2), new THREE.MeshBasicMaterial({ color: side < 0 ? '#ff5e3a' : '#42dbff', transparent: true, opacity: 0.42 }));
      panel.position.set(side * 17.96, 2.8, 6);
      this.staticGroup.add(panel);
    }

    // Attack approach cover.
    this.addContainer(-13, 22, 4.2, 2.5, 2.65, 0);
    this.addContainer(13, 22, 4.2, 2.5, 2.65, 1);
    this.addLowCover(-6, 18, 3.2, 1.1);
    this.addLowCover(6, 18, 3.2, 1.1);
    this.addLowCover(-19, 12, 1.2, 3.8);
    this.addLowCover(19, 12, 1.2, 3.8);

    // Connectors between lanes.
    this.addBlock(-15.5, -2, 2.2, 6.5, 2.1, WALL_MAT.steel);
    this.addBlock(15.5, -2, 2.2, 6.5, 2.1, WALL_MAT.steel);

    // Site back walls.
    this.addBlock(-18.5, -26.5, 20, 1.2, 5.4, WALL_MAT.dark);
    this.addBlock(18.5, -26.5, 20, 1.2, 5.4, WALL_MAT.dark);
    this.addBlock(-28.6, -20, 1.2, 12, 5.4, WALL_MAT.dark);
    this.addBlock(28.6, -20, 1.2, 12, 5.4, WALL_MAT.dark);

    // Site cover pieces.
    this.addLowCover(-22, -12.5, 3.5, 1.2);
    this.addLowCover(-15, -20, 1.2, 3.2);
    this.addLowCover(22, -12.5, 3.5, 1.2);
    this.addLowCover(15, -20, 1.2, 3.2);
    this.addContainer(-12.5, -18, 2.4, 5.2, 2.7, 1);
    this.addContainer(12.5, -18, 2.4, 5.2, 2.7, 2);

    // Mid-site column.
    this.addBlock(0, -17, 3.4, 3.4, 4.4, WALL_MAT.panel);
    this.addLowCover(-3.5, -12.5, 4.1, 1.2);
    this.addLowCover(3.5, -12.5, 4.1, 1.2);

    // Defender rotation shelf and spawn cover.
    this.addLowCover(-10, -27.5, 4.5, 1.1);
    this.addLowCover(10, -27.5, 4.5, 1.1);
    this.addContainer(-7, -32, 3, 2.5, 2.2, 2);
    this.addContainer(7, -32, 3, 2.5, 2.2, 0);

    // Attack spawn cover.
    this.addLowCover(-8, 32.5, 4, 1.2);
    this.addLowCover(8, 32.5, 4, 1.2);
  }

  makeLabelTexture(text, color = '#ffffff', sub = '') {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 256;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, 512, 256);
    ctx.font = '700 150px "Bebas Neue", Impact, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = color;
    ctx.shadowBlur = 24;
    ctx.fillStyle = color;
    ctx.fillText(text, 256, 104);
    if (sub) {
      ctx.shadowBlur = 0;
      ctx.font = '500 30px "Space Grotesk", sans-serif';
      ctx.fillStyle = 'rgba(255,255,255,0.66)';
      ctx.fillText(sub, 256, 205);
    }
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  }

  buildSites() {
    const siteData = [
      { site: this.sites.A, color: '#ff633f', light: '#ff4f2f' },
      { site: this.sites.B, color: '#4bdcff', light: '#23cfff' }
    ];
    for (const { site, color } of siteData) {
      const floor = new THREE.Mesh(
        new THREE.CircleGeometry(site.radius, 64),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.08, depthWrite: false })
      );
      floor.rotation.x = -Math.PI / 2;
      floor.position.set(site.center.x, 0.018, site.center.z);
      this.scene.add(floor);
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(site.radius - 0.12, site.radius, 64),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.82, side: THREE.DoubleSide })
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.set(site.center.x, 0.025, site.center.z);
      this.scene.add(ring);
      const inner = new THREE.Mesh(
        new THREE.RingGeometry(0.9, 1.02, 32),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.5, side: THREE.DoubleSide })
      );
      inner.rotation.x = -Math.PI / 2;
      inner.position.set(site.center.x, 0.026, site.center.z);
      this.scene.add(inner);
      // Cross lines.
      for (let i = 0; i < 4; i++) {
        const line = new THREE.Mesh(new THREE.PlaneGeometry(site.radius * 1.5, 0.035), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.18 }));
        line.rotation.x = -Math.PI / 2;
        line.rotation.z = (i / 4) * Math.PI;
        line.position.set(site.center.x, 0.021, site.center.z);
        this.scene.add(line);
      }
      // Hologram sign.
      const tex = this.makeLabelTexture(site.id, color, 'BOMB SITE');
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false }));
      sprite.scale.set(3.4, 1.7, 1);
      sprite.position.set(site.center.x, 4.1, site.center.z - 4.5);
      this.scene.add(sprite);
      const glow = new THREE.PointLight(color, 8, 8, 2);
      glow.position.set(site.center.x, 2.2, site.center.z);
      this.scene.add(glow);
      // Physical ring posts.
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
        const post = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.07, 0.75, 6), WALL_MAT.steel);
        post.position.set(site.center.x + Math.cos(a) * (site.radius - 0.3), 0.37, site.center.z + Math.sin(a) * (site.radius - 0.3));
        this.staticGroup.add(post);
        const tip = new THREE.Mesh(new THREE.SphereGeometry(0.055, 6, 5), new THREE.MeshBasicMaterial({ color }));
        tip.position.copy(post.position).add(new THREE.Vector3(0, 0.42, 0));
        this.staticGroup.add(tip);
      }
    }
  }

  buildDetails() {
    // Pipes along the outer walls.
    const pipeMat = new THREE.MeshStandardMaterial({ color: '#4b565e', roughness: 0.5, metalness: 0.6 });
    for (const side of [-1, 1]) {
      for (let i = 0; i < 2; i++) {
        const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 38, 8), pipeMat);
        pipe.rotation.x = Math.PI / 2;
        pipe.position.set(side * 29.65, 1.5 + i * 0.55, 4);
        this.staticGroup.add(pipe);
      }
    }

    // Hanging lamps.
    for (const [x, z, color] of [[-17, 7, '#ff9b58'], [17, 7, '#5cdcff'], [-18, -6, '#ff5d3b'], [18, -6, '#44d6ff'], [0, 23, '#ffc26b']]) {
      const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 2.3, 4), WALL_MAT.black);
      cable.position.set(x, 5.2, z);
      this.staticGroup.add(cable);
      const lamp = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.42, 0.18, 10), WALL_MAT.dark);
      lamp.position.set(x, 4.05, z);
      this.staticGroup.add(lamp);
      const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 6), new THREE.MeshBasicMaterial({ color }));
      bulb.position.set(x, 3.94, z);
      this.staticGroup.add(bulb);
      const light = new THREE.PointLight(color, 12, 12, 2);
      light.position.set(x, 3.8, z);
      this.scene.add(light);
    }

    // Rain/ash particles.
    const count = this.quality === 'low' ? 250 : 700;
    const positions = new Float32Array(count * 3);
    const velocities = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = (Math.random() - 0.5) * 62;
      positions[i * 3 + 1] = Math.random() * 12;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 72;
      velocities[i] = 2 + Math.random() * 3;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({ color: '#b5c7d5', size: 0.022, transparent: true, opacity: 0.4, depthWrite: false });
    this.rain = new THREE.Points(geo, mat);
    this.rainVel = velocities;
    this.scene.add(this.rain);

    // Distant skyline.
    for (let i = 0; i < 24; i++) {
      const h = 5 + Math.random() * 20;
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(4 + Math.random() * 8, h, 4 + Math.random() * 8),
        new THREE.MeshBasicMaterial({ color: Math.random() > 0.6 ? '#0e1620' : '#0a1018' })
      );
      const angle = (i / 24) * Math.PI * 2;
      const radius = 58 + Math.random() * 25;
      mesh.position.set(Math.cos(angle) * radius, h / 2 - 2, Math.sin(angle) * radius);
      mesh.rotation.y = angle;
      this.staticGroup.add(mesh);
      if (i % 3 === 0) {
        const win = new THREE.Mesh(new THREE.PlaneGeometry(0.25, 0.6), new THREE.MeshBasicMaterial({ color: '#ffcc85', transparent: true, opacity: 0.55 }));
        win.position.set(mesh.position.x + Math.cos(angle) * 3, 2 + Math.random() * (h - 3), mesh.position.z + Math.sin(angle) * 3);
        win.lookAt(0, win.position.y, 0);
        this.staticGroup.add(win);
      }
    }

    // Ground props.
    for (let i = 0; i < 18; i++) {
      const x = (Math.random() - 0.5) * 54;
      const z = (Math.random() - 0.5) * 62;
      if (Math.abs(x) < 9 && z > -11 && z < 10) continue;
      const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.24, 0.85, 9), i % 2 ? WALL_MAT.rust : WALL_MAT.steel);
      barrel.position.set(x, 0.43, z);
      barrel.rotation.y = Math.random() * Math.PI;
      barrel.castShadow = true;
      this.staticGroup.add(barrel);
    }
  }

  buildNavGrid() {
    this.nav = { minX: -29, maxX: 29, minZ: -35, maxZ: 35, cell: 1.8 };
    const cols = Math.floor((this.nav.maxX - this.nav.minX) / this.nav.cell) + 1;
    const rows = Math.floor((this.nav.maxZ - this.nav.minZ) / this.nav.cell) + 1;
    this.nav.cols = cols;
    this.nav.rows = rows;
    this.nav.blocked = new Uint8Array(cols * rows);
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const x = this.nav.minX + c * this.nav.cell;
        const z = this.nav.minZ + r * this.nav.cell;
        let blocked = this.pointBlocked(x, z, 0.48);
        // Keep spawn points and site centers open.
        for (const p of [this.spawns.attackers.center, this.spawns.defenders.center, this.sites.A.center, this.sites.B.center]) {
          if (Math.hypot(x - p.x, z - p.z) < 2.5) blocked = false;
        }
        this.nav.blocked[r * cols + c] = blocked ? 1 : 0;
      }
    }
  }

  pointBlocked(x, z, radius = 0.38) {
    for (const b of this.blockers) {
      if (b.maxY < 0.45) continue;
      if (x + radius > b.minX && x - radius < b.maxX && z + radius > b.minZ && z - radius < b.maxZ) return true;
    }
    return false;
  }

  circleBlocked(x, z, radius) {
    if (x - radius < this.bounds.minX || x + radius > this.bounds.maxX || z - radius < this.bounds.minZ || z + radius > this.bounds.maxZ) return true;
    return this.pointBlocked(x, z, radius);
  }

  moveCircle(position, dx, dz, radius = 0.34) {
    const steps = Math.max(1, Math.ceil(Math.hypot(dx, dz) / 0.18));
    const sx = dx / steps;
    const sz = dz / steps;
    for (let i = 0; i < steps; i++) {
      if (!this.circleBlocked(position.x + sx, position.z, radius)) position.x += sx;
      if (!this.circleBlocked(position.x, position.z + sz, radius)) position.z += sz;
    }
  }

  nearestFreeCell(x, z) {
    const { cols, rows, minX, minZ, cell } = this.nav;
    let c = Math.round((x - minX) / cell);
    let r = Math.round((z - minZ) / cell);
    c = THREE.MathUtils.clamp(c, 0, cols - 1);
    r = THREE.MathUtils.clamp(r, 0, rows - 1);
    if (!this.nav.blocked[r * cols + c]) return { c, r };
    for (let d = 1; d < 5; d++) {
      for (let dr = -d; dr <= d; dr++) {
        for (let dc = -d; dc <= d; dc++) {
          const cc = c + dc;
          const rr = r + dr;
          if (cc < 0 || rr < 0 || cc >= cols || rr >= rows) continue;
          if (!this.nav.blocked[rr * cols + cc]) return { c: cc, r: rr };
        }
      }
    }
    return { c, r };
  }

  findPath(start, end) {
    const { cols, rows, minX, minZ, cell, blocked } = this.nav;
    const s = this.nearestFreeCell(start.x, start.z);
    const e = this.nearestFreeCell(end.x, end.z);
    const startIdx = s.r * cols + s.c;
    const endIdx = e.r * cols + e.c;
    if (startIdx === endIdx) return [new THREE.Vector3(end.x, 0, end.z)];
    const size = cols * rows;
    const open = [startIdx];
    const came = new Int32Array(size).fill(-1);
    const g = new Float32Array(size).fill(Infinity);
    const f = new Float32Array(size).fill(Infinity);
    const inOpen = new Uint8Array(size);
    g[startIdx] = 0;
    f[startIdx] = this.heuristic(s.c, s.r, e.c, e.r);
    inOpen[startIdx] = 1;
    let iterations = 0;
    while (open.length && iterations++ < 6000) {
      let best = 0;
      for (let i = 1; i < open.length; i++) if (f[open[i]] < f[open[best]]) best = i;
      const current = open.splice(best, 1)[0];
      inOpen[current] = 0;
      if (current === endIdx) {
        const path = [];
        let cur = current;
        while (cur !== -1) {
          const c = cur % cols;
          const r = Math.floor(cur / cols);
          path.push(new THREE.Vector3(minX + c * cell, 0, minZ + r * cell));
          cur = came[cur];
        }
        path.reverse();
        path.push(new THREE.Vector3(end.x, 0, end.z));
        return path;
      }
      const cc = current % cols;
      const rr = Math.floor(current / cols);
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          if (!dr && !dc) continue;
          const nc = cc + dc;
          const nr = rr + dr;
          if (nc < 0 || nr < 0 || nc >= cols || nr >= rows) continue;
          const ni = nr * cols + nc;
          if (blocked[ni]) continue;
          if (dc && dr) {
            if (blocked[rr * cols + nc] || blocked[nr * cols + cc]) continue;
          }
          const cost = g[current] + (dc && dr ? 1.414 : 1);
          if (cost < g[ni]) {
            came[ni] = current;
            g[ni] = cost;
            f[ni] = cost + this.heuristic(nc, nr, e.c, e.r);
            if (!inOpen[ni]) {
              open.push(ni);
              inOpen[ni] = 1;
            }
          }
        }
      }
    }
    return [new THREE.Vector3(end.x, 0, end.z)];
  }

  heuristic(c, r, ec, er) {
    const dx = Math.abs(c - ec);
    const dz = Math.abs(r - er);
    return dx + dz + (Math.SQRT2 - 2) * Math.min(dx, dz);
  }

  raycastStatic(origin, direction, maxDist = 200) {
    let hit = maxDist;
    for (const b of this.blockers) {
      if (b.maxY < 0.2) continue;
      const t = this.rayBox(origin, direction, b, maxDist);
      if (t !== null && t < hit) hit = t;
    }
    for (const t of this.temporary) {
      if (t.dead) continue;
      const tHit = this.rayBox(origin, direction, t.box, maxDist);
      if (tHit !== null && tHit < hit) hit = tHit;
    }
    return hit;
  }

  rayBox(origin, dir, b, maxDist) {
    let tmin = 0;
    let tmax = maxDist;
    const axes = [
      [origin.x, dir.x, b.minX, b.maxX],
      [origin.y, dir.y, b.minY, b.maxY],
      [origin.z, dir.z, b.minZ, b.maxZ]
    ];
    for (const [o, d, min, max] of axes) {
      if (Math.abs(d) < 1e-8) {
        if (o < min || o > max) return null;
      } else {
        let t1 = (min - o) / d;
        let t2 = (max - o) / d;
        if (t1 > t2) [t1, t2] = [t2, t1];
        tmin = Math.max(tmin, t1);
        tmax = Math.min(tmax, t2);
        if (tmin > tmax) return null;
      }
    }
    return tmin > 0.02 ? tmin : null;
  }

  hasLineOfSight(a, b) {
    const dir = new THREE.Vector3().subVectors(b, a);
    const dist = dir.length();
    if (dist < 0.001) return true;
    dir.divideScalar(dist);
    if (this.raycastStatic(a, dir, dist) < dist - 0.15) return false;
    for (const smoke of this.smokes) {
      if (this.segmentSphere(a, b, smoke.center, smoke.radius)) return false;
    }
    return true;
  }

  segmentSphere(a, b, center, radius) {
    const ab = new THREE.Vector3().subVectors(b, a);
    const t = THREE.MathUtils.clamp(new THREE.Vector3().subVectors(center, a).dot(ab) / ab.lengthSq(), 0, 1);
    const p = a.clone().addScaledVector(ab, t);
    return p.distanceTo(center) < radius;
  }

  addBarrier(position, width = 3.4, height = 2.3, duration = 8, color = '#48d7ff') {
    const geo = new RoundedBoxGeometry(width, height, 0.25, 2, 0.07);
    const material = new THREE.MeshStandardMaterial({
      color,
      emissive: color,
      emissiveIntensity: 0.36,
      transparent: true,
      opacity: 0.6,
      roughness: 0.3,
      metalness: 0.3
    });
    const mesh = new THREE.Mesh(geo, material);
    mesh.position.set(position.x, height / 2, position.z);
    mesh.castShadow = true;
    this.dynamicGroup.add(mesh);
    const grid = new THREE.Mesh(
      new THREE.PlaneGeometry(width * 0.9, height * 0.9),
      new THREE.MeshBasicMaterial({ color, wireframe: true, transparent: true, opacity: 0.28 })
    );
    grid.position.z = 0.14;
    mesh.add(grid);
    const box = {
      minX: position.x - width / 2, maxX: position.x + width / 2,
      minZ: position.z - 0.15, maxZ: position.z + 0.15,
      minY: 0, maxY: height, mesh, kind: 'barrier'
    };
    const data = { mesh, box, life: duration, maxLife: duration, type: 'barrier' };
    this.temporary.push(data);
    this.blockers.push(box);
    return data;
  }

  addSmoke(position, radius = 5, duration = 8, color = '#ac8cff') {
    const group = new THREE.Group();
    group.position.copy(position);
    const count = this.quality === 'low' ? 5 : 9;
    for (let i = 0; i < count; i++) {
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(1, 12, 9),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.16, depthWrite: false })
      );
      mesh.scale.setScalar(radius * (0.34 + Math.random() * 0.2));
      mesh.position.set((Math.random() - 0.5) * radius * 0.8, 0.8 + Math.random() * 1.4, (Math.random() - 0.5) * radius * 0.8);
      group.add(mesh);
    }
    const core = new THREE.Mesh(
      new THREE.SphereGeometry(radius * 0.8, 16, 12),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.1, depthWrite: false })
    );
    core.position.y = 1.2;
    core.scale.y = 0.8;
    group.add(core);
    this.dynamicGroup.add(group);
    const data = { group, center: position.clone().setY(1.1), radius: radius * 0.88, life: duration, maxLife: duration, type: 'smoke' };
    this.smokes.push(data);
    return data;
  }

  addZone(position, radius, duration, color = '#ff633f', type = 'damage') {
    const group = new THREE.Group();
    group.position.copy(position);
    group.position.y = 0.03;
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(radius * 0.9, radius, 48),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8, side: THREE.DoubleSide })
    );
    ring.rotation.x = -Math.PI / 2;
    group.add(ring);
    const disc = new THREE.Mesh(
      new THREE.CircleGeometry(radius * 0.88, 48),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.12, side: THREE.DoubleSide, depthWrite: false })
    );
    disc.rotation.x = -Math.PI / 2;
    group.add(disc);
    const light = new THREE.PointLight(color, 7, radius * 2, 2);
    light.position.y = 0.5;
    group.add(light);
    this.dynamicGroup.add(group);
    const data = { group, center: position.clone(), radius, life: duration, maxLife: duration, type, ring };
    this.dynamicGroup.userData.zones = this.dynamicGroup.userData.zones || [];
    this.dynamicGroup.userData.zones.push(data);
    return data;
  }

  addHealStation(position, radius, duration, color = '#67ffb0') {
    const group = new THREE.Group();
    group.position.copy(position);
    const base = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.36, 1.1, 10), WALL_MAT.panel);
    base.position.y = 0.55;
    group.add(base);
    const orb = new THREE.Mesh(new THREE.SphereGeometry(0.17, 10, 8), new THREE.MeshBasicMaterial({ color }));
    orb.position.y = 1.25;
    group.add(orb);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.02, 5, 24), new THREE.MeshBasicMaterial({ color }));
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.05;
    group.add(ring);
    const light = new THREE.PointLight(color, 8, radius * 1.6, 2);
    light.position.y = 1.2;
    group.add(light);
    this.dynamicGroup.add(group);
    const data = { group, center: position.clone(), radius, life: duration, maxLife: duration, type: 'heal', orb, ring };
    this.dynamicGroup.userData.zones = this.dynamicGroup.userData.zones || [];
    this.dynamicGroup.userData.zones.push(data);
    return data;
  }

  update(dt) {
    this.clock += dt;
    // Rain.
    if (this.rain) {
      const pos = this.rain.geometry.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let y = pos.getY(i) - this.rainVel[i] * dt;
        if (y < 0) y = 11 + Math.random() * 3;
        pos.setY(i, y);
      }
      pos.needsUpdate = true;
    }
    if (this.beacon) {
      const t = this.clock % 2;
      this.beacon.material.color.set(t < 0.25 ? '#ff6b4a' : '#4a1510');
    }
    // Decay temporary barriers.
    for (let i = this.temporary.length - 1; i >= 0; i--) {
      const t = this.temporary[i];
      if (t.dead) continue;
      t.life -= dt;
      t.mesh.material.opacity = Math.max(0, 0.6 * (t.life / t.maxLife));
      if (t.life <= 0) {
        t.dead = true;
        this.dynamicGroup.remove(t.mesh);
        const idx = this.blockers.indexOf(t.box);
        if (idx >= 0) this.blockers.splice(idx, 1);
        this.temporary.splice(i, 1);
      }
    }
    // Smoke decay.
    for (let i = this.smokes.length - 1; i >= 0; i--) {
      const s = this.smokes[i];
      s.life -= dt;
      s.group.children.forEach((child) => {
        if (child.material) child.material.opacity = (child.material.opacity || 0) * 0.999;
      });
      s.group.rotation.y += dt * 0.04;
      if (s.life <= 0) {
        this.dynamicGroup.remove(s.group);
        this.smokes.splice(i, 1);
      }
    }
    // Zones.
    const zones = this.dynamicGroup.userData.zones || [];
    for (let i = zones.length - 1; i >= 0; i--) {
      const z = zones[i];
      z.life -= dt;
      z.group.rotation.y += dt * 0.35;
      if (z.orb) z.orb.position.y = 1.25 + Math.sin(this.clock * 3) * 0.08;
      if (z.ring) z.ring.rotation.z += dt * 0.4;
      if (z.life <= 0) {
        this.dynamicGroup.remove(z.group);
        zones.splice(i, 1);
      }
    }
  }

  getSpawn(team, index = 0) {
    const spawn = team === 'attackers' ? this.spawns.attackers : this.spawns.defenders;
    const offsets = [
      [-2.4, 0], [2.4, 0], [-5.2, 1.2], [5.2, 1.2], [-1, 1.5], [1, 1.5]
    ];
    const o = offsets[index % offsets.length];
    return new THREE.Vector3(spawn.center.x + o[0], 0, spawn.center.z + (team === 'attackers' ? o[1] : -o[1]));
  }
}

export class InputManager {
  constructor(settings, callbacks = {}) {
    this.settings = settings;
    this.callbacks = callbacks;
    this.keys = new Set();
    this.lookX = 0;
    this.lookY = 0;
    this.firing = false;
    this.aiming = false;
    this.interactHeld = false;
    this.enabled = false;
    this.pointerLocked = false;
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.joystick = { x: 0, y: 0, active: false, id: null };
    this.lookTouch = { id: null, x: 0, y: 0 };
    this.buttons = {};
    this.setupKeyboard();
    this.setupMouse();
  }

  setupKeyboard() {
    window.addEventListener('keydown', (e) => {
      if (!this.enabled) return;
      if (['Tab', 'Space', 'KeyR', 'KeyE', 'KeyQ', 'KeyF', 'Digit1', 'Digit2'].includes(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      if (e.code === 'Space') this.emit('jump');
      if (e.code === 'KeyR') this.emit('reload');
      if (e.code === 'KeyE') this.interactHeld = true;
      if (e.code === 'KeyQ') this.emit('active');
      if (e.code === 'KeyF') this.emit('special');
      if (e.code === 'Digit1') this.emit('weapon1');
      if (e.code === 'Digit2') this.emit('weapon2');
      if (e.code === 'KeyM') this.emit('map');
      if (e.code === 'Escape' && this.pointerLocked) document.exitPointerLock?.();
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      if (e.code === 'KeyE') this.interactHeld = false;
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.firing = false;
      this.interactHeld = false;
    });
  }

  setupMouse() {
    const canvas = document.querySelector('#game-canvas');
    window.addEventListener('mousemove', (e) => {
      if (!this.enabled || this.isTouch) return;
      if (!this.pointerLocked && e.buttons !== 1) return;
      if (this.pointerLocked) {
        this.lookX += e.movementX;
        this.lookY += e.movementY;
      }
    });
    canvas?.addEventListener('mousedown', (e) => {
      if (!this.enabled) return;
      if (!this.isTouch && !this.pointerLocked) {
        canvas.requestPointerLock?.();
        return;
      }
      if (e.button === 0) {
        this.firing = true;
        this.emit('triggerDown');
      }
      if (e.button === 2) this.aiming = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) {
        this.firing = false;
        this.emit('triggerUp');
      }
      if (e.button === 2) this.aiming = false;
    });
    window.addEventListener('contextmenu', (e) => {
      if (this.enabled) e.preventDefault();
    });
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === canvas;
      this.callbacks.onPointerLock?.(this.pointerLocked);
    });
  }

  setupTouch(container) {
    if (!container) return;
    const joystickZone = container.querySelector('#joystick-zone');
    const joystickKnob = container.querySelector('#joystick-knob');
    const lookZone = container.querySelector('#look-zone');
    if (joystickZone && joystickKnob) {
      const radius = 52;
      const update = (e) => {
        const rect = joystickZone.getBoundingClientRect();
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        let dx = e.clientX - cx;
        let dy = e.clientY - cy;
        const len = Math.hypot(dx, dy);
        if (len > radius) { dx = (dx / len) * radius; dy = (dy / len) * radius; }
        this.joystick.x = dx / radius;
        this.joystick.y = dy / radius;
        joystickKnob.style.transform = `translate(${dx}px, ${dy}px)`;
      };
      joystickZone.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.joystick.id = e.pointerId;
        this.joystick.active = true;
        joystickZone.setPointerCapture(e.pointerId);
        joystickKnob.classList.add('active');
        update(e);
      });
      joystickZone.addEventListener('pointermove', (e) => {
        if (e.pointerId !== this.joystick.id) return;
        e.preventDefault();
        update(e);
      });
      const end = (e) => {
        if (e.pointerId !== this.joystick.id) return;
        this.joystick.active = false;
        this.joystick.x = 0;
        this.joystick.y = 0;
        this.joystick.id = null;
        joystickKnob.style.transform = 'translate(0px, 0px)';
        joystickKnob.classList.remove('active');
      };
      joystickZone.addEventListener('pointerup', end);
      joystickZone.addEventListener('pointercancel', end);
    }
    if (lookZone) {
      let last = { x: 0, y: 0 };
      lookZone.addEventListener('pointerdown', (e) => {
        if (e.pointerType === 'mouse') return;
        this.lookTouch.id = e.pointerId;
        last = { x: e.clientX, y: e.clientY };
        lookZone.setPointerCapture(e.pointerId);
      });
      lookZone.addEventListener('pointermove', (e) => {
        if (e.pointerId !== this.lookTouch.id) return;
        const scale = 1.2;
        this.lookX += (e.clientX - last.x) * scale;
        this.lookY += (e.clientY - last.y) * scale;
        last = { x: e.clientX, y: e.clientY };
      });
      const end = (e) => {
        if (e.pointerId === this.lookTouch.id) this.lookTouch.id = null;
      };
      lookZone.addEventListener('pointerup', end);
      lookZone.addEventListener('pointercancel', end);
    }
    container.querySelectorAll('[data-action]').forEach((el) => {
      const action = el.dataset.action;
      const active = (e) => {
        e.preventDefault();
        el.classList.add('pressed');
        if (action === 'fire') {
          this.firing = true;
          this.emit('triggerDown');
        } else {
          this.emit(action);
        }
        if (action === 'interact') this.interactHeld = true;
      };
      const end = (e) => {
        e.preventDefault();
        el.classList.remove('pressed');
        if (action === 'fire') {
          this.firing = false;
          this.emit('triggerUp');
        }
        if (action === 'interact') this.interactHeld = false;
      };
      el.addEventListener('pointerdown', active);
      el.addEventListener('pointerup', end);
      el.addEventListener('pointercancel', end);
      el.addEventListener('pointerleave', (e) => { if (e.pointerType !== 'mouse') end(e); });
    });
  }

  emit(action) {
    if (!this.enabled) return;
    this.callbacks[action]?.();
  }

  consumeLook() {
    const sensitivity = Number(this.settings.get('sensitivity') || 0.85);
    const scale = 0.0022 * sensitivity;
    const look = { x: this.lookX * scale, y: this.lookY * scale };
    this.lookX = 0;
    this.lookY = 0;
    return look;
  }

  isDown(code) {
    return this.keys.has(code);
  }

  getMoveVector() {
    let x = 0;
    let z = 0;
    if (this.keys.has('KeyW')) z -= 1;
    if (this.keys.has('KeyS')) z += 1;
    if (this.keys.has('KeyA')) x -= 1;
    if (this.keys.has('KeyD')) x += 1;
    if (this.joystick.active) {
      x += this.joystick.x;
      z += this.joystick.y;
    }
    const len = Math.hypot(x, z);
    if (len > 1) { x /= len; z /= len; }
    return { x, z };
  }

  get sprint() {
    return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight');
  }

  setEnabled(value) {
    this.enabled = value;
    if (!value) {
      this.keys.clear();
      this.firing = false;
      this.interactHeld = false;
    }
  }
}

import * as THREE from 'three';
import { WEAPONS, getWeapon } from '../data/weapons.js';

const tmp = new THREE.Vector3();
const tmp2 = new THREE.Vector3();

export class WeaponController {
  constructor(owner, primaryId = 'rifle', game) {
    this.owner = owner;
    this.game = game;
    this.weapons = {
      primary: getWeapon(primaryId),
      secondary: getWeapon('pistol')
    };
    this.ammo = {
      primary: { current: this.weapons.primary.magazine, reserve: this.weapons.primary.reserve },
      secondary: { current: this.weapons.secondary.magazine, reserve: this.weapons.secondary.reserve }
    };
    this.slot = 'primary';
    this.fireTimer = 0;
    this.reloadTimer = 0;
    this.reloading = false;
    this.triggerHeld = false;
    this.shotsFired = 0;
    this.lastShotAt = -10;
  }

  get weapon() {
    return this.weapons[this.slot];
  }

  get ammoState() {
    return this.ammo[this.slot];
  }

  setPrimary(id) {
    this.weapons.primary = getWeapon(id);
    this.ammo.primary = { current: this.weapons.primary.magazine, reserve: this.weapons.primary.reserve };
    this.slot = 'primary';
  }

  reset() {
    this.slot = 'primary';
    for (const key of ['primary', 'secondary']) {
      this.ammo[key] = { current: this.weapons[key].magazine, reserve: this.weapons[key].reserve };
    }
    this.fireTimer = 0;
    this.reloadTimer = 0;
    this.reloading = false;
    this.triggerHeld = false;
  }

  switchSlot(slot) {
    if (slot === this.slot || !this.weapons[slot] || this.reloading) return;
    this.slot = slot;
    this.fireTimer = Math.max(this.fireTimer, 0.18);
    this.owner.onWeaponChanged?.();
    this.game?.audio?.sfx('empty');
  }

  update(dt) {
    this.fireTimer = Math.max(0, this.fireTimer - dt);
    if (this.reloading) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this.finishReload();
    }
  }

  startReload() {
    if (this.reloading || !this.owner.isAlive) return false;
    const ammo = this.ammoState;
    if (ammo.current >= this.weapon.magazine || ammo.reserve <= 0) return false;
    this.reloading = true;
    this.reloadTimer = this.weapon.reload * (this.owner.reloadMultiplier || 1);
    this.owner.onReloadStart?.(this.weapon);
    this.game?.audio?.sfx('reload');
    return true;
  }

  finishReload() {
    const ammo = this.ammoState;
    const needed = this.weapon.magazine - ammo.current;
    const amount = Math.min(needed, ammo.reserve);
    ammo.current += amount;
    ammo.reserve -= amount;
    this.reloading = false;
    this.owner.onReloadEnd?.(this.weapon);
  }

  triggerDown() {
    this.triggerHeld = true;
    this.tryFire();
  }

  triggerUp() {
    this.triggerHeld = false;
  }

  tryFire(originOverride, directionOverride) {
    if (!this.owner.isAlive) return null;
    if (this.reloading) return null;
    if (this.fireTimer > 0) return null;
    const weapon = this.weapon;
    const ammo = this.ammoState;
    if (ammo.current <= 0) {
      if (this.triggerHeld) {
        this.game?.audio?.sfx('empty');
        this.owner.onDryFire?.();
      }
      this.startReload();
      return null;
    }
    const rate = weapon.fireRate / (this.owner.fireRateMultiplier || 1);
    this.fireTimer = rate;
    ammo.current -= 1;
    this.shotsFired += 1;
    this.lastShotAt = this.game?.elapsed || 0;
    const origin = originOverride || this.owner.getEyePosition();
    const baseDirection = directionOverride || this.owner.getAimDirection();
    const spread = weapon.spread * (this.owner.moving ? 1.55 : 1) * (this.owner.isCrouching ? 0.7 : 1);
    const hits = [];
    for (let p = 0; p < weapon.pellets; p++) {
      const dir = baseDirection.clone();
      const randA = Math.random() * Math.PI * 2;
      const randR = Math.sqrt(Math.random()) * spread;
      const right = new THREE.Vector3(-dir.z, 0, dir.x).normalize();
      const up = new THREE.Vector3().crossVectors(right, dir).normalize();
      dir.addScaledVector(right, Math.cos(randA) * randR).addScaledVector(up, Math.sin(randA) * randR).normalize();
      const result = this.resolveRay(origin, dir, weapon);
      hits.push(result);
      this.game?.effects?.tracer(origin, result.point, weapon.color, this.owner.isPlayer);
      if (result.hit) {
        this.game.effects.impact(result.point, result.headshot ? '#ffce6b' : weapon.color);
        this.game.applyDamage(result.target, result.damage, this.owner, { headshot: result.headshot, weapon });
      } else if (result.blocked) {
        this.game.effects.impact(result.point, '#b8c6d4');
      }
    }
    this.owner.onShotFired?.(weapon, hits);
    this.game?.audio?.sfx(weapon.id, this.owner.isPlayer ? 0 : 0.4);
    if (ammo.current <= 0) {
      this.startReload();
    }
    return { weapon, hits };
  }

  resolveRay(origin, direction, weapon) {
    const range = weapon.range;
    const wallDist = this.game.world.raycastStatic(origin, direction, range);
    let closest = { distance: wallDist, target: null, point: origin.clone().addScaledVector(direction, Math.min(wallDist, range)), hit: false, blocked: wallDist < range, headshot: false, damage: 0 };
    const targets = this.game.getCombatants();
    for (const target of targets) {
      if (!target.isAlive || target === this.owner || target.team === this.owner.team) continue;
      const center = target.getChestPosition ? target.getChestPosition() : tmp.copy(target.position).setY(target.position.y + 1.05);
      const head = target.getHeadPosition ? target.getHeadPosition() : tmp2.copy(target.position).setY(target.position.y + 1.62);
      const bodyHit = this.raySphere(origin, direction, center, 0.42);
      const headHit = this.raySphere(origin, direction, head, target.isPlayer ? 0.17 : 0.2);
      let t = null;
      let headshot = false;
      if (headHit !== null && headHit < closest.distance) {
        t = headHit;
        headshot = true;
      }
      if (bodyHit !== null && bodyHit < closest.distance && (t === null || bodyHit < t)) {
        t = bodyHit;
        headshot = false;
      }
      if (t !== null) {
        let damage = weapon.damage * (this.owner.damageMultiplier || 1);
        if (headshot) damage *= weapon.id === 'sniper' ? 2.4 : 1.8;
        if (t > weapon.range * 0.55) damage *= Math.max(0.55, 1 - (t / weapon.range) * 0.5);
        closest = {
          distance: t,
          target,
          point: origin.clone().addScaledVector(direction, t),
          hit: true,
          blocked: false,
          headshot,
          damage: Math.round(damage)
        };
      }
    }
    return closest;
  }

  raySphere(origin, direction, center, radius) {
    const oc = tmp.subVectors(origin, center);
    const b = oc.dot(direction);
    const c = oc.lengthSq() - radius * radius;
    const h = b * b - c;
    if (h < 0) return null;
    const sqrt = Math.sqrt(h);
    const t0 = -b - sqrt;
    const t1 = -b + sqrt;
    if (t0 > 0) return t0;
    if (t1 > 0) return t1;
    return null;
  }
}

import * as THREE from 'three';

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
    this.group = new THREE.Group();
    this.group.name = 'effects';
    scene.add(this.group);
  }

  tracer(from, to, color = '#ffb24a', fromPlayer = false) {
    const geo = new THREE.BufferGeometry().setFromPoints([from.clone(), to.clone()]);
    const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: fromPlayer ? 0.8 : 0.35, depthWrite: false });
    const line = new THREE.Line(geo, mat);
    this.group.add(line);
    this.items.push({ object: line, life: 0.07, maxLife: 0.07, kind: 'tracer', fade: true });
  }

  impact(position, color = '#ffd08a') {
    const group = new THREE.Group();
    group.position.copy(position);
    const count = 5;
    for (let i = 0; i < count; i++) {
      const spark = new THREE.Mesh(
        new THREE.SphereGeometry(0.018, 4, 3),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9 })
      );
      spark.userData.vel = new THREE.Vector3(
        (Math.random() - 0.5) * 5,
        Math.random() * 4,
        (Math.random() - 0.5) * 5
      );
      group.add(spark);
    }
    const flash = new THREE.Mesh(new THREE.SphereGeometry(0.06, 6, 5), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.7 }));
    group.add(flash);
    this.group.add(group);
    this.items.push({ object: group, life: 0.32, maxLife: 0.32, kind: 'impact' });
  }

  muzzle(position, direction, color = '#ffbc5a') {
    const flash = new THREE.Mesh(
      new THREE.ConeGeometry(0.06, 0.22, 5),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, wireframe: true })
    );
    flash.position.copy(position);
    flash.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.clone().normalize());
    this.group.add(flash);
    this.items.push({ object: flash, life: 0.06, maxLife: 0.06, kind: 'muzzle', fade: true });
  }

  ring(position, color = '#ff6b4a', radius = 5, duration = 0.7, vertical = false) {
    const geo = new THREE.RingGeometry(0.92, 1, 48);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(position);
    mesh.position.y += 0.05;
    if (!vertical) mesh.rotation.x = -Math.PI / 2;
    mesh.scale.setScalar(0.2);
    this.group.add(mesh);
    this.items.push({ object: mesh, life: duration, maxLife: duration, kind: 'ring', radius, fade: true });
  }

  smokeBurst(position, color = '#b58cff') {
    for (let i = 0; i < 10; i++) this.impact(position.clone().add(new THREE.Vector3((Math.random() - 0.5) * 2, Math.random(), (Math.random() - 0.5) * 2)), color);
    this.ring(position, color, 3, 0.6);
  }

  lightning(from, to, color = '#70f3ff') {
    const points = [];
    const segments = 7;
    for (let i = 0; i <= segments; i++) {
      const t = i / segments;
      const p = from.clone().lerp(to, t);
      if (i > 0 && i < segments) p.add(new THREE.Vector3((Math.random() - 0.5) * 0.6, (Math.random() - 0.5) * 0.6, (Math.random() - 0.5) * 0.6));
      points.push(p);
    }
    const geo = new THREE.BufferGeometry().setFromPoints(points);
    const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9 }));
    this.group.add(line);
    this.items.push({ object: line, life: 0.24, maxLife: 0.24, kind: 'lightning', fade: true });
  }

  damageNumber(position, amount, headshot = false) {
    const canvas = document.createElement('canvas');
    canvas.width = 160;
    canvas.height = 80;
    const ctx = canvas.getContext('2d');
    ctx.font = `700 ${headshot ? 54 : 42}px "Space Grotesk", sans-serif`;
    ctx.textAlign = 'center';
    ctx.fillStyle = headshot ? '#ffcf62' : '#ffffff';
    ctx.shadowColor = headshot ? '#ffad2e' : '#ff6b4a';
    ctx.shadowBlur = 18;
    ctx.fillText(`${amount}`, 80, 55);
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: texture, transparent: true, depthWrite: false }));
    sprite.position.copy(position);
    sprite.scale.set(0.8, 0.4, 1);
    this.group.add(sprite);
    this.items.push({ object: sprite, life: 0.7, maxLife: 0.7, kind: 'damage', fade: true, rise: true, texture });
  }

  explosion(position, radius = 9) {
    const light = new THREE.PointLight('#ff8a3d', 60, radius * 2.4, 2);
    light.position.copy(position);
    this.group.add(light);
    this.items.push({ object: light, life: 1.1, maxLife: 1.1, kind: 'light', startPower: 60 });
    this.ring(position, '#ff8c45', radius, 1.1);
    this.ring(position, '#ffd98b', radius * 0.6, 0.8);
    for (let i = 0; i < 22; i++) {
      const p = position.clone().add(new THREE.Vector3((Math.random() - 0.5) * 3, Math.random() * 2, (Math.random() - 0.5) * 3));
      this.impact(p, i % 2 ? '#ff9b47' : '#ffd366');
    }
    const sphere = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), new THREE.MeshBasicMaterial({ color: '#ffb35c', transparent: true, opacity: 0.5, depthWrite: false }));
    sphere.position.copy(position);
    sphere.position.y += 1;
    this.group.add(sphere);
    this.items.push({ object: sphere, life: 0.5, maxLife: 0.5, kind: 'blast', radius, fade: true });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      item.life -= dt;
      const t = Math.max(0, item.life / item.maxLife);
      if (item.kind === 'impact') {
        item.object.children.forEach((child) => {
          if (child.userData.vel) {
            child.position.addScaledVector(child.userData.vel, dt);
            child.userData.vel.y -= 8 * dt;
            child.material.opacity = t;
          } else if (child.material) {
            child.material.opacity = t;
          }
        });
      } else if (item.kind === 'ring') {
        item.object.scale.setScalar(0.2 + (1 - t) * item.radius * 0.55);
        item.object.material.opacity = t * 0.8;
      } else if (item.kind === 'blast') {
        item.object.scale.setScalar(1 + (1 - t) * item.radius);
        item.object.material.opacity = t * 0.45;
      } else if (item.kind === 'light') {
        item.object.intensity = t * item.startPower;
      } else if (item.kind === 'damage') {
        item.object.position.y += dt * 0.75;
        item.object.material.opacity = t;
      } else if (item.fade && item.object.material) {
        item.object.material.opacity = t * (item.kind === 'tracer' ? 0.8 : 0.9);
      }
      if (item.life <= 0) {
        this.group.remove(item.object);
        if (item.object.geometry) item.object.geometry.dispose();
        if (item.object.material) item.object.material.dispose();
        if (item.texture) item.texture.dispose();
        this.items.splice(i, 1);
      }
    }
  }

  clear() {
    for (const item of this.items) {
      this.group.remove(item.object);
      item.object.traverse?.((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) o.material.dispose();
      });
      if (item.object.geometry) item.object.geometry.dispose();
      if (item.object.material) item.object.material.dispose();
      if (item.texture) item.texture.dispose();
    }
    this.items = [];
  }
}

import * as THREE from 'three';

const down = new THREE.Vector3(0, -1, 0);

export class AbilityController {
  constructor(owner, data, game) {
    this.owner = owner;
    this.data = data;
    this.game = game;
    this.activeCooldown = 0;
    this.specialCooldown = 0;
    this.lastDamageAt = -10;
    this.buffs = [];
    this.baseStats = { fireRate: 1, speed: 1, damage: 1, reload: 1 };
    this.maxActive = data.active.cooldown;
    this.maxSpecial = data.special.cooldown;
    this.zoneTicker = 0;
    this.initPassive();
  }

  initPassive() {
    const id = this.data.id;
    if (id === 'muralha') this.owner.bonusArmor = 25;
    if (id === 'volt') {
      this.baseStats.reload = 0.85;
      this.baseStats.speed = 1.05;
      this.owner.reloadMultiplier = 0.85;
      this.owner.speedMultiplier = 1.05;
    }
    if (id === 'tigre') {
      this.baseStats.speed = 1.12;
      this.owner.speedMultiplier = 1.12;
    }
    if (id === 'orquidea') {
      this.owner.damageReduction = 0.12;
    }
  }

  resetRound() {
    this.activeCooldown = 0;
    this.specialCooldown = 0;
    this.buffs = [];
    this.lastDamageAt = -10;
    this.owner.fireRateMultiplier = 1;
    this.owner.damageMultiplier = 1;
    this.owner.speedMultiplier = this.baseStats.speed;
    this.owner.reloadMultiplier = this.baseStats.reload;
    this.owner.damageReduction = this.data.id === 'orquidea' ? 0.12 : 0;
    if (this.data.id === 'muralha') this.owner.bonusArmor = 25;
  }

  get activeReady() {
    return this.activeCooldown <= 0;
  }

  get specialReady() {
    return this.specialCooldown <= 0;
  }

  update(dt) {
    this.activeCooldown = Math.max(0, this.activeCooldown - dt);
    this.specialCooldown = Math.max(0, this.specialCooldown - dt);
    for (let i = this.buffs.length - 1; i >= 0; i--) {
      const buff = this.buffs[i];
      buff.time -= dt;
      if (buff.time <= 0) {
        this.owner[buff.stat] = buff.base;
        this.buffs.splice(i, 1);
      }
    }
    const id = this.data.id;
    if (!this.owner.isAlive) return;
    const elapsed = this.game.elapsed;
    if (id === 'sutra' && elapsed - this.lastDamageAt > 5) {
      this.owner.heal(2.5 * dt, true);
    }
    if (id === 'areia' && elapsed - this.lastDamageAt > 6) {
      this.owner.addArmor(8 * dt, 100);
    }
    if (id === 'santa') {
      const allies = this.game.getCombatants().filter((c) => c.team === this.owner.team && c.isAlive && c !== this.owner && c.position.distanceTo(this.owner.position) < 6);
      for (const ally of allies) ally.heal(1.2 * dt, true);
    }
    if (id === 'laco') {
      const inside = this.game.world.smokes.some((s) => s.center.distanceTo(this.owner.position) < s.radius);
      this.owner.inSmoke = inside;
    }
    if (id === 'vespa') {
      const threat = this.game.lastEnemyShot;
      if (threat && threat.team !== this.owner.team && threat.time > elapsed - 0.25) {
        if (threat.shooter.position.distanceTo(this.owner.position) < 18) {
          threat.shooter.revealUntil = Math.max(threat.shooter.revealUntil || 0, elapsed + 2);
        }
      }
    }
    if (this.zoneTicker > 0) this.zoneTicker -= dt;
  }

  onDamaged(amount, attacker) {
    this.lastDamageAt = this.game.elapsed;
    if (this.data.id === 'corvo' && attacker) {
      attacker.revealUntil = Math.max(attacker.revealUntil || 0, this.game.elapsed + 2.5);
    }
  }

  onKill() {
    if (this.data.id === 'brasa') {
      this.applyBuff('reloadMultiplier', 0.65, 6, 'reload');
    }
    if (this.data.id === 'laco') {
      this.activeCooldown = Math.max(0, this.activeCooldown - 3);
    }
  }

  applyBuff(stat, value, duration, label) {
    const base = stat === 'reloadMultiplier' ? (this.baseStats.reload || 1) : (this.baseStats[label] || 1);
    const existing = this.buffs.find((b) => b.stat === stat);
    if (existing) {
      existing.time = Math.max(existing.time, duration);
      this.owner[stat] = value;
    } else {
      this.buffs.push({ stat, base: this.owner[stat] ?? base, time: duration });
      this.owner[stat] = value;
    }
  }

  computeTarget(range = 18) {
    if (!this.owner.isPlayer) {
      const dir = new THREE.Vector3(Math.random() - 0.5, 0, Math.random() - 0.5).normalize();
      return this.owner.position.clone().addScaledVector(dir, Math.min(range, 8));
    }
    const origin = this.owner.getEyePosition();
    const dir = this.owner.getAimDirection();
    const groundDir = new THREE.Vector3(dir.x, 0, dir.z);
    if (groundDir.lengthSq() < 0.01) groundDir.set(0, 0, -1);
    groundDir.normalize();
    const start = new THREE.Vector3(origin.x, 0.4, origin.z);
    const wall = this.game.world.raycastStatic(start, groundDir, range);
    const dist = Math.min(wall - 0.35, range);
    return this.owner.position.clone().addScaledVector(groundDir, Math.max(1, dist));
  }

  useActive(pointOverride) {
    if (!this.owner.isAlive || this.activeCooldown > 0) return false;
    if (!this.game.canUseAbilities()) return false;
    const ability = this.data.active;
    this.activeCooldown = ability.cooldown;
    this.runEffect(ability, pointOverride, false);
    this.game.audio.sfx('ability');
    this.game.hud.abilityUsed?.(this, false);
    return true;
  }

  useSpecial(pointOverride) {
    if (!this.owner.isAlive || this.specialCooldown > 0) return false;
    if (!this.game.canUseAbilities()) return false;
    const ability = this.data.special;
    this.specialCooldown = ability.cooldown;
    this.runEffect(ability, pointOverride, true);
    this.game.audio.sfx('special');
    this.game.hud.abilityUsed?.(this, true);
    return true;
  }

  runEffect(ability, pointOverride, isSpecial) {
    const p = ability.params || {};
    const owner = this.owner;
    const game = this.game;
    const effects = game.effects;
    const color = this.data.palette.secondary;
    const target = pointOverride || this.computeTarget(p.range || 16);

    switch (ability.type) {
      case 'dash': {
        const dir = owner.getAimDirection();
        const horiz = new THREE.Vector3(dir.x, 0, dir.z).normalize();
        const distance = p.distance || 7;
        const steps = 12;
        for (let i = 0; i < steps; i++) game.world.moveCircle(owner.position, horiz.x * distance / steps, horiz.z * distance / steps, 0.34);
        effects.ring(owner.position, color, 2.4, 0.4);
        owner.onDash?.();
        break;
      }
      case 'leap': {
        const dir = owner.getAimDirection();
        const horiz = new THREE.Vector3(dir.x, 0, dir.z).normalize();
        if (owner.isPlayer) {
          owner.velocity.y = p.height || 6;
          owner.velocity.x += horiz.x * (p.distance || 6) * 0.9;
          owner.velocity.z += horiz.z * (p.distance || 6) * 0.9;
        } else {
          for (let i = 0; i < 10; i++) game.world.moveCircle(owner.position, horiz.x * (p.distance || 6) / 10, horiz.z * (p.distance || 6) / 10, 0.34);
        }
        effects.ring(owner.position, color, 3, 0.5);
        break;
      }
      case 'healArea':
      case 'blessing': {
        const radius = p.radius || 6;
        const allies = game.getCombatants().filter((c) => c.team === owner.team && c.isAlive && c.position.distanceTo(owner.position) < radius);
        for (const ally of allies) {
          ally.heal(p.heal || p.amount || 45);
          if (p.shield) ally.addArmor(p.shield, 100);
        }
        owner.heal(p.heal || p.amount || 45);
        if (p.shield) owner.addArmor(p.shield, 100);
        effects.ring(owner.position, color, radius, 0.8);
        effects.ring(owner.position, '#ffffff', radius * 0.6, 0.6);
        break;
      }
      case 'reveal': {
        const radius = p.radius || 30;
        const duration = p.duration || 4;
        const enemies = game.getCombatants().filter((c) => c.team !== owner.team && c.isAlive && (radius > 500 || c.position.distanceTo(owner.position) < radius));
        for (const enemy of enemies) {
          enemy.revealUntil = Math.max(enemy.revealUntil || 0, game.elapsed + duration);
          effects.ring(enemy.position, color, 2.4, 0.6);
        }
        effects.ring(owner.position, color, Math.min(radius, 30), 0.9);
        game.hud.notify(`${ability.name.toUpperCase()} · ${enemies.length} SINAL(S)`, color);
        break;
      }
      case 'shock':
      case 'chain':
      case 'blackout': {
        const radius = p.radius || 7;
        const enemies = game.getCombatants().filter((c) => c.team !== owner.team && c.isAlive && c.position.distanceTo(target) < radius);
        for (const enemy of enemies) {
          game.applyDamage(enemy, p.damage || 20, owner, { ability: ability.name });
          enemy.stunUntil = Math.max(enemy.stunUntil || 0, game.elapsed + (p.stun || 1.2));
          effects.lightning(target.clone().setY(1.3), enemy.getChestPosition(), color);
        }
        effects.ring(target, color, radius, 0.7);
        if (!enemies.length) game.hud.notify('SEM ALVO NA ÁREA', '#8b98a4');
        break;
      }
      case 'barrier': {
        const width = p.width || 3.4;
        const height = p.height || 2.2;
        game.world.addBarrier(target, width, height, p.duration || 8, p.color || color);
        effects.ring(target, color, width, 0.5);
        game.hud.notify(`${ability.name.toUpperCase()} · ATIVO`, color);
        break;
      }
      case 'smoke': {
        game.world.addSmoke(target, p.radius || 5, p.duration || 8, this.data.palette.secondary);
        effects.smokeBurst(target, this.data.palette.secondary);
        break;
      }
      case 'smokeSelf': {
        game.world.addSmoke(owner.position.clone(), p.radius || 9, p.duration || 10, this.data.palette.secondary);
        effects.smokeBurst(owner.position, this.data.palette.secondary);
        break;
      }
      case 'slowField': {
        game.world.addZone(target, p.radius || 5, p.duration || 7, color, 'slow');
        game.registerZone({ type: 'slow', owner, center: target, radius: p.radius || 5, duration: p.duration || 7, slow: p.slow || 0.5 });
        effects.ring(target, color, p.radius || 5, 0.6);
        break;
      }
      case 'damageZone': {
        game.world.addZone(target, p.radius || 4.8, p.duration || 8, color, 'damage');
        game.registerZone({ type: 'damage', owner, center: target, radius: p.radius || 4.8, duration: p.duration || 8, dps: p.dps || 12, tick: 0 });
        effects.ring(target, color, p.radius || 5, 0.7);
        break;
      }
      case 'healStation': {
        game.world.addHealStation(target, p.radius || 5, p.duration || 10, color);
        game.registerZone({ type: 'heal', owner, center: target, radius: p.radius || 5, duration: p.duration || 10, heal: p.heal || 6, tick: 0 });
        effects.ring(target, color, p.radius || 5, 0.7);
        break;
      }
      case 'teamShield': {
        const radius = p.radius || 16;
        const allies = game.getCombatants().filter((c) => c.team === owner.team && c.isAlive && c.position.distanceTo(owner.position) < radius);
        for (const ally of allies) {
          ally.addArmor(p.amount || 50, 100);
          if (p.duration && p.reduction) {
            ally.damageReduction = Math.max(ally.damageReduction || 0, p.reduction);
            ally.reductionUntil = game.elapsed + p.duration;
          }
          effects.ring(ally.position, color, 2.8, 0.8);
        }
        game.hud.notify(`${ability.name.toUpperCase()} · ${allies.length} ALIADOS`, color);
        break;
      }
      case 'teamHeal': {
        const radius = p.radius || 18;
        const allies = game.getCombatants().filter((c) => c.team === owner.team && c.isAlive && c.position.distanceTo(owner.position) < radius);
        for (const ally of allies) {
          ally.heal(p.amount || 60);
          if (p.armor) ally.addArmor(p.armor, 100);
          if (p.duration) {
            ally.speedMultiplier = Math.max(ally.speedMultiplier || 1, 1.18);
            ally.speedBoostUntil = game.elapsed + durationOf(p.duration, 4);
          }
          effects.ring(ally.position, color, 3, 0.7);
        }
        game.hud.notify(`${ability.name.toUpperCase()} · ${allies.length} ALIADOS`, color);
        break;
      }
      case 'frenzy': {
        owner.heal(p.heal || 30);
        this.applyBuff('fireRateMultiplier', p.fireRate || 1.35, p.duration || 8, 'fireRate');
        this.applyBuff('speedMultiplier', p.speed || 1.2, p.duration || 8, 'speed');
        effects.ring(owner.position, color, 3.5, 0.6);
        break;
      }
      case 'markSlow': {
        const enemies = game.getCombatants()
          .filter((c) => c.team !== owner.team && c.isAlive)
          .sort((a, b) => a.position.distanceTo(owner.position) - b.position.distanceTo(owner.position));
        const enemy = enemies[0];
        if (enemy) {
          enemy.revealUntil = Math.max(enemy.revealUntil || 0, game.elapsed + (p.duration || 5));
          enemy.slowUntil = Math.max(enemy.slowUntil || 0, game.elapsed + (p.duration || 5));
          enemy.slowFactor = p.slow || 0.55;
          effects.ring(enemy.position, color, 2.6, 0.7);
          effects.lightning(owner.getEyePosition(), enemy.getChestPosition(), color);
        }
        break;
      }
      case 'hunt': {
        const enemies = game.getCombatants()
          .filter((c) => c.team !== owner.team && c.isAlive)
          .sort((a, b) => a.position.distanceTo(owner.position) - b.position.distanceTo(owner.position))
          .slice(0, p.count || 3);
        for (const enemy of enemies) {
          enemy.revealUntil = Math.max(enemy.revealUntil || 0, game.elapsed + (p.duration || 6));
          effects.ring(enemy.position, color, 2.4, 0.55);
        }
        this.applyBuff('damageMultiplier', p.damage || 1.2, p.duration || 6, 'damage');
        game.hud.notify('CAÇADA ATIVA', color);
        break;
      }
      case 'mirage': {
        const allies = game.getCombatants().filter((c) => c.team === owner.team && c.isAlive && c.position.distanceTo(owner.position) < (p.radius || 16));
        for (const ally of allies) ally.addArmor(p.amount || 40, 100);
        const decoy = owner.position.clone().addScaledVector(owner.getAimDirection(), 4);
        effects.ring(decoy, color, 3.5, 1.2);
        effects.ring(owner.position, color, 3, 0.7);
        game.hud.notify('MIRAGEM', color);
        break;
      }
      default:
        effects.ring(owner.position, color, 3, 0.6);
    }
    owner.onAbilityUsed?.(ability, isSpecial);
  }
}

function durationOf(value, fallback) {
  return typeof value === 'number' ? value : fallback;
}

import * as THREE from 'three';
import { WeaponController } from './WeaponController.js';
import { AbilityController } from './AbilityController.js';
import { createWeaponModel } from './CharacterFactory.js';

const _forward = new THREE.Vector3();
const _right = new THREE.Vector3();

export class Player {
  constructor(data, team, game, primaryWeapon = 'rifle') {
    this.data = data;
    this.character = data;
    this.team = team;
    this.game = game;
    this.isPlayer = true;
    this.name = data.shortName;
    this.position = new THREE.Vector3();
    this.velocity = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.health = 100;
    this.maxHealth = 100;
    this.armor = 0;
    this.maxArmor = 100;
    this.isAlive = true;
    this.kills = 0;
    this.deaths = 0;
    this.assists = 0;
    this.damageDealt = 0;
    this.eyeHeight = 1.62;
    this.radius = 0.34;
    this.grounded = true;
    this.moveSpeed = 5.2;
    this.runSpeed = 8.4;
    this.jumpForce = 6.7;
    this.gravity = 22;
    this.moving = false;
    this.sprinting = false;
    this.speedMultiplier = 1;
    this.fireRateMultiplier = 1;
    this.damageMultiplier = 1;
    this.reloadMultiplier = 1;
    this.damageReduction = 0;
    this.bonusArmor = 0;
    this.revealUntil = 0;
    this.stunUntil = 0;
    this.slowUntil = 0;
    this.slowFactor = 1;
    this.speedBoostUntil = 0;
    this.reductionUntil = 0;
    this.bob = 0;
    this.shake = 0;
    this.recoil = 0;
    this.lastStep = 0;
    this.lastDamageAt = -10;
    this.deathTime = 0;
    this.camera = new THREE.PerspectiveCamera(Number(game.settings.get('fov')) || 72, 1, 0.03, 300);
    this.camera.rotation.order = 'YXZ';
    this.camera.position.set(0, 1.6, 0);
    game.scene.add(this.camera);
    this.viewGroup = new THREE.Group();
    this.camera.add(this.viewGroup);
    this.weapon = new WeaponController(this, primaryWeapon, game);
    this.abilities = new AbilityController(this, data, game);
    this.buildViewLight();
    this.bindInput();
    this.buildViewModel();
    this.game.scene.add(this.camera);
  }

  buildViewLight() {
    const light = new THREE.PointLight('#ffd7b0', 0.8, 2.3, 2);
    light.position.set(0.3, -0.1, -0.2);
    this.camera.add(light);
  }

  bindInput() {
    const input = this.game.input;
    input.callbacks.triggerDown = () => {
      if (!this.isAlive || !this.game.canShoot()) return;
      this.weapon.triggerDown();
    };
    input.callbacks.triggerUp = () => this.weapon.triggerUp();
    input.callbacks.reload = () => {
      if (this.isAlive && this.game.canShoot()) this.weapon.startReload();
    };
    input.callbacks.jump = () => this.tryJump();
    input.callbacks.active = () => this.useActive();
    input.callbacks.special = () => this.useSpecial();
    input.callbacks.weapon1 = () => this.weapon.switchSlot('primary');
    input.callbacks.weapon2 = () => this.weapon.switchSlot('secondary');
    input.callbacks.interact = () => this.game.bombController?.onInteractTap(this);
  }

  resetForRound(spawn) {
    this.position.copy(spawn);
    this.velocity.set(0, 0, 0);
    this.health = 100;
    this.armor = this.bonusArmor || 0;
    this.isAlive = true;
    this.grounded = true;
    this.stunUntil = 0;
    this.slowUntil = 0;
    this.revealUntil = 0;
    this.weapon.reset();
    this.abilities.resetRound();
    this.yaw = this.team === 'attackers' ? 0 : Math.PI;
    this.pitch = 0;
    this.camera.rotation.set(0, this.yaw, 0);
    this.viewGroup.visible = true;
    this.camera.fov = Number(this.game.settings.get('fov')) || 72;
    this.camera.updateProjectionMatrix();
    this.onWeaponChanged();
    this.game.hud.setHealth(this);
    this.game.hud.setWeapon(this.weapon);
  }

  buildViewModel() {
    while (this.viewGroup.children.length) this.viewGroup.remove(this.viewGroup.children[0]);
    const weapon = createWeaponModel(this.weapon.weapon.id, 0.78);
    weapon.position.set(0.28, -0.25, -0.48);
    weapon.rotation.set(-0.04, -0.08, -0.03);
    const hands = new THREE.Group();
    const glove = new THREE.MeshStandardMaterial({ color: '#15191f', roughness: 0.78, metalness: 0.1 });
    const sleeve = new THREE.MeshStandardMaterial({ color: this.data.palette.primary, roughness: 0.7, metalness: 0.12 });
    const accent = new THREE.MeshStandardMaterial({ color: this.data.palette.secondary, emissive: this.data.palette.secondary, emissiveIntensity: 0.3, roughness: 0.3 });
    const handR = new THREE.Mesh(new THREE.CapsuleGeometry(0.05, 0.12, 4, 8), glove);
    handR.position.set(0.31, -0.28, -0.38);
    handR.rotation.set(0.3, 0, -0.25);
    hands.add(handR);
    const armR = new THREE.Mesh(new THREE.CapsuleGeometry(0.065, 0.34, 4, 8), sleeve);
    armR.position.set(0.37, -0.42, -0.22);
    armR.rotation.set(1.18, 0.2, -0.3);
    hands.add(armR);
    const handL = new THREE.Mesh(new THREE.CapsuleGeometry(0.048, 0.12, 4, 8), glove);
    handL.position.set(0.08, -0.3, -0.59);
    handL.rotation.set(0.2, 0, 0.6);
    hands.add(handL);
    const armL = new THREE.Mesh(new THREE.CapsuleGeometry(0.06, 0.32, 4, 8), sleeve);
    armL.position.set(0.0, -0.46, -0.46);
    armL.rotation.set(1.2, -0.1, 0.5);
    hands.add(armL);
    const band = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.015, 0.06), accent);
    band.position.set(0.31, -0.235, -0.39);
    band.rotation.z = -0.25;
    hands.add(band);
    hands.traverse((m) => {
      if (m.isMesh) {
        m.material.depthTest = false;
        m.renderOrder = 92;
        m.castShadow = false;
      }
    });
    weapon.traverse((m) => {
      if (m.isMesh) {
        m.material = m.material.clone();
        m.material.depthTest = false;
        m.renderOrder = 93;
        m.castShadow = false;
      }
    });
    this.viewGroup.add(weapon, hands);
    this.viewWeapon = weapon;
    this.viewHands = hands;
  }

  onWeaponChanged() {
    if (!this.weapon?.weapon?.id) return;
    this.buildViewModel();
    this.game.hud?.setWeapon(this.weapon);
  }

  getEyePosition() {
    return this.position.clone().setY(this.position.y + this.eyeHeight);
  }

  getChestPosition() {
    return this.position.clone().setY(this.position.y + 1.08);
  }

  getHeadPosition() {
    return this.position.clone().setY(this.position.y + 1.62);
  }

  getAimDirection() {
    const dir = new THREE.Vector3(0, 0, -1);
    dir.applyEuler(new THREE.Euler(this.pitch, this.yaw, 0, 'YXZ'));
    return dir.normalize();
  }

  tryJump() {
    if (!this.isAlive || !this.game.canShoot()) return;
    if (this.grounded) {
      this.velocity.y = this.jumpForce;
      this.grounded = false;
      this.game.audio.sfx('jump');
    }
  }

  useActive() {
    if (this.game.canUseAbilities()) this.abilities.useActive();
  }

  useSpecial() {
    if (this.game.canUseAbilities()) this.abilities.useSpecial();
  }

  update(dt) {
    this.abilities.update(dt);
    this.weapon.update(dt);
    if (!this.isAlive) {
      this.deathTime += dt;
      return;
    }
    if (!this.game.controlsEnabled) {
      this.updateCamera(dt);
      return;
    }
    const look = this.game.input.consumeLook();
    this.yaw -= look.x;
    this.pitch -= look.y * (this.game.settings.get('invertY') ? -1 : 1);
    this.pitch = THREE.MathUtils.clamp(this.pitch, -1.25, 1.2);

    const move = this.game.input.getMoveVector();
    const wantSprint = this.game.input.sprint || this.game.input.joystick.active && Math.hypot(this.game.input.joystick.x, this.game.input.joystick.y) > 0.78;
    const stunned = this.game.elapsed < this.stunUntil;
    const slowed = this.game.elapsed < this.slowUntil;
    const speedMul = (this.speedMultiplier || 1) * (this.inSmoke && this.data.id === 'laco' ? 1.15 : 1) * (slowed ? this.slowFactor : 1) * (stunned ? 0.15 : 1);
    this.sprinting = wantSprint && move.z < -0.15;
    const speed = (this.sprinting ? this.runSpeed : this.moveSpeed) * speedMul;
    _forward.set(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
    _right.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
    const targetX = (_forward.x * -move.z + _right.x * move.x) * speed;
    const targetZ = (_forward.z * -move.z + _right.z * move.x) * speed;
    const accel = this.grounded ? 18 : 5;
    this.velocity.x = THREE.MathUtils.damp(this.velocity.x, targetX, accel, dt);
    this.velocity.z = THREE.MathUtils.damp(this.velocity.z, targetZ, accel, dt);
    this.velocity.y -= this.gravity * dt;
    this.game.world.moveCircle(this.position, this.velocity.x * dt, this.velocity.z * dt, this.radius);
    this.position.y += this.velocity.y * dt;
    if (this.position.y <= 0) {
      this.position.y = 0;
      this.velocity.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }
    this.moving = Math.hypot(this.velocity.x, this.velocity.z) > 0.7;
    if (this.moving) {
      this.bob += dt * (this.sprinting ? 13 : 9);
      if (this.game.elapsed - this.lastStep > (this.sprinting ? 0.29 : 0.4)) {
        this.lastStep = this.game.elapsed;
        if (this.grounded) this.game.audio.sfx('step');
      }
    } else {
      this.bob = THREE.MathUtils.damp(this.bob, 0, 8, dt);
    }
    if (this.game.input.firing && this.weapon.weapon.automatic) this.weapon.tryFire();
    this.updateCamera(dt);
    this.animateViewModel(dt);
    if (this.game.elapsed > this.speedBoostUntil && this.speedMultiplier > (this.abilities.baseStats.speed || 1)) {
      this.speedMultiplier = this.abilities.baseStats.speed;
    }
    if (this.game.elapsed > this.reductionUntil && this.damageReduction && this.data.id !== 'orquidea') this.damageReduction = 0;
  }

  updateCamera(dt) {
    const bobY = Math.sin(this.bob) * (this.sprinting ? 0.035 : 0.018);
    const bobX = Math.cos(this.bob * 0.5) * 0.012;
    this.shake = Math.max(0, this.shake - dt * 2.5);
    const shakeX = (Math.random() - 0.5) * this.shake * 0.02;
    const shakeY = (Math.random() - 0.5) * this.shake * 0.02;
    this.camera.position.set(this.position.x + bobX, this.position.y + this.eyeHeight + bobY, this.position.z);
    this.camera.rotation.set(this.pitch + this.recoil + shakeY, this.yaw + shakeX, 0);
    const aiming = this.game.input.aiming;
    const targetFov = (Number(this.game.settings.get('fov')) || 72) / (aiming && this.weapon.weapon.zoom ? 1.5 : 1);
    this.camera.fov = THREE.MathUtils.damp(this.camera.fov, targetFov, 12, dt);
    this.camera.updateProjectionMatrix();
    this.recoil = THREE.MathUtils.damp(this.recoil, 0, 9, dt);
  }

  animateViewModel(dt) {
    if (!this.viewWeapon) return;
    const bobAmt = this.moving ? (this.sprinting ? 0.025 : 0.014) : 0.005;
    const swayX = Math.sin(this.bob * 0.5) * bobAmt;
    const swayY = Math.abs(Math.cos(this.bob)) * bobAmt;
    const reloadDip = this.weapon.reloading ? -0.16 : 0;
    const aim = this.game.input.aiming ? 0.08 : 0;
    this.viewGroup.position.x = THREE.MathUtils.damp(this.viewGroup.position.x, swayX + aim, 10, dt);
    this.viewGroup.position.y = THREE.MathUtils.damp(this.viewGroup.position.y, -swayY + reloadDip, 10, dt);
    this.viewGroup.rotation.z = THREE.MathUtils.damp(this.viewGroup.rotation.z, -swayX * 0.7, 8, dt);
    this.viewGroup.rotation.x = THREE.MathUtils.damp(this.viewGroup.rotation.x, this.weapon.reloading ? 0.3 : 0, 8, dt);
    if (this.weapon.reloading) {
      this.viewGroup.position.y += Math.sin(this.weapon.reloadTimer * 12) * 0.003;
    }
  }

  onShotFired(weapon) {
    this.recoil = Math.min(0.14, this.recoil + weapon.recoil * 0.035);
    this.shake = Math.min(1.8, this.shake + weapon.recoil * 0.45);
    const dir = this.getAimDirection();
    const muzzlePos = this.camera.localToWorld(new THREE.Vector3(0.28, -0.18, -0.85));
    this.game.effects.muzzle(muzzlePos, dir, weapon.color);
    this.lastShotFiredAt = this.game.elapsed;
    this.game.lastEnemyShot = { shooter: this, team: this.team, time: this.game.elapsed };
    this.game.hud?.kickCrosshair(weapon.recoil);
    if (weapon.id === 'shotgun' || weapon.id === 'sniper') this.shake = Math.min(2.5, this.shake + 0.7);
  }

  onDryFire() {}

  onReloadStart() {
    this.game.hud?.setReloading(true, this.weapon.reloadTimer, this.weapon.reloadTimer);
  }

  onReloadEnd() {
    this.game.hud?.setReloading(false);
  }

  onDash() {
    this.shake = Math.max(this.shake, 0.8);
  }

  onAbilityUsed(ability, special) {
    this.game.hud?.abilityUsed(this.abilities, special);
  }

  heal(amount, silent = false) {
    if (!this.isAlive) return;
    const before = this.health;
    this.health = Math.min(this.maxHealth, this.health + amount);
    if (!silent && this.health > before) this.game.hud?.flashHeal();
    this.game.hud?.setHealth(this);
  }

  addArmor(amount, cap = 100) {
    if (!this.isAlive) return;
    this.armor = Math.min(cap, this.armor + amount);
    this.game.hud?.setHealth(this);
  }

  takeDamage(amount, attacker, info = {}) {
    if (!this.isAlive) return { damage: 0, killed: false };
    const reduction = 1 - (this.damageReduction || 0);
    let dmg = amount * reduction;
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.66);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    dmg = Math.max(1, Math.round(dmg));
    this.health -= dmg;
    this.lastDamageAt = this.game.elapsed;
    this.abilities.onDamaged(dmg, attacker);
    this.shake = Math.min(2.2, this.shake + dmg / 42);
    this.game.hud?.damageDirection?.(attacker ? attacker.position : null);
    if (this.health <= 0) {
      this.health = 0;
      this.die(attacker, info);
      return { damage: dmg, killed: true };
    }
    this.game.hud.setHealth(this);
    this.game.audio.sfx('hurt');
    return { damage: dmg, killed: false };
  }

  die(attacker, info = {}) {
    this.isAlive = false;
    this.deaths += 1;
    this.deathTime = 0;
    this.velocity.set(0, 0, 0);
    this.viewGroup.visible = false;
    this.game.hud.showDeath(attacker, this);
    this.game.onCombatantDeath(this, attacker, info);
    this.game.audio.sfx('hurt');
  }

  get movementSpeed() {
    return this.sprinting ? this.runSpeed : this.moveSpeed;
  }
}

import * as THREE from 'three';
import { CharacterModel, createWeaponModel } from './CharacterFactory.js';
import { WeaponController } from './WeaponController.js';
import { AbilityController } from './AbilityController.js';

const _v = new THREE.Vector3();
const _v2 = new THREE.Vector3();

function makeNameplate(name, team) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: true, depthWrite: false, sizeAttenuation: true });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(2.1, 0.525, 1);
  const update = (health, maxHealth, color) => {
    ctx.clearRect(0, 0, 512, 128);
    ctx.textAlign = 'center';
    ctx.font = '600 34px "Space Grotesk", sans-serif';
    ctx.shadowColor = 'rgba(0,0,0,0.8)';
    ctx.shadowBlur = 8;
    ctx.fillStyle = color;
    ctx.fillText(name, 256, 46);
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(3,8,12,0.75)';
    ctx.roundRect?.(72, 66, 368, 16, 8);
    ctx.fillRect(72, 66, 368, 16);
    const pct = Math.max(0, health / maxHealth);
    ctx.fillStyle = team === 'attackers' ? '#ff6347' : '#4adfff';
    ctx.fillRect(74, 68, 364 * pct, 12);
    ctx.strokeStyle = 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 1;
    ctx.strokeRect(72, 66, 368, 16);
    texture.needsUpdate = true;
  };
  return { sprite, texture, update, material: mat };
}

export class Bot {
  constructor(data, team, game, index = 0, primaryWeapon = 'rifle') {
    this.data = data;
    this.character = data;
    this.team = team;
    this.game = game;
    this.isPlayer = false;
    this.name = data.shortName;
    this.index = index;
    this.position = new THREE.Vector3();
    this.velocity = new THREE.Vector3();
    this.yaw = team === 'attackers' ? 0 : Math.PI;
    this.health = 100;
    this.maxHealth = 100;
    this.armor = 0;
    this.maxArmor = 100;
    this.isAlive = true;
    this.kills = 0;
    this.deaths = 0;
    this.eyeHeight = 1.62;
    this.radius = 0.36;
    this.speedMultiplier = 1;
    this.fireRateMultiplier = 1;
    this.damageMultiplier = 0.72;
    this.reloadMultiplier = 1;
    this.damageReduction = 0;
    this.bonusArmor = 0;
    this.revealUntil = 0;
    this.stunUntil = 0;
    this.slowUntil = 0;
    this.slowFactor = 1;
    this.speedBoostUntil = 0;
    this.reductionUntil = 0;
    this.reaction = 0.28;
    this.accuracy = 2.2;
    this.path = [];
    this.pathIndex = 0;
    this.destination = null;
    this.repathTimer = 0;
    this.thinkTimer = Math.random() * 0.25;
    this.target = null;
    this.lastSeen = -10;
    this.lastAttacker = null;
    this.combatTimer = 0;
    this.stuckTimer = 0;
    this.lastPos = new THREE.Vector3();
    this.burstTimer = 0;
    this.burstShots = 0;
    this.abilityTimer = 5 + Math.random() * 8;
    this.specialTimer = 18 + Math.random() * 14;
    this.deathTime = 0;
    this.deathRotation = 0;
    this.planting = 0;
    this.defusing = 0;
    this.site = index % 2 === 0 ? 'A' : 'B';
    this.holdOffset = new THREE.Vector3((Math.random() - 0.5) * 5, 0, (Math.random() - 0.5) * 4);
    this.nameplate = makeNameplate(this.name, team);
    this.nameplate.sprite.position.y = 2.15;
    this.nameplate.sprite.userData.bot = this;
    this.game.scene.add(this.nameplate.sprite);
    this.model = new CharacterModel(data, { menuPose: false });
    this.model.group.rotation.y = this.yaw;
    this.game.scene.add(this.model.group);
    this.weapon = new WeaponController(this, primaryWeapon, game);
    this.abilities = new AbilityController(this, data, game);
    this.buildGun();
    this.nameplate.update(100, 100, team === 'attackers' ? '#ff8c76' : '#8ee8ff');
  }

  buildGun() {
    this.gun = createWeaponModel(this.weapon.weapon.id, 0.62);
    this.gun.rotation.y = Math.PI;
    this.gun.position.set(0.3, 1.16, 0.18);
    this.model.group.add(this.gun);
    this.gun.traverse((m) => { if (m.isMesh) m.castShadow = true; });
  }

  resetForRound(spawn) {
    this.position.copy(spawn);
    this.velocity.set(0, 0, 0);
    this.health = 100;
    this.armor = this.bonusArmor || 0;
    this.isAlive = true;
    this.yaw = this.team === 'attackers' ? 0 : Math.PI;
    this.weapon.reset();
    this.abilities.resetRound();
    this.target = null;
    this.lastAttacker = null;
    this.path = [];
    this.pathIndex = 0;
    this.destination = null;
    this.repathTimer = 0;
    this.planting = 0;
    this.defusing = 0;
    this.deathTime = 0;
    this.deathRotation = 0;
    this.stunUntil = 0;
    this.slowUntil = 0;
    this.revealUntil = 0;
    this.model.group.visible = true;
    this.model.group.rotation.set(0, this.yaw, 0);
    this.gun.visible = true;
    this.nameplate.sprite.visible = true;
    this.nameplate.material.depthTest = true;
    this.nameplate.update(this.health, this.maxHealth, this.team === 'attackers' ? '#ff8c76' : '#8ee8ff');
    if (this.team === 'attackers') {
      this.site = Math.random() > 0.5 ? 'A' : 'B';
    }
    this.holdOffset.set((Math.random() - 0.5) * 5, 0, (Math.random() - 0.5) * 4);
    this.model.group.position.copy(this.position);
  }

  getEyePosition() {
    return this.position.clone().setY(this.position.y + this.eyeHeight);
  }

  getChestPosition() {
    return this.position.clone().setY(this.position.y + 1.08);
  }

  getHeadPosition() {
    return this.position.clone().setY(this.position.y + 1.64);
  }

  getAimDirection() {
    return _v.set(Math.sin(this.yaw), 0, Math.cos(this.yaw)).clone().normalize();
  }

  think() {
    const enemies = this.game.getCombatants().filter((c) => c.team !== this.team && c.isAlive);
    let best = null;
    let bestScore = Infinity;
    const eye = this.getEyePosition();
    const forward = _v2.set(Math.sin(this.yaw), 0, Math.cos(this.yaw));
    for (const enemy of enemies) {
      const targetPos = enemy.getChestPosition();
      const to = targetPos.clone().sub(eye);
      const dist = to.length();
      if (dist > 52) continue;
      to.normalize();
      const dot = forward.dot(to);
      if (dot < -0.15) continue;
      if (!this.game.world.hasLineOfSight(eye, targetPos)) continue;
      let score = dist * (dot < 0.3 ? 1.6 : 1);
      if (enemy === this.target) score *= 0.55;
      if (enemy.revealUntil > this.game.elapsed) score *= 0.85;
      if (score < bestScore) {
        bestScore = score;
        best = enemy;
      }
    }
    if (best) {
      this.target = best;
      this.lastSeen = this.game.elapsed;
      this.combatTimer = 0.8;
      this.reaction = Math.max(0.05, 0.26 - (this.abilities.activeCooldown <= 0 ? 0.02 : 0));
    } else if (this.target && (!this.target.isAlive || this.game.elapsed - this.lastSeen > 3)) {
      this.target = null;
    }
    if (!this.target && this.lastAttacker?.isAlive && this.game.elapsed - this.lastSeen < 4) {
      // Investigate an unseen attacker.
      this.setDestination(this.lastAttacker.position.clone());
    }
  }

  update(dt) {
    this.abilities.update(dt);
    this.weapon.update(dt);
    if (!this.isAlive) {
      this.deathTime += dt;
      this.deathRotation = Math.min(1, this.deathRotation + dt * 1.7);
      this.model.group.rotation.z = this.deathRotation * Math.PI * 0.48;
      this.model.group.position.y = this.position.y + this.deathRotation * 0.1;
      this.nameplate.sprite.visible = false;
      return;
    }
    this.stunUntil = Math.max(this.stunUntil || 0, 0);
    const stunned = this.game.elapsed < this.stunUntil;
    const slowed = this.game.elapsed < this.slowUntil;
    this.thinkTimer -= dt;
    if (this.thinkTimer <= 0) {
      this.thinkTimer = 0.18 + Math.random() * 0.1;
      this.think();
    }
    this.abilityTimer -= dt;
    this.specialTimer -= dt;
    if (this.abilityTimer <= 0 && this.abilities.activeReady) {
      this.abilityTimer = 6 + Math.random() * 10;
      if (this.target || this.health < 75 || Math.random() < 0.4) {
        this.abilities.useActive();
      }
    }
    if (this.specialTimer <= 0 && this.abilities.specialReady) {
      this.specialTimer = 18 + Math.random() * 15;
      if (this.target && (this.health < 65 || Math.random() < 0.28)) {
        this.abilities.useSpecial();
      }
    }

    const target = this.target;
    const hasTarget = target && target.isAlive && this.game.world.hasLineOfSight(this.getEyePosition(), target.getChestPosition());
    if (stunned) {
      this.weapon.triggerUp();
      this.target = null;
    } else if (hasTarget) {
      this.combatTimer -= dt;
      this.fightTarget(dt);
    } else {
      this.combatTimer = Math.max(0, this.combatTimer - dt);
      this.followObjective(dt);
      if (this.weapon.triggerHeld && !this.weapon.reloading) this.weapon.triggerUp();
    }
    this.applyMovement(dt, stunned ? 0.12 : slowed ? this.slowFactor : 1);
    this.updateVisuals(dt);

    // Interaction progress is managed by the bomb controller.
    if (this.game.bombController) {
      this.game.bombController.botInteract(this, dt);
    }
    if (this.game.elapsed > this.speedBoostUntil && this.speedMultiplier > 1.12) this.speedMultiplier = 1.12;
    if (this.game.elapsed > this.reductionUntil && this.damageReduction && this.data.id !== 'orquidea') this.damageReduction = 0;
  }

  fightTarget(dt) {
    const target = this.target;
    if (!target) return;
    const eye = this.getEyePosition();
    const aim = target.getChestPosition().clone();
    aim.y += Math.random() * 0.2 - 0.1;
    const dir = aim.sub(eye).normalize();
    const desiredYaw = Math.atan2(dir.x, dir.z);
    this.yaw = lerpAngle(this.yaw, desiredYaw, Math.min(1, dt * 8));
    const dist = this.position.distanceTo(target.position);
    const ideal = this.weapon.weapon.id === 'shotgun' ? 5 : this.weapon.weapon.id === 'sniper' ? 22 : 13;
    // Strafe around the target at a comfortable range.
    const toTarget = target.position.clone().sub(this.position);
    toTarget.y = 0;
    const d = toTarget.length();
    toTarget.normalize();
    const perp = new THREE.Vector3(-toTarget.z, 0, toTarget.x).multiplyScalar(Math.sin(this.game.elapsed * 0.9 + this.index) > 0 ? 1 : -1);
    let moveDir = new THREE.Vector3();
    if (d > ideal + 4) moveDir.add(toTarget);
    else if (d < ideal - 3) moveDir.sub(toTarget);
    moveDir.addScaledVector(perp, 0.62);
    moveDir.normalize();
    this.velocity.x = THREE.MathUtils.damp(this.velocity.x, moveDir.x * 3.8 * (this.speedMultiplier || 1), 7, dt);
    this.velocity.z = THREE.MathUtils.damp(this.velocity.z, moveDir.z * 3.8 * (this.speedMultiplier || 1), 7, dt);

    if (this.reaction > 0) {
      this.reaction -= dt;
    } else if (this.reaction <= 0) {
      const weapon = this.weapon.weapon;
      const aimDir = _v.set(Math.sin(this.yaw), 0, Math.cos(this.yaw)).clone().normalize();
      aimDir.y = dir.y * 0.9;
      aimDir.normalize();
      if (this.burstTimer > 0) {
        this.burstTimer -= dt;
      } else {
        this.weapon.triggerDown();
        if (weapon.automatic) {
          if (Math.random() < dt * 7) {
            this.weapon.triggerHeld = true;
          }
        }
      }
      // Bot fire uses direct aim but still receives weapon spread and accuracy penalty.
      if (this.weapon.triggerHeld && this.weapon.fireTimer <= 0) {
        this.weapon.tryFire(eye, aimDir);
        this.weapon.triggerHeld = false;
        if (Math.random() < 0.22) this.burstTimer = 0.25 + Math.random() * 0.45;
      }
    }
  }

  followObjective(dt) {
    const bc = this.game.bombController;
    if (!bc) return;
    let goal = null;
    if (bc.state === 'Planted' || bc.state === 'Defusing' || bc.state === 'Planting') {
      const bombPos = bc.position || this.game.world.sites[this.site].center;
      if (this.team === 'defenders') {
        goal = bombPos.clone();
      } else {
        const angle = this.game.elapsed * 0.35 + this.index;
        goal = bombPos.clone().add(new THREE.Vector3(Math.cos(angle) * 3.2, 0, Math.sin(angle) * 3.2));
      }
    } else if (this.team === 'attackers') {
      const site = this.game.world.sites[this.site];
      goal = site.center.clone().add(this.holdOffset);
      if (this.position.distanceTo(goal) < 2.8) {
        // Slow down, cover angles, allow the interaction system to plant.
        goal = site.center.clone().add(new THREE.Vector3(Math.cos(this.index * 2.4) * 4, 0, Math.sin(this.index * 2.4) * 4));
        if (this.game.elapsed % 5 < dt) this.holdOffset.set((Math.random() - 0.5) * 5, 0, (Math.random() - 0.5) * 4);
      }
    } else {
      const site = this.game.world.sites[this.site];
      goal = site.center.clone().add(new THREE.Vector3(-4 + (this.index % 3) * 4, 0, 3 + (this.index % 2) * 3));
      if (this.position.distanceTo(goal) < 2.2) {
        goal = site.center.clone().add(new THREE.Vector3(Math.cos(this.game.elapsed * 0.2 + this.index) * 4.5, 0, Math.sin(this.game.elapsed * 0.2 + this.index) * 4.5));
      }
    }
    if (goal) this.setDestination(goal);
    this.followPath(dt);
  }

  setDestination(goal) {
    if (!goal) return;
    if (!this.destination || this.destination.distanceTo(goal) > 2.2) {
      this.destination = goal.clone();
      this.path = this.game.world.findPath(this.position, goal);
      this.pathIndex = Math.min(1, this.path.length - 1);
      this.repathTimer = 1.4;
    }
  }

  followPath(dt) {
    this.repathTimer -= dt;
    if (!this.path.length) {
      this.velocity.x = THREE.MathUtils.damp(this.velocity.x, 0, 8, dt);
      this.velocity.z = THREE.MathUtils.damp(this.velocity.z, 0, 8, dt);
      return;
    }
    if (this.pathIndex >= this.path.length) {
      this.velocity.x = THREE.MathUtils.damp(this.velocity.x, 0, 8, dt);
      this.velocity.z = THREE.MathUtils.damp(this.velocity.z, 0, 8, dt);
      return;
    }
    let waypoint = this.path[this.pathIndex];
    let to = waypoint.clone().sub(this.position);
    if (to.length() < 0.8) {
      this.pathIndex += 1;
      if (this.pathIndex >= this.path.length) return;
      waypoint = this.path[this.pathIndex];
      to = waypoint.clone().sub(this.position);
    }
    to.y = 0;
    const dist = to.length();
    if (dist < 0.1) return;
    to.normalize();
    const speed = (this.team === 'attackers' ? 5.4 : 5.0) * (this.speedMultiplier || 1) * (this.game.elapsed < this.speedBoostUntil ? 1.18 : 1);
    this.velocity.x = THREE.MathUtils.damp(this.velocity.x, to.x * speed, 6, dt);
    this.velocity.z = THREE.MathUtils.damp(this.velocity.z, to.z * speed, 6, dt);
    if (!this.target && !this.game.world.smokes.some((s) => s.center.distanceTo(this.position) < s.radius)) {
      const desiredYaw = Math.atan2(to.x, to.z);
      this.yaw = lerpAngle(this.yaw, desiredYaw, Math.min(1, dt * 5));
    }
    if (this.repathTimer <= 0) {
      this.repathTimer = 1.8;
      if (this.destination && this.destination.distanceTo(this.path[this.path.length - 1]) > 2.5) {
        this.path = this.game.world.findPath(this.position, this.destination);
        this.pathIndex = Math.min(1, this.path.length - 1);
      }
    }
  }

  applyMovement(dt, slow = 1) {
    this.game.world.moveCircle(this.position, this.velocity.x * dt * slow, this.velocity.z * dt * slow, this.radius);
    // Keep bots out of one another's personal space.
    for (const other of this.game.getCombatants()) {
      if (other === this || !other.isAlive) continue;
      const dx = this.position.x - other.position.x;
      const dz = this.position.z - other.position.z;
      const d = Math.hypot(dx, dz);
      if (d > 0.01 && d < 0.85) {
        const push = (0.85 - d) * 0.5;
        this.position.x += (dx / d) * push;
        this.position.z += (dz / d) * push;
      }
    }
    this.position.y = 0;
    this.model.group.position.copy(this.position);
    this.model.group.rotation.y = this.yaw;
    this.nameplate.sprite.position.set(this.position.x, this.position.y + 2.18, this.position.z);
  }

  updateVisuals(dt) {
    const speed = Math.hypot(this.velocity.x, this.velocity.z);
    this.model.update(dt, speed, this.combatTimer > 0);
    this.model.group.position.copy(this.position);
    this.model.group.rotation.y = this.yaw;
    if (this.combatTimer > 0) {
      this.model.rightArm.rotation.x = -1.1;
      this.model.leftArm.rotation.x = -1.05;
      this.model.rightArm.rotation.z = -0.2;
      this.model.leftArm.rotation.z = 0.15;
    }
    this.gun.position.set(0.3, 1.2, 0.24);
    const revealed = this.revealUntil > this.game.elapsed;
    this.nameplate.material.depthTest = !revealed;
    this.nameplate.sprite.material.opacity = revealed ? 1 : 0.92;
    if (revealed) {
      const pulse = 0.8 + Math.sin(this.game.elapsed * 8 + this.index) * 0.2;
      this.nameplate.sprite.scale.set(2.1 * pulse, 0.525 * pulse, 1);
    } else {
      this.nameplate.sprite.scale.set(2.1, 0.525, 1);
    }
    if (!this.isAlive) this.nameplate.sprite.visible = false;
    if (Math.random() < dt * 2) this.nameplate.update(this.health, this.maxHealth, this.team === 'attackers' ? '#ff8c76' : '#8ee8ff');
  }

  onShotFired(weapon) {
    const muzzle = this.getChestPosition().addScaledVector(this.getAimDirection(), 0.6);
    this.game.effects.muzzle(muzzle, this.getAimDirection(), weapon.color);
    this.game.lastEnemyShot = { shooter: this, team: this.team, time: this.game.elapsed };
    if (this.position.distanceTo(this.game.player.position) < 34) this.game.audio.sfx(weapon.id, 0.5);
  }

  onReloadStart() {
    this.weapon.triggerHeld = false;
  }

  onReloadEnd() {}

  onDryFire() {}

  onAbilityUsed(ability, special) {
    if (this.position.distanceTo(this.game.player.position) < 20) this.game.audio.sfx('ability');
  }

  heal(amount) {
    if (!this.isAlive) return;
    this.health = Math.min(this.maxHealth, this.health + amount);
    this.nameplate.update(this.health, this.maxHealth, this.team === 'attackers' ? '#ff8c76' : '#8ee8ff');
  }

  addArmor(amount, cap = 100) {
    if (!this.isAlive) return;
    this.armor = Math.min(cap, this.armor + amount);
  }

  takeDamage(amount, attacker, info = {}) {
    if (!this.isAlive) return { damage: 0, killed: false };
    let dmg = amount * (1 - (this.damageReduction || 0));
    if (this.armor > 0) {
      const absorbed = Math.min(this.armor, dmg * 0.66);
      this.armor -= absorbed;
      dmg -= absorbed;
    }
    dmg = Math.max(1, Math.round(dmg));
    this.health -= dmg;
    this.abilities.onDamaged(dmg, attacker);
    if (attacker) {
      this.lastAttacker = attacker;
      this.lastSeen = Math.max(this.lastSeen, this.game.elapsed - 2);
      if (!this.target || Math.random() < 0.6) {
        this.target = attacker;
        this.reaction = 0.12;
        this.yaw = Math.atan2(attacker.position.x - this.position.x, attacker.position.z - this.position.z);
      }
    }
    this.nameplate.update(this.health, this.maxHealth, this.team === 'attackers' ? '#ff8c76' : '#8ee8ff');
    if (this.health <= 0) {
      this.health = 0;
      this.die(attacker, info);
      return { damage: dmg, killed: true };
    }
    return { damage: dmg, killed: false };
  }

  die(attacker, info = {}) {
    this.isAlive = false;
    this.deaths += 1;
    this.deathTime = 0;
    this.deathRotation = 0;
    this.velocity.set(0, 0, 0);
    this.nameplate.sprite.visible = false;
    this.gun.visible = false;
    this.game.onCombatantDeath(this, attacker, info);
  }

  get movementSpeed() {
    return Math.hypot(this.velocity.x, this.velocity.z);
  }
}

function lerpAngle(a, b, t) {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}

import * as THREE from 'three';

export const BOMB_STATE = {
  NOT_PLANTED: 'NotPlanted',
  PLANTING: 'Planting',
  PLANTED: 'Planted',
  DEFUSING: 'Defusing',
  DEFUSED: 'Defused',
  EXPLODED: 'Exploded'
};

const PLANT_TIME = 4.0;
const DEFUSE_TIME = 5.2;
const BOMB_TIME = 40;

export class BombController {
  constructor(game) {
    this.game = game;
    this.state = BOMB_STATE.NOT_PLANTED;
    this.position = null;
    this.bombMesh = null;
    this.light = null;
    this.timer = 0;
    this.plantProgress = 0;
    this.defuseProgress = 0;
    this.plantSite = null;
    this.playerPlanting = false;
    this.playerDefusing = false;
    this.botPlanter = null;
    this.botDefuser = null;
    this.lastBeep = 0;
    this.defuserHold = 0;
    this.reset();
  }

  reset() {
    if (this.bombMesh) {
      this.game.scene.remove(this.bombMesh);
      this.disposeGroup(this.bombMesh);
      this.bombMesh = null;
    }
    this.state = BOMB_STATE.NOT_PLANTED;
    this.position = null;
    this.timer = 0;
    this.plantProgress = 0;
    this.defuseProgress = 0;
    this.plantSite = null;
    this.playerPlanting = false;
    this.playerDefusing = false;
    this.botPlanter = null;
    this.botDefuser = null;
    this.lastBeep = 0;
    this.defuseTimer = 0;
    this.plantTimer = 0;
    this.game.hud?.setBombStatus(null);
    this.game.hud?.setPrompt(null);
  }

  disposeGroup(group) {
    group.traverse?.((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
        else obj.material.dispose();
      }
    });
  }

  getSiteAt(position) {
    if (!position) return null;
    for (const site of Object.values(this.game.world.sites)) {
      if (position.distanceTo(site.center) < site.radius - 0.35) return site;
    }
    return null;
  }

  plant(planter, site) {
    this.state = BOMB_STATE.PLANTED;
    this.plantSite = site;
    this.position = planter.position.clone();
    this.position.y = 0;
    this.timer = BOMB_TIME;
    this.plantProgress = 0;
    this.defuseProgress = 0;
    this.playerPlanting = false;
    this.playerDefusing = false;
    this.buildBombMesh();
    this.game.audio.sfx('plant');
    this.game.hud.setBombStatus({ state: 'Planted', timer: this.timer, site: site.id });
    this.game.hud.notify(`BOMBA PLANTADA NO SITE ${site.id}`, '#ff633f', 4);
    this.game.roundManager?.onBombPlanted?.(site);
    this.game.addKillfeed?.('BOMBA', `plantada no site ${site.id}`, '#ff633f');
  }

  defuse(defuser) {
    this.state = BOMB_STATE.DEFUSED;
    this.defuseProgress = DEFUSE_TIME;
    this.playerDefusing = false;
    this.game.hud.setBombStatus({ state: 'Defused', timer: 0, site: this.plantSite?.id });
    this.game.hud.notify('BOMBA DESARMADA', '#4adfff', 4);
    this.game.audio.sfx('defuse');
    this.game.roundManager?.onBombDefused?.(defuser);
    this.game.addKillfeed?.('DESARME', 'bomba neutralizada', '#4adfff');
    this.fadeBomb();
  }

  explode() {
    if (this.state === BOMB_STATE.EXPLODED || this.state === BOMB_STATE.DEFUSED) return;
    this.state = BOMB_STATE.EXPLODED;
    this.game.effects.explosion(this.position || new THREE.Vector3(), 10);
    this.game.audio.sfx('explosion');
    this.game.hud.flashExplosion?.();
    this.game.roundManager?.onBombExploded?.();
    this.fadeBomb();
  }

  fadeBomb() {
    if (!this.bombMesh) return;
    this.bombMesh.children.forEach((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0.35;
      }
    });
    if (this.light) this.light.intensity = 0;
  }

  buildBombMesh() {
    if (this.bombMesh) this.game.scene.remove(this.bombMesh);
    const group = new THREE.Group();
    group.position.copy(this.position);
    const bodyMat = new THREE.MeshStandardMaterial({ color: '#20252b', roughness: 0.45, metalness: 0.72 });
    const dark = new THREE.MeshStandardMaterial({ color: '#0b0e11', roughness: 0.8 });
    const red = new THREE.MeshBasicMaterial({ color: '#ff3b2f' });
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.22, 0.32), bodyMat);
    body.position.y = 0.18;
    body.castShadow = true;
    group.add(body);
    const screen = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.08, 0.012), red);
    screen.position.set(0, 0.23, 0.167);
    group.add(screen);
    for (let i = 0; i < 3; i++) {
      const wire = new THREE.Mesh(new THREE.TorusGeometry(0.13 + i * 0.015, 0.008, 4, 14, Math.PI), new THREE.MeshBasicMaterial({ color: i === 1 ? '#ffd15c' : '#ff3b2f' }));
      wire.position.set(0, 0.28, 0);
      wire.rotation.x = Math.PI / 2;
      wire.rotation.z = i * 0.8;
      group.add(wire);
    }
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.01, 0.01, 0.28, 5), dark);
    antenna.position.set(0.16, 0.42, -0.06);
    group.add(antenna);
    const tip = new THREE.Mesh(new THREE.SphereGeometry(0.025, 6, 5), red);
    tip.position.set(0.16, 0.57, -0.06);
    group.add(tip);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.55, 0.6, 32), new THREE.MeshBasicMaterial({ color: '#ff3b2f', transparent: true, opacity: 0.35, side: THREE.DoubleSide }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.012;
    group.add(ring);
    const light = new THREE.PointLight('#ff3b2f', 5, 8, 2);
    light.position.set(0, 0.55, 0);
    group.add(light);
    this.light = light;
    this.screen = screen;
    this.bombRing = ring;
    this.game.scene.add(group);
    this.bombMesh = group;
  }

  update(dt) {
    if (this.state === BOMB_STATE.PLANTED) {
      this.timer -= dt;
      this.game.hud.setBombStatus({ state: 'Planted', timer: this.timer, site: this.plantSite?.id });
      const beepInterval = THREE.MathUtils.clamp(this.timer / 40, 0.12, 1) * 0.85;
      if (this.game.elapsed - this.lastBeep > beepInterval) {
        this.lastBeep = this.game.elapsed;
        this.game.audio.sfx('beep');
        if (this.screen) this.screen.material.color.set('#ffffff');
        setTimeout(() => {
          if (this.screen) this.screen.material.color.set('#ff3b2f');
        }, 80);
      }
      if (this.bombRing) this.bombRing.material.opacity = 0.22 + Math.abs(Math.sin(this.game.elapsed * 3)) * 0.3;
      if (this.light) this.light.intensity = 3 + Math.abs(Math.sin(this.game.elapsed * 4)) * 8;
      if (this.timer <= 0) this.explode();
      this.updatePlayerDefuse(dt);
      return;
    }
    if (this.state === BOMB_STATE.DEFUSED || this.state === BOMB_STATE.EXPLODED) return;
    this.updatePlayerPlant(dt);
  }

  updatePlayerPlant(dt) {
    const player = this.game.player;
    if (!player?.isAlive || player.team !== 'attackers' || !this.game.roundManager.canPlant()) {
      this.playerPlanting = false;
      if (this.plantProgress > 0) this.plantProgress = Math.max(0, this.plantProgress - dt * 1.5);
      return;
    }
    const site = this.getSiteAt(player.position);
    const hasInput = this.game.input.interactHeld && this.game.input.enabled;
    const canPlant = !!site && hasInput;
    if (canPlant) {
      if (!this.playerPlanting) {
        this.playerPlanting = true;
        this.plantSite = site;
        this.plantStart = player.position.clone();
        this.game.hud.notify(`PLANTANDO NO SITE ${site.id}`, '#ff633f');
      }
      if (player.position.distanceTo(this.plantStart) > 1.2) {
        this.plantProgress = 0;
        this.plantStart = player.position.clone();
      }
      this.plantProgress += dt;
      this.game.hud.setPrompt({
        text: `PLANTANDO BOMBA · SITE ${site.id}`,
        sub: 'MANTENHA A POSIÇÃO',
        progress: this.plantProgress / PLANT_TIME,
        color: '#ff633f',
        key: 'E'
      });
      if (Math.random() < dt * 3) this.game.audio.sfx('beep');
      if (this.plantProgress >= PLANT_TIME) {
        this.plant(player, site);
      }
    } else {
      if (this.playerPlanting) {
        this.game.hud.setPrompt(null);
        this.playerPlanting = false;
      }
      if (this.plantProgress > 0) this.plantProgress = Math.max(0, this.plantProgress - dt * 1.8);
      if (site && this.plantProgress <= 0) {
        this.game.hud.setPrompt({
          text: `SEGURE E PARA PLANTAR · SITE ${site.id}`,
          sub: 'A BOMBA ESTÁ PRONTA',
          progress: null,
          color: '#ff633f',
          key: 'E'
        });
      }
    }
  }

  updatePlayerDefuse(dt) {
    const player = this.game.player;
    if (!player?.isAlive || player.team !== 'defenders' || !this.position || !this.game.roundManager.canDefuse()) {
      this.playerDefusing = false;
      this.defuseProgress = Math.max(0, this.defuseProgress - dt * 1.8);
      return;
    }
    const near = player.position.distanceTo(this.position) < 2.3;
    const hasInput = this.game.input.interactHeld && this.game.input.enabled;
    if (near && hasInput) {
      if (!this.playerDefusing) {
        this.playerDefusing = true;
        this.game.hud.notify('DESARMANDO BOMBA', '#4adfff');
      }
      this.defuseProgress += dt;
      this.game.hud.setPrompt({
        text: 'DESARMANDO BOMBA',
        sub: 'MANTENHA A POSIÇÃO',
        progress: this.defuseProgress / DEFUSE_TIME,
        color: '#4adfff',
        key: 'E'
      });
      this.game.audio.sfx('defuse');
      if (this.defuseProgress >= DEFUSE_TIME) this.defuse(player);
    } else {
      if (this.playerDefusing) {
        this.playerDefusing = false;
        this.game.hud.setPrompt(null);
      }
      if (this.defuseProgress > 0) this.defuseProgress = Math.max(0, this.defuseProgress - dt * 1.8);
      if (near && this.defuseProgress <= 0) {
        this.game.hud.setPrompt({
          text: 'SEGURE E PARA DESARMAR',
          sub: `SITE ${this.plantSite?.id || ''} · ${Math.ceil(this.timer)}s`,
          progress: null,
          color: '#4adfff',
          key: 'E'
        });
      }
    }
  }

  botInteract(bot, dt) {
    if (!bot.isAlive) {
      if (this.botPlanter === bot) { this.botPlanter = null; this.plantProgress = 0; }
      if (this.botDefuser === bot) { this.botDefuser = null; this.defuseProgress = 0; }
      return;
    }
    if (this.state === BOMB_STATE.NOT_PLANTED && bot.team === 'attackers' && this.game.roundManager.canPlant()) {
      const site = this.getSiteAt(bot.position);
      if (site) {
        const inCombat = bot.target && bot.target.isAlive && bot.game.elapsed - bot.lastSeen < 1;
        if (!inCombat && (!this.botPlanter || !this.botPlanter.isAlive)) {
          this.botPlanter = bot;
          this.plantSite = site;
        }
        if (this.botPlanter === bot) {
          if (inCombat || bot.position.distanceTo(site.center) > site.radius) {
            this.botPlanter = null;
            this.plantProgress = 0;
            return;
          }
          this.plantProgress += dt;
          if (this.plantProgress > 0.6 && this.game.elapsed - (this.lastBotNotify || 0) > 2) {
            this.lastBotNotify = this.game.elapsed;
            this.game.hud.notify(`${bot.name} ESTÁ PLANTANDO · SITE ${site.id}`, '#ff633f');
          }
          if (this.plantProgress >= PLANT_TIME) {
            this.plant(bot, site);
          }
        }
      } else if (this.botPlanter === bot) {
        this.botPlanter = null;
        this.plantProgress = 0;
      }
    }
    if (this.state === BOMB_STATE.PLANTED && bot.team === 'defenders' && this.game.roundManager.canDefuse()) {
      const near = this.position && bot.position.distanceTo(this.position) < 2.2;
      if (near) {
        if (!this.botDefuser || !this.botDefuser.isAlive) this.botDefuser = bot;
        if (this.botDefuser === bot) {
          this.defuseProgress += dt;
          this.game.audio.sfx('defuse');
          this.game.hud.setBombStatus({ state: 'Defusing', timer: this.timer, site: this.plantSite?.id, defuse: this.defuseProgress / DEFUSE_TIME, defuser: bot.name });
          if (this.defuseProgress >= DEFUSE_TIME) this.defuse(bot);
        }
      } else if (this.botDefuser === bot) {
        this.botDefuser = null;
        this.defuseProgress = Math.max(0, this.defuseProgress - dt * 1.8);
      }
    }
  }

  onRoundReset() {
    this.reset();
  }
}

export class TeamManager {
  constructor() {
    this.teams = {
      attackers: { id: 'attackers', label: 'ATTACKERS', color: '#ff633f', members: [], score: 0 },
      defenders: { id: 'defenders', label: 'DEFENDERS', color: '#4adfff', members: [], score: 0 }
    };
  }

  reset() {
    this.teams.attackers.score = 0;
    this.teams.defenders.score = 0;
    for (const team of Object.values(this.teams)) {
      for (const m of team.members) {
        m.kills = 0;
        m.deaths = 0;
      }
    }
  }

  register(combatant, teamId) {
    const team = this.teams[teamId];
    if (!team) return;
    team.members.push(combatant);
    combatant.team = teamId;
  }

  getTeam(id) {
    return this.teams[id];
  }

  getAttackers() {
    return this.teams.attackers.members;
  }

  getDefenders() {
    return this.teams.defenders.members;
  }

  get attackersAlive() {
    return this.teams.attackers.members.filter((m) => m.isAlive).length;
  }

  get defendersAlive() {
    return this.teams.defenders.members.filter((m) => m.isAlive).length;
  }

  get attackersScore() {
    return this.teams.attackers.score;
  }

  get defendersScore() {
    return this.teams.defenders.score;
  }

  addScore(teamId) {
    this.teams[teamId].score += 1;
  }

  getMemberCount(teamId) {
    return this.teams[teamId].members.length;
  }

  getScoreboard() {
    return [...this.teams.attackers.members, ...this.teams.defenders.members]
      .map((m) => ({ name: m.name, team: m.team, kills: m.kills || 0, deaths: m.deaths || 0, isPlayer: !!m.isPlayer, character: m.character }))
      .sort((a, b) => b.kills - a.kills);
  }
}

import { BOMB_STATE } from './BombController.js';

export const ROUND_STATE = {
  WAITING: 'WaitingForPlayers',
  PREPARING: 'PreparingRound',
  STARTING: 'RoundStarting',
  ACTIVE: 'RoundActive',
  BOMB_PLANTED: 'BombPlanted',
  ENDING: 'RoundEnding',
  FINISHED: 'MatchFinished'
};

const PREP_TIME = 2.2;
const START_TIME = 3.0;
const END_TIME = 4.8;
const ROUND_TIME = 90;

export class RoundManager {
  constructor(game, options = {}) {
    this.game = game;
    this.winTarget = options.winTarget || 4;
    this.roundNumber = 0;
    this.state = ROUND_STATE.WAITING;
    this.phaseTimer = 0;
    this.roundTime = ROUND_TIME;
    this.lastWinner = null;
    this.lastReason = '';
    this.matchWinner = null;
    this.checkTimer = 0;
    this.roundActive = false;
  }

  start() {
    this.roundNumber = 1;
    this.phaseTimer = 1.0;
    this.state = ROUND_STATE.WAITING;
    this.game.hud.showRoundBanner({
      kicker: 'VEM COMER · DOCA ZERO',
      title: 'PREPARANDO OPERAÇÃO',
      sub: '4 vs 4 · PRIMEIRO A 4 ROUNDS',
      color: '#ffb24a',
      time: 1
    });
    this.game.audio.setMode('game');
  }

  update(dt) {
    if (this.state === ROUND_STATE.WAITING) {
      this.phaseTimer -= dt;
      if (this.phaseTimer <= 0) this.prepareRound();
      return;
    }
    if (this.state === ROUND_STATE.PREPARING) {
      this.phaseTimer -= dt;
      if (this.phaseTimer <= 0) this.beginStarting();
      return;
    }
    if (this.state === ROUND_STATE.STARTING) {
      this.phaseTimer -= dt;
      this.game.hud.setCountdown(Math.max(0, Math.ceil(this.phaseTimer)));
      if (this.phaseTimer <= 0) this.beginActive();
      return;
    }
    if (this.state === ROUND_STATE.ACTIVE || this.state === ROUND_STATE.BOMB_PLANTED) {
      this.roundTime = Math.max(0, this.roundTime - dt);
      this.checkTimer -= dt;
      if (this.checkTimer <= 0) {
        this.checkTimer = 0.35;
        this.checkElimination();
      }
      if (this.state === ROUND_STATE.ACTIVE && this.roundTime <= 0) {
        this.endRound('defenders', 'TEMPO ESGOTADO');
      }
      this.game.hud.updateRound(this);
      return;
    }
    if (this.state === ROUND_STATE.ENDING) {
      this.phaseTimer -= dt;
      this.game.hud.updateRound(this);
      if (this.phaseTimer <= 0) {
        if (this.game.teamManager.getTeam(this.lastWinner).score >= this.winTarget) {
          this.finishMatch(this.lastWinner);
        } else {
          this.roundNumber += 1;
          this.prepareRound();
        }
      }
      return;
    }
  }

  prepareRound() {
    this.state = ROUND_STATE.PREPARING;
    this.phaseTimer = PREP_TIME;
    this.roundTime = ROUND_TIME;
    this.roundActive = false;
    this.game.controlsEnabled = false;
    this.game.input.setEnabled(false);
    this.game.resetRound();
    this.game.hud.hideMatchResult();
    this.game.hud.setCountdown(null);
    this.game.hud.showRoundBanner({
      kicker: `ROUND ${this.roundNumber} · ${this.game.teamManager.attackersScore} — ${this.game.teamManager.defendersScore}`,
      title: 'PREPARE-SE',
      sub: this.game.player.team === 'attackers' ? 'ATAQUE · PLANTE A BOMBA NOS SITES A OU B' : 'DEFESA · IMPEÇA O PLANT E DESARME A BOMBA',
      color: this.game.player.team === 'attackers' ? '#ff633f' : '#4adfff',
      time: PREP_TIME
    });
  }

  beginStarting() {
    this.state = ROUND_STATE.STARTING;
    this.phaseTimer = START_TIME;
    this.game.hud.showRoundBanner({
      kicker: `ROUND ${this.roundNumber}`,
      title: '',
      sub: '',
      color: '#ffffff',
      time: 0
    });
  }

  beginActive() {
    this.state = ROUND_STATE.ACTIVE;
    this.roundActive = true;
    this.phaseTimer = 0;
    this.roundTime = ROUND_TIME;
    this.game.controlsEnabled = true;
    this.game.input.setEnabled(true);
    this.game.hud.setCountdown(null);
    this.game.hud.hideRoundBanner();
    this.game.audio.sfx('roundStart');
    this.game.hud.notify(this.game.player.team === 'attackers' ? 'ATAQUE · PLANTA A BOMBA' : 'DEFESA · PROTEGE OS SITES', this.game.player.team === 'attackers' ? '#ff633f' : '#4adfff', 3);
    this.game.hud.updateRound(this);
  }

  checkElimination() {
    const attackers = this.game.teamManager.attackersAlive;
    const defenders = this.game.teamManager.defendersAlive;
    if (defenders === 0 && this.state === ROUND_STATE.ACTIVE) {
      this.endRound('attackers', 'DEFESA ELIMINADA');
    } else if (defenders === 0 && this.state === ROUND_STATE.BOMB_PLANTED) {
      this.endRound('attackers', 'DEFESA ELIMINADA');
    } else if (attackers === 0 && this.state === ROUND_STATE.ACTIVE) {
      this.endRound('defenders', 'ATAQUE ELIMINADO');
    }
  }

  onBombPlanted(site) {
    this.state = ROUND_STATE.BOMB_PLANTED;
    this.game.controlsEnabled = true;
    this.game.input.setEnabled(true);
    this.game.hud.showAlert('BOMBA PLANTADA', `SITE ${site.id} · ${this.game.bombController.timer.toFixed(0)}s`, '#ff633f');
  }

  onBombExploded() {
    this.endRound('attackers', 'BOMBA DETONADA');
  }

  onBombDefused() {
    this.endRound('defenders', 'BOMBA DESARMADA');
  }

  endRound(winner, reason) {
    if (this.state === ROUND_STATE.ENDING || this.state === ROUND_STATE.FINISHED) return;
    this.lastWinner = winner;
    this.lastReason = reason;
    this.state = ROUND_STATE.ENDING;
    this.phaseTimer = END_TIME;
    this.controlsEnabled = false;
    this.roundActive = false;
    this.game.controlsEnabled = false;
    this.game.input.setEnabled(false);
    this.game.teamManager.addScore(winner);
    const color = winner === 'attackers' ? '#ff633f' : '#4adfff';
    this.game.hud.showRoundResult({
      winner,
      label: winner.toUpperCase(),
      reason,
      scores: [this.game.teamManager.attackersScore, this.game.teamManager.defendersScore],
      color,
      isPlayerWin: winner === this.game.player.team,
      round: this.roundNumber
    });
    this.game.audio.sfx(winner === this.game.player.team ? 'victory' : 'defeat');
    this.game.onRoundEnd(winner, reason);
    if (this.game.teamManager.getTeam(winner).score >= this.winTarget) {
      // The result overlay is followed by the match overlay after END_TIME.
    }
  }

  finishMatch(winner) {
    if (this.state === ROUND_STATE.FINISHED) return;
    this.state = ROUND_STATE.FINISHED;
    this.matchWinner = winner;
    this.game.controlsEnabled = false;
    this.game.input.setEnabled(false);
    this.game.hud.showMatchResult({
      winner,
      isPlayerWin: winner === this.game.player.team,
      scores: [this.game.teamManager.attackersScore, this.game.teamManager.defendersScore],
      scoreboard: this.game.teamManager.getScoreboard(),
      team: this.game.player.team
    });
    this.game.audio.sfx(winner === this.game.player.team ? 'victory' : 'defeat');
  }

  canPlant() {
    return this.state === ROUND_STATE.ACTIVE && this.game.bombController.state === BOMB_STATE.NOT_PLANTED;
  }

  canDefuse() {
    return this.state === ROUND_STATE.BOMB_PLANTED && this.game.bombController.state === BOMB_STATE.PLANTED;
  }

  canUseAbilities() {
    return this.state === ROUND_STATE.ACTIVE || this.state === ROUND_STATE.BOMB_PLANTED;
  }

  canShoot() {
    return this.state === ROUND_STATE.ACTIVE || this.state === ROUND_STATE.BOMB_PLANTED;
  }

  get isRoundActive() {
    return this.state === ROUND_STATE.ACTIVE || this.state === ROUND_STATE.BOMB_PLANTED;
  }
}

@import '@fontsource/bebas-neue/400.css';
@import '@fontsource/space-grotesk/400.css';
@import '@fontsource/space-grotesk/500.css';
@import '@fontsource/space-grotesk/600.css';
@import '@fontsource/space-grotesk/700.css';

:root {
  --bg: #060a0f;
  --bg-2: #0b1118;
  --panel: rgba(11, 17, 24, 0.82);
  --panel-solid: #0e151d;
  --line: rgba(182, 205, 220, 0.13);
  --line-bright: rgba(182, 205, 220, 0.28);
  --ink: #f4efe7;
  --ink-dim: #bdc8ce;
  --muted: #7f8d98;
  --coral: #ff633f;
  --coral-bright: #ff8568;
  --amber: #ffb24a;
  --cyan: #4adfff;
  --green: #55f0b0;
  --violet: #c88bff;
  --red: #ff4f5e;
  --display: 'Bebas Neue', 'Arial Narrow', sans-serif;
  --ui: 'Space Grotesk', 'Helvetica Neue', sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: var(--bg); }
body {
  font-family: var(--ui);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  touch-action: none;
}
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
input { font: inherit; }
svg { display: block; }
kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 22px; height: 20px; padding: 0 5px;
  border: 1px solid var(--line-bright); border-radius: 3px;
  background: rgba(255,255,255,0.05); color: var(--ink);
  font-size: 10px; font-weight: 600;
}

#game-canvas {
  position: fixed; inset: 0; width: 100%; height: 100%; display: block;
  background: radial-gradient(circle at 50% 40%, #141d27 0%, #060a0f 66%);
  touch-action: none;
}

.fx-layer { position: fixed; inset: 0; z-index: 2; pointer-events: none; overflow: hidden; }
.fx-grid {
  position: absolute; inset: 0;
  background-image: linear-gradient(rgba(115, 153, 179, 0.038) 1px, transparent 1px), linear-gradient(90deg, rgba(115, 153, 179, 0.038) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(ellipse at 60% 50%, #000 0%, transparent 72%);
}
.fx-vignette { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 46%, transparent 34%, rgba(0,0,0,0.35) 77%, rgba(0,0,0,0.72) 100%); }
.fx-grain {
  position: absolute; inset: -50%;
  opacity: 0.06;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  animation: grain 0.25s steps(2) infinite;
}
@keyframes grain { 0% { transform: translate(0,0); } 25% { transform: translate(2%,-1%); } 50% { transform: translate(-1%,2%); } 75% { transform: translate(1%,1%); } 100% { transform: translate(-2%,-1%); } }

/* ---------- BOOT ---------- */
#boot-screen {
  position: fixed; inset: 0; z-index: 500;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: #05090d;
  transition: opacity 0.7s ease, visibility 0.7s;
}
#boot-screen.hidden { opacity: 0; visibility: hidden; }
.boot-mark { display: flex; gap: 2px; font-family: var(--display); font-size: 82px; line-height: 0.8; letter-spacing: -2px; }
.boot-v { color: var(--ink); }
.boot-c { color: var(--coral); }
.boot-word { margin-top: 20px; font-family: var(--display); letter-spacing: 0.28em; font-size: 18px; color: var(--ink-dim); }
.boot-bar { width: 220px; height: 2px; background: rgba(255,255,255,0.1); margin-top: 26px; overflow: hidden; }
.boot-bar i { display: block; height: 100%; width: 40%; background: var(--coral); animation: bootbar 1.4s ease-in-out infinite; }
@keyframes bootbar { 0% { transform: translateX(-110%); } 100% { transform: translateX(310%); } }
.boot-status { font-size: 9px; letter-spacing: 0.34em; color: var(--muted); margin-top: 15px; }

/* ---------- MENU SHELL ---------- */
.menu-root {
  position: fixed; inset: 0; z-index: 5;
  display: flex; flex-direction: column;
  opacity: 1; visibility: visible; transition: opacity 0.5s ease, visibility 0.5s;
  pointer-events: none;
}
.menu-root > * { pointer-events: auto; }
.menu-root.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.menu-root::before {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(90deg, rgba(4,8,13,0.92) 0%, rgba(4,8,13,0.56) 36%, transparent 62%), linear-gradient(0deg, rgba(4,8,13,0.92), transparent 26%);
}
.menu-root.character-mode::before { background: linear-gradient(90deg, rgba(4,8,13,0.95) 0%, rgba(4,8,13,0.28) 34%, transparent 55%, rgba(4,8,13,0.55) 72%, rgba(4,8,13,0.9) 100%), linear-gradient(0deg, rgba(4,8,13,0.86), transparent 32%); }
.menu-root.customize-mode::before { background: linear-gradient(90deg, rgba(4,8,13,0.95) 0%, rgba(4,8,13,0.32) 32%, transparent 55%, rgba(4,8,13,0.8) 80%, rgba(4,8,13,0.94) 100%), linear-gradient(0deg, rgba(4,8,13,0.9), transparent 36%); }

.top-nav {
  position: relative; z-index: 10;
  height: 76px; padding: 0 34px 0 38px;
  display: flex; align-items: center; justify-content: space-between;
  border-bottom: 1px solid rgba(176, 205, 221, 0.1);
  background: linear-gradient(180deg, rgba(5,9,14,0.78), rgba(5,9,14,0.18));
  backdrop-filter: blur(8px);
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark {
  display: grid; place-items: center; width: 40px; height: 40px;
  border: 1px solid rgba(255,99,63,0.6); color: var(--coral);
  font-family: var(--display); font-size: 19px; letter-spacing: -0.02em;
  background: linear-gradient(135deg, rgba(255,99,63,0.16), transparent);
  clip-path: polygon(8% 0, 100% 0, 100% 84%, 90% 100%, 0 100%, 0 14%);
}
.brand-copy { display: flex; flex-direction: column; align-items: flex-start; line-height: 1; }
.brand-copy strong { font-family: var(--display); font-size: 19px; letter-spacing: 0.16em; }
.brand-copy small { font-size: 7px; letter-spacing: 0.3em; color: var(--muted); margin-top: 5px; }
.main-nav { display: flex; align-items: center; gap: 4px; height: 100%; }
.nav-link {
  position: relative; height: 100%; padding: 0 18px;
  font-size: 10px; letter-spacing: 0.18em; color: var(--muted); font-weight: 600;
  transition: color 0.2s;
}
.nav-link::after { content: ''; position: absolute; left: 18px; right: 18px; bottom: 0; height: 2px; background: var(--coral); transform: scaleX(0); transition: transform 0.25s; }
.nav-link:hover { color: var(--ink); }
.nav-link.active { color: var(--ink); }
.nav-link.active::after { transform: scaleX(1); }
.nav-actions { display: flex; align-items: center; gap: 16px; }
.online-pill { display: flex; align-items: center; gap: 7px; font-size: 8px; letter-spacing: 0.16em; color: var(--green); }
.online-pill i, .live-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); animation: blink 2s infinite; }
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
.icon-btn { width: 36px; height: 36px; display: grid; place-items: center; border: 1px solid var(--line); transition: border-color 0.2s, background 0.2s; }
.icon-btn svg { width: 16px; height: 16px; fill: var(--ink-dim); }
.icon-btn:hover { border-color: var(--coral); background: rgba(255,99,63,0.08); }

.menu-stage { position: relative; flex: 1; z-index: 8; min-height: 0; }
.view { position: absolute; inset: 0; opacity: 0; visibility: hidden; transition: opacity 0.35s ease, visibility 0.35s; padding: 24px 4vw 0; overflow: hidden; }
.view.active { opacity: 1; visibility: visible; }

/* ---------- HOME ---------- */
.hero-copy { position: absolute; left: 5.5vw; top: 7.5vh; width: min(620px, 47vw); }
.eyebrow { display: flex; align-items: center; gap: 10px; font-size: 8px; letter-spacing: 0.3em; color: var(--ink-dim); font-weight: 600; }
