.beta-tag { color: var(--coral); border: 1px solid rgba(255,99,63,0.4); padding: 2px 5px; font-size: 7px; letter-spacing: 0.18em; }
.hero-title { margin: 16px 0 10px; font-family: var(--display); font-weight: 400; line-height: 0.77; letter-spacing: -0.015em; display: flex; flex-direction: column; }
.hero-title span { display: block; font-size: clamp(86px, 11.5vw, 178px); }
.hero-title span:first-child { color: var(--ink); text-shadow: 0 10px 50px rgba(0,0,0,0.6); }
.hero-title .accent-word { color: var(--coral); margin-left: 0.55em; text-shadow: 0 0 60px rgba(255,99,63,0.3); }
.hero-title .accent-word::after { content: ''; display: inline-block; width: 0.09em; height: 0.08em; background: var(--amber); margin-left: 0.08em; vertical-align: 0.2em; box-shadow: 0 0 12px var(--amber); }
.hero-tagline { font-size: 13px; line-height: 1.75; color: var(--ink-dim); letter-spacing: 0.04em; margin: 12px 0 27px 34px; }
.hero-tagline strong { color: var(--ink); font-weight: 500; }
.hero-actions { display: flex; align-items: stretch; gap: 10px; margin-left: 34px; }
.btn-primary {
  position: relative; display: flex; flex-direction: column; align-items: flex-start; justify-content: center;
  min-width: 258px; padding: 15px 58px 14px 22px;
  background: var(--coral); color: #100805;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
  transition: transform 0.2s, background 0.2s;
