.btn-arrow { position: absolute; right: 22px; top: 50%; transform: translateY(-50%); font-size: 25px; font-weight: 300; }
.btn-primary.compact { min-width: 200px; padding: 11px 48px 11px 18px; }
.btn-primary.compact .btn-label { font-size: 19px; }
.btn-primary.compact .btn-arrow { right: 17px; font-size: 20px; }
.btn-ghost {
  display: flex; align-items: center; gap: 10px; padding: 0 19px;
  border: 1px solid var(--line-bright); background: rgba(11,17,24,0.35);
  font-size: 9px; letter-spacing: 0.17em; font-weight: 600; color: var(--ink-dim);
  transition: border-color 0.2s, color 0.2s, background 0.2s;
}
.btn-ghost:hover { border-color: var(--ink-dim); color: var(--ink); background: rgba(255,255,255,0.05); }
.ghost-icon { color: var(--coral); font-size: 16px; }
.match-options { display: flex; gap: 24px; margin: 28px 0 0 34px; align-items: flex-end; }
.option-group { display: flex; flex-direction: column; gap: 7px; }
.option-label { font-size: 7px; letter-spacing: 0.24em; color: var(--muted); }
.segmented { display: flex; border: 1px solid var(--line); background: rgba(9,14,21,0.6); }
.segmented button { padding: 7px 11px; font-size: 8px; letter-spacing: 0.12em; color: var(--muted); transition: background 0.2s, color 0.2s; }
.segmented button:hover { color: var(--ink); }
.segmented button.active { background: var(--ink); color: #080c12; font-weight: 700; }
.loadout-chip { display: flex; align-items: center; gap: 14px; padding: 8px 10px 8px 12px; border: 1px solid var(--line); background: rgba(9,14,21,0.6); font-size: 8px; letter-spacing: 0.1em; color: var(--ink-dim); }
.loadout-chip i { color: var(--coral); font-style: normal; font-size: 14px; }
.rule-value { font-size: 8px; letter-spacing: 0.1em; color: var(--ink-dim); padding: 9px 0; }
.hero-agent-card {
  position: absolute; right: 4.2vw; bottom: 15.5vh; width: 318px;
  padding: 20px 22px 17px; border-left: 1px solid rgba(255,99,63,0.55);
  background: linear-gradient(110deg, rgba(8,13,19,0.72), rgba(8,13,19,0.1));
  backdrop-filter: blur(3px);
}
.hero-agent-role { font-size: 8px; letter-spacing: 0.3em; color: var(--coral); }
.hero-agent-name { font-family: var(--display); font-size: 48px; line-height: 0.95; letter-spacing: 0.02em; margin-top: 5px; }
.hero-agent-real { font-size: 9px; letter-spacing: 0.13em; color: var(--muted); margin-top: 5px; }
.hero-agent-line { height: 1px; background: linear-gradient(90deg, var(--line-bright), transparent); margin: 14px 0 12px; }
.hero-agent-abilities { display: flex; gap: 16px; }
.hero-agent-ability { display: flex; align-items: center; gap: 7px; }
.hero-agent-ability span { font-size: 17px; color: var(--coral); width: 21px; text-align: center; }
.hero-agent-ability div { display: flex; flex-direction: column; }
.hero-agent-ability strong { font-size: 7px; letter-spacing: 0.12em; font-weight: 600; }
.hero-agent-ability small { font-size: 6px; letter-spacing: 0.13em; color: var(--muted); margin-top: 3px; }
.hero-agent-hint { margin-top: 16px; font-size: 7px; letter-spacing: 0.14em; color: var(--muted); display: flex; justify-content: space-between; }
.hero-agent-hint span { color: var(--ink-dim); }
.agent-dock { position: absolute; left: 5.5vw; bottom: 8.5vh; display: flex; gap: 7px; }
.dock-agent {
  position: relative; width: 34px; height: 42px; border: 1px solid rgba(177,200,215,0.2);
  background: linear-gradient(180deg, rgba(255,255,255,0.05), rgba(0,0,0,0.15));
  color: var(--muted); font-family: var(--display); font-size: 15px;
  clip-path: polygon(0 0, 100% 0, 100% 78%, 78% 100%, 0 100%);
  transition: transform 0.2s, border-color 0.2s, color 0.2s;
}
.dock-agent:hover { transform: translateY(-3px); color: var(--ink); border-color: var(--ink-dim); }
.dock-agent.active { border-color: var(--coral); color: var(--coral); background: linear-gradient(180deg, rgba(255,99,63,0.2), rgba(255,99,63,0.03)); }
.dock-agent small { position: absolute; right: 3px; bottom: 2px; font-family: var(--ui); font-size: 5px; letter-spacing: 0.02em; opacity: 0.6; }
.stage-coordinates { position: absolute; right: 4.2vw; top: 4vh; font-size: 7px; letter-spacing: 0.16em; color: rgba(180,200,212,0.45); writing-mode: vertical-rl; }
.stage-coordinates span { color: rgba(180,200,212,0.24); margin-top: 14px; }

/* ---------- SCREEN SHARED ---------- */
.screen-heading { display: flex; justify-content: space-between; align-items: flex-end; padding: 1vh 1vw 0; height: 15vh; min-height: 100px; }
.screen-title { margin: 8px 0 0; font-family: var(--display); font-size: clamp(46px, 5.8vw, 80px); font-weight: 400; line-height: 0.9; letter-spacing: 0.015em; }
.screen-title em { font-style: normal; color: var(--coral); }
.heading-meta { text-align: right; font-size: 8px; line-height: 1.8; letter-spacing: 0.17em; color: var(--muted); }
.heading-meta span { color: rgba(127,141,152,0.55); }
.menu-footer {
  position: relative; z-index: 10; height: 40px; padding: 0 34px;
  display: flex; align-items: center; justify-content: space-between;
  border-top: 1px solid rgba(176,205,221,0.1);
  background: rgba(4,8,13,0.66); backdrop-filter: blur(6px);
  font-size: 7px; letter-spacing: 0.17em; color: var(--muted);
}
.footer-left { display: flex; align-items: center; gap: 8px; }
.footer-center { display: flex; align-items: center; gap: 12px; }
.footer-center i { width: 3px; height: 3px; background: var(--coral); border-radius: 50%; }
.footer-right { display: flex; align-items: center; gap: 8px; }
.key-hint { display: grid; place-items: center; min-width: 24px; height: 18px; border: 1px solid var(--line); font-size: 7px; }

/* ---------- CHARACTERS ---------- */
#view-characters { padding: 0 2.2vw; }
.character-layout { height: calc(100% - 15vh); display: grid; grid-template-columns: 318px 1fr 374px; gap: 0; min-height: 0; }
.roster-panel { padding: 14px 0 0; display: flex; flex-direction: column; }
.roster-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; }
.roster-card {
  position: relative; height: clamp(72px, 9.4vh, 104px); padding: 9px 9px 8px 10px;
  text-align: left; border: 1px solid rgba(164,193,210,0.12);
  background: linear-gradient(145deg, rgba(23,33,42,0.72), rgba(8,13,19,0.58));
  transition: border-color 0.22s, background 0.22s, transform 0.2s;
  overflow: hidden;
}
.roster-card::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--agent-color, var(--coral)); opacity: 0; transition: opacity 0.2s; }
.roster-card::after { content: ''; position: absolute; right: -20px; bottom: -34px; width: 72px; height: 72px; border-radius: 50%; background: var(--agent-color, var(--coral)); opacity: 0.08; filter: blur(15px); }
.roster-card:hover { border-color: rgba(190,215,230,0.32); transform: translateY(-1px); }
.roster-card.active { border-color: var(--agent-color, var(--coral)); background: linear-gradient(145deg, rgba(34,45,54,0.9), rgba(9,14,20,0.7)); }
