.roster-role { display: block; font-size: 5.5px; letter-spacing: 0.13em; color: var(--muted); margin-top: 2px; }
.roster-foot { display: flex; justify-content: space-between; margin-top: auto; padding: 10px 0 12px; font-size: 6px; letter-spacing: 0.12em; color: rgba(127,141,152,0.55); }
.character-open-space { position: relative; min-width: 0; cursor: grab; }
.character-open-space:active { cursor: grabbing; }
.viewer-controls { position: absolute; left: 4%; bottom: 9%; display: flex; flex-direction: column; gap: 4px; z-index: 2; }
.viewer-controls button { width: 29px; height: 29px; border: 1px solid var(--line); background: rgba(8,13,19,0.7); color: var(--ink-dim); font-size: 15px; transition: border-color 0.2s, color 0.2s; }
.viewer-controls button:hover { border-color: var(--coral); color: var(--ink); }
.viewer-nameplate { position: absolute; left: 50%; bottom: 5%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 2px; pointer-events: none; }
.viewer-nameplate span { font-size: 7px; letter-spacing: 0.3em; color: var(--coral); }
.viewer-nameplate strong { font-family: var(--display); font-size: 30px; letter-spacing: 0.16em; font-weight: 400; }
.agent-detail-panel {
  margin: 14px 0 12px; padding: 20px 20px 15px; overflow-y: auto;
  border: 1px solid rgba(170,198,214,0.13);
  background: linear-gradient(160deg, rgba(12,19,26,0.86), rgba(6,10,15,0.64));
  backdrop-filter: blur(12px);
  scrollbar-width: thin; scrollbar-color: rgba(255,99,63,0.4) transparent;
}
.agent-detail-panel::-webkit-scrollbar { width: 4px; }
.agent-detail-panel::-webkit-scrollbar-thumb { background: rgba(255,99,63,0.4); }
.detail-top { display: flex; justify-content: space-between; align-items: flex-start; }
.role-chip { display: inline-flex; align-items: center; gap: 6px; border: 1px solid color-mix(in srgb, var(--role-color) 50%, transparent); color: var(--role-color); padding: 4px 7px; font-size: 6.5px; letter-spacing: 0.16em; }
.detail-num { font-size: 7px; letter-spacing: 0.16em; color: var(--muted); }
.detail-name { font-family: var(--display); font-size: 56px; font-weight: 400; line-height: 0.85; margin: 12px 0 2px; letter-spacing: 0.02em; }
.detail-real { font-size: 9px; letter-spacing: 0.12em; color: var(--muted); }
.detail-tagline { font-size: 11px; line-height: 1.55; color: var(--ink-dim); margin: 13px 0 10px; border-left: 2px solid var(--role-color); padding-left: 11px; }
.detail-description { font-size: 9px; line-height: 1.65; color: var(--muted); margin: 0 0 13px; }
.detail-section-title { display: flex; align-items: center; gap: 8px; font-size: 6.5px; letter-spacing: 0.2em; color: var(--muted); margin: 13px 0 7px; }
.detail-section-title::after { content: ''; height: 1px; flex: 1; background: var(--line); }
.ability-list { display: flex; flex-direction: column; gap: 4px; }
.detail-ability { display: flex; gap: 9px; padding: 8px 9px; background: rgba(255,255,255,0.025); border: 1px solid rgba(255,255,255,0.05); }
.detail-ability.passive { border-left: 2px solid var(--role-color); }
.detail-ability-icon { width: 29px; height: 29px; flex: 0 0 29px; display: grid; place-items: center; border: 1px solid color-mix(in srgb, var(--role-color) 35%, transparent); color: var(--role-color); font-size: 15px; background: color-mix(in srgb, var(--role-color) 8%, transparent); }
.detail-ability-copy { min-width: 0; }
.detail-ability-head { display: flex; align-items: center; gap: 6px; }
.detail-ability-head strong { font-size: 8px; letter-spacing: 0.1em; }
.detail-ability-head span { font-size: 5.5px; letter-spacing: 0.1em; color: var(--muted); border: 1px solid var(--line); padding: 1px 3px; }
.detail-ability p { margin: 3px 0 0; font-size: 7.5px; line-height: 1.4; color: var(--muted); }
.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 13px; }
.stat-item { display: flex; flex-direction: column; gap: 4px; }
.stat-item span { font-size: 6px; letter-spacing: 0.15em; color: var(--muted); }
.stat-item div { height: 3px; background: rgba(255,255,255,0.08); }
.stat-item i { display: block; height: 100%; background: var(--role-color); box-shadow: 0 0 5px color-mix(in srgb, var(--role-color) 55%, transparent); }
.skin-row { display: flex; gap: 6px; }
.skin-swatch { position: relative; width: 45px; height: 34px; border: 1px solid var(--line); overflow: hidden; background: var(--swatch); }
.skin-swatch.active { border-color: var(--role-color); box-shadow: inset 0 0 0 1px var(--role-color); }
.skin-swatch span { position: absolute; left: 3px; bottom: 2px; font-size: 4.5px; letter-spacing: 0.04em; color: #fff; text-shadow: 0 1px 3px #000; }
.detail-actions { display: flex; gap: 6px; margin-top: 14px; }
.detail-actions .btn-primary { flex: 1; min-width: 0; }
.detail-actions .btn-ghost { font-size: 7px; padding: 0 10px; }
.quote-line { font-size: 8px; font-style: italic; color: rgba(190,210,222,0.5); margin-top: 13px; }

/* ---------- ARMORY ---------- */
#view-armory { padding: 0 4vw; }
.armory-layout { height: calc(100% - 15vh); display: grid; grid-template-columns: 265px 1fr 270px; gap: 3vw; align-items: center; }
.weapon-rail { display: flex; flex-direction: column; gap: 5px; }
.weapon-card {
  display: flex; align-items: center; gap: 12px; padding: 13px 13px;
  border: 1px solid transparent; border-left: 2px solid transparent;
  background: rgba(11,18,25,0.5); text-align: left; transition: all 0.2s;
}
.weapon-card:hover { background: rgba(255,255,255,0.04); border-color: var(--line); }
.weapon-card.active { border-color: rgba(255,99,63,0.34); border-left-color: var(--coral); background: rgba(255,99,63,0.07); }
.weapon-card-index { font-size: 7px; color: var(--muted); width: 18px; }
.weapon-card-glyph { width: 46px; color: var(--ink-dim); }
.weapon-card-glyph svg { width: 46px; height: 20px; fill: currentColor; }
.weapon-card.active .weapon-card-glyph { color: var(--coral); }
.weapon-card-copy { display: flex; flex-direction: column; gap: 3px; }
.weapon-card-copy strong { font-size: 9px; letter-spacing: 0.1em; font-weight: 600; }
.weapon-card-copy small { font-size: 5.5px; letter-spacing: 0.12em; color: var(--muted); }
.weapon-card .equipped-tag { margin-left: auto; font-size: 5px; color: var(--green); border: 1px solid rgba(85,240,176,0.4); padding: 2px 4px; }
.weapon-showcase { align-self: center; padding: 4vh 2vw 4vh 2vw; position: relative; }
.weapon-showcase::before { content: ''; position: absolute; inset: 10% 0 12%; border-top: 1px solid rgba(255,255,255,0.06); border-bottom: 1px solid rgba(255,255,255,0.04); background: radial-gradient(ellipse at center, rgba(255,99,63,0.06), transparent 66%); }
.weapon-silhouette { position: relative; height: 155px; display: flex; align-items: center; justify-content: center; color: var(--ink); filter: drop-shadow(0 10px 22px rgba(0,0,0,0.6)); }
.weapon-silhouette svg { width: 90%; max-width: 650px; height: 150px; fill: #b8c3ca; }
.weapon-silhouette::after { content: ''; position: absolute; width: 65%; height: 1px; bottom: 8px; background: linear-gradient(90deg, transparent, var(--coral), transparent); opacity: 0.6; }
.weapon-code { font-size: 7px; letter-spacing: 0.3em; color: var(--coral); }
.weapon-name { font-family: var(--display); font-size: clamp(42px, 4.4vw, 66px); line-height: 0.95; letter-spacing: 0.03em; margin: 6px 0 2px; }
.weapon-class { font-size: 8px; letter-spacing: 0.2em; color: var(--muted); }
.weapon-description { max-width: 560px; font-size: 10px; line-height: 1.65; color: var(--ink-dim); }
.weapon-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 20px; margin: 20px 0 24px; max-width: 560px; }
.wstat { display: grid; grid-template-columns: 48px 1fr 24px; align-items: center; gap: 8px; }
.wstat span { font-size: 6px; letter-spacing: 0.16em; color: var(--muted); text-transform: uppercase; }
.wstat div { height: 3px; background: rgba(255,255,255,0.08); }
.wstat i { display: block; height: 100%; background: var(--coral); }
.wstat strong { font-size: 7px; font-weight: 500; color: var(--ink-dim); text-align: right; }
.armory-note { border-left: 1px solid var(--line); padding-left: 25px; position: relative; }
.note-index { font-family: var(--display); font-size: 54px; color: rgba(255,99,63,0.32); line-height: 1; }
.armory-note h3, .sticker-panel h3 { font-family: var(--display); font-size: 22px; letter-spacing: 0.1em; font-weight: 400; margin: 5px 0 7px; }
.armory-note p, .sticker-panel p { font-size: 9px; line-height: 1.7; color: var(--muted); }
.note-rule { height: 1px; background: var(--line); margin: 20px 0 15px; }
.armory-note h4 { font-size: 7px; letter-spacing: 0.2em; color: var(--ink-dim); margin: 0 0 9px; }
.future-list { display: flex; flex-wrap: wrap; gap: 4px; }
.future-list span { border: 1px dashed var(--line); padding: 4px 6px; font-size: 6px; letter-spacing: 0.1em; color: var(--muted); }
.arsenal-seal { margin-top: 30px; width: 66px; height: 66px; border: 1px solid rgba(255,99,63,0.35); display: flex; flex-direction: column; align-items: center; justify-content: center; font-family: var(--display); font-size: 24px; color: var(--coral); transform: rotate(-6deg); }
.arsenal-seal small { font-family: var(--ui); font-size: 5px; letter-spacing: 0.22em; color: var(--muted); margin-top: 2px; }

/* ---------- CUSTOMIZE ---------- */
#view-customize { padding: 0 4vw; }
.customize-layout { height: calc(100% - 15vh); display: grid; grid-template-columns: 305px 1fr 265px; gap: 2vw; align-items: center; }
.customize-info { padding: 20px; border: 1px solid var(--line); background: rgba(9,15,21,0.58); backdrop-filter: blur(8px); }
.custom-role { font-size: 7px; letter-spacing: 0.28em; color: var(--coral); }
.customize-info h3 { font-family: var(--display); font-size: 38px; font-weight: 400; letter-spacing: 0.05em; margin: 6px 0 5px; }
.customize-info p { font-size: 9px; line-height: 1.7; color: var(--muted); margin: 0 0 17px; }
.skin-list { display: flex; flex-direction: column; gap: 5px; margin-bottom: 18px; }
.skin-card { display: flex; align-items: center; gap: 10px; padding: 7px; border: 1px solid var(--line); text-align: left; transition: border-color 0.2s, background 0.2s; }
.skin-card:hover { border-color: var(--line-bright); background: rgba(255,255,255,0.04); }
.skin-card.active { border-color: var(--coral); background: rgba(255,99,63,0.07); }
.skin-thumb { width: 43px; height: 43px; flex: none; position: relative; background: var(--swatch); overflow: hidden; }
.skin-thumb::before { content: ''; position: absolute; width: 70%; height: 1px; background: rgba(255,255,255,0.45); transform: rotate(-38deg); top: 50%; left: 15%; box-shadow: 0 7px 0 rgba(255,255,255,0.18); }
.skin-card div:nth-child(2) { display: flex; flex-direction: column; gap: 3px; }
.skin-card strong { font-size: 8px; letter-spacing: 0.1em; }
.skin-card small { font-size: 5.5px; color: var(--muted); letter-spacing: 0.12em; }
.skin-card .skin-equip { margin-left: auto; color: var(--green); font-size: 6px; }
.custom-meta { display: flex; justify-content: space-between; border-top: 1px solid var(--line); padding: 8px 0; font-size: 6.5px; letter-spacing: 0.13em; color: var(--muted); }
.custom-meta strong { color: var(--ink-dim); font-weight: 500; }
.text-green { color: var(--green) !important; }
.customize-stage { align-self: stretch; position: relative; cursor: grab; }
.stage-caption { position: absolute; top: 4%; left: 50%; transform: translateX(-50%); font-size: 6.5px; letter-spacing: 0.28em; color: var(--muted); white-space: nowrap; }
.stage-caption span { color: rgba(127,141,152,0.5); }
.sticker-panel { border-left: 1px solid var(--line); padding-left: 23px; }
.sticker-panel .note-index { color: rgba(200,139,255,0.32); }
.sticker-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; margin: 18px 0; }
.sticker { height: 45px; border: 1px solid var(--line); background: rgba(255,255,255,0.025); color: var(--muted); font-size: 18px; transition: all 0.2s; }
.sticker:hover, .sticker.active { border-color: var(--violet); color: var(--violet); background: rgba(200,139,255,0.08); }
.sticker-preview { display: flex; align-items: center; gap: 13px; border: 1px solid var(--line); padding: 12px; background: linear-gradient(120deg, rgba(200,139,255,0.08), transparent); }
.sticker-preview span { font-size: 28px; color: var(--violet); }
.sticker-preview small { font-size: 6px; line-height: 1.7; letter-spacing: 0.15em; color: var(--muted); }

/* ---------- ABOUT ---------- */
#view-about { padding: 0 5vw; }
.about-layout { height: calc(100% - 15vh); display: grid; grid-template-columns: 1fr 300px; gap: 5vw; align-items: center; }
.manifesto-lead { font-size: clamp(16px, 1.45vw, 21px); line-height: 1.55; font-weight: 400; color: var(--ink); max-width: 740px; border-left: 2px solid var(--coral); padding-left: 20px; }
.about-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 22px 30px; margin-top: 32px; max-width: 780px; }
.about-columns h4 { font-size: 7px; letter-spacing: 0.22em; color: var(--coral); margin: 0 0 7px; }
.about-columns p { font-size: 9px; line-height: 1.75; color: var(--muted); margin: 0; }
.about-stats { border-left: 1px solid var(--line); padding-left: 25px; }
.about-stats > div:not(.about-build) { display: flex; align-items: baseline; gap: 12px; border-bottom: 1px solid var(--line); padding: 10px 0; }
.about-stats > div strong { font-family: var(--display); font-size: 38px; font-weight: 400; color: var(--ink); line-height: 1; }
.about-stats > div span { font-size: 6.5px; letter-spacing: 0.2em; color: var(--muted); }
.about-build { margin-top: 20px; padding: 15px; background: rgba(255,255,255,0.025); border: 1px solid var(--line); display: grid; grid-template-columns: 1fr auto; gap: 7px; font-size: 6px; letter-spacing: 0.12em; }
.about-build span { color: var(--muted); }
.about-build strong { color: var(--ink-dim); font-weight: 500; text-align: right; }

/* ---------- MODAL ---------- */
.modal-layer { position: fixed; inset: 0; z-index: 100; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.3s, visibility 0.3s; }
.modal-layer.open { opacity: 1; visibility: visible; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(2,5,9,0.75); backdrop-filter: blur(12px); }
.settings-panel { position: relative; width: min(560px, 92vw); max-height: 90vh; overflow: auto; background: #0c131a; border: 1px solid rgba(180,208,224,0.18); box-shadow: 0 30px 100px rgba(0,0,0,0.6); }
.settings-head { display: flex; align-items: flex-start; justify-content: space-between; padding: 24px 26px 16px; border-bottom: 1px solid var(--line); }
.settings-head h3 { font-family: var(--display); font-size: 36px; font-weight: 400; margin: 3px 0 0; letter-spacing: 0.06em; }
.close-btn { width: 30px; height: 30px; font-size: 20px; border: 1px solid var(--line); color: var(--muted); transition: all 0.2s; }
.close-btn:hover { border-color: var(--coral); color: var(--ink); }
.settings-body { padding: 18px 26px; }
.setting-group { padding: 12px 0 16px; border-bottom: 1px solid rgba(255,255,255,0.05); }
.setting-row { display: flex; justify-content: space-between; align-items: center; font-size: 8px; letter-spacing: 0.15em; color: var(--ink-dim); margin-bottom: 8px; }
.setting-row small { display: block; font-size: 5.5px; letter-spacing: 0.1em; color: var(--muted); margin-top: 3px; }
.setting-row strong { font-size: 8px; color: var(--coral); font-weight: 500; }
input[type='range'] { -webkit-appearance: none; appearance: none; width: 100%; height: 3px; background: rgba(255,255,255,0.1); outline: none; }
input[type='range']::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; background: var(--coral); border: 2px solid #0c131a; box-shadow: 0 0 0 1px var(--coral); cursor: pointer; }
input[type='range']::-moz-range-thumb { width: 9px; height: 9px; background: var(--coral); border: 2px solid #0c131a; border-radius: 0; cursor: pointer; }
.volumes input { margin-bottom: 10px; }
.quality { width: 100%; }
.quality button { flex: 1; padding: 8px 0; }
.toggle-group { display: flex; flex-direction: column; gap: 10px; border-bottom: 0; }
.toggle-row { display: flex; justify-content: space-between; align-items: center; font-size: 8px; letter-spacing: 0.13em; color: var(--ink-dim); cursor: pointer; }
.toggle-row small { color: var(--muted); font-size: 5.5px; }
.toggle-row input { display: none; }
.toggle-row i { width: 31px; height: 16px; border: 1px solid var(--line-bright); position: relative; transition: background 0.2s, border-color 0.2s; }
.toggle-row i::after { content: ''; position: absolute; width: 10px; height: 10px; background: var(--muted); left: 2px; top: 2px; transition: transform 0.2s, background 0.2s; }
.toggle-row input:checked + i { border-color: var(--coral); background: rgba(255,99,63,0.15); }
.toggle-row input:checked + i::after { transform: translateX(15px); background: var(--coral); }
.settings-foot { display: flex; align-items: center; justify-content: space-between; padding: 16px 26px 22px; border-top: 1px solid var(--line); }
.text-button { font-size: 7.5px; letter-spacing: 0.16em; color: var(--muted); text-transform: uppercase; transition: color 0.2s; }
.text-button:hover { color: var(--ink); }
.text-button.danger { color: #c6636c; }
.text-button.danger:hover { color: var(--red); }

/* ---------- GAME HUD ---------- */
.game-root { position: fixed; inset: 0; z-index: 30; display: none; pointer-events: none; }
.game-root.active { display: block; }
#hud { position: absolute; inset: 0; font-family: var(--ui); }
.hud-score {
  position: absolute; top: calc(14px + var(--safe-top)); left: 50%; transform: translateX(-50%);
  display: flex; align-items: stretch; height: 59px;
  border: 1px solid rgba(180,205,220,0.16);
  background: linear-gradient(180deg, rgba(7,12,18,0.9), rgba(7,12,18,0.58));
  backdrop-filter: blur(8px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 0 calc(100% - 8px));
}
.score-side { width: 112px; display: flex; flex-direction: column; align-items: center; justify-content: center; position: relative; }
.score-side.attackers { border-right: 1px solid rgba(255,99,63,0.24); }
.score-side.defenders { border-left: 1px solid rgba(74,223,255,0.24); }
.score-side::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px; }
.score-side.attackers::before { background: var(--coral); }
.score-side.defenders::before { background: var(--cyan); }
.score-role { font-size: 6px; letter-spacing: 0.2em; color: var(--muted); }
.score-side strong { font-family: var(--display); font-size: 30px; line-height: 1; font-weight: 400; }
.score-side.attackers strong { color: var(--coral); }
.score-side.defenders strong { color: var(--cyan); }
.score-side small { display: flex; align-items: center; gap: 4px; font-size: 5.5px; letter-spacing: 0.1em; color: var(--muted); margin-top: 1px; }
.alive-dot { width: 4px; height: 4px; background: currentColor; border-radius: 50%; }
.score-center { width: 154px; display: flex; flex-direction: column; align-items: center; justify-content: center; position: relative; }
.score-center::before, .score-center::after { content: ''; position: absolute; width: 5px; height: 5px; border: 1px solid rgba(255,255,255,0.2); transform: rotate(45deg); top: 8px; }
.score-center::before { left: 8px; }
.score-center::after { right: 8px; }
.round-label { font-size: 6px; letter-spacing: 0.18em; color: var(--muted); }
.round-timer { font-family: var(--display); font-size: 28px; font-weight: 400; line-height: 0.95; letter-spacing: 0.07em; }
.round-timer.low { color: var(--red); animation: pulseText 1s infinite; }
.match-score { font-size: 5.5px; letter-spacing: 0.15em; color: var(--muted); }
@keyframes pulseText { 50% { opacity: 0.45; } }

.hud-minimap { position: absolute; top: calc(20px + var(--safe-top)); left: 22px; width: 190px; border: 1px solid rgba(170,200,215,0.14); background: rgba(5,10,15,0.62); }
.minimap-head { height: 23px; padding: 0 7px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgba(170,200,215,0.1); font-size: 5.5px; letter-spacing: 0.14em; color: var(--muted); }
.minimap-head strong { color: var(--ink-dim); font-weight: 500; }
#minimap { display: block; width: 100%; height: auto; opacity: 0.92; }
.minimap-sites { position: absolute; top: 44%; left: 8px; right: 8px; display: flex; justify-content: space-between; pointer-events: none; }
.minimap-sites span { font-family: var(--display); font-size: 15px; }
.site-a { color: var(--coral); }
.site-b { color: var(--cyan); }
.minimap-foot { display: flex; gap: 7px; padding: 5px 7px; font-size: 4.5px; letter-spacing: 0.08em; color: var(--muted); border-top: 1px solid rgba(170,200,215,0.08); }
.minimap-foot span { display: flex; align-items: center; gap: 3px; }
.dot { display: block; width: 4px; height: 4px; border-radius: 50%; }
.dot.ally { background: var(--cyan); }
.dot.enemy { background: var(--coral); }
.dot.bomb { background: var(--red); box-shadow: 0 0 4px var(--red); }
.hud-killfeed { position: absolute; top: calc(20px + var(--safe-top)); right: 22px; width: 285px; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
.kill-entry { display: flex; align-items: center; gap: 7px; min-height: 27px; padding: 4px 8px; background: rgba(5,10,15,0.72); border-right: 2px solid var(--coral); font-size: 7px; letter-spacing: 0.08em; animation: slideIn 0.25s ease; backdrop-filter: blur(5px); }
.kill-entry.defender { border-right-color: var(--cyan); }
.kill-entry .killer { color: var(--ink); }
.kill-entry .weapon { color: var(--amber); font-family: var(--display); font-size: 11px; letter-spacing: 0.08em; }
.kill-entry .victim { color: var(--muted); }
.kill-entry .hs { color: var(--amber); font-size: 5px; border: 1px solid rgba(255,178,74,0.4); padding: 1px 3px; }
@keyframes slideIn { from { transform: translateX(20px); opacity: 0; } }

.bomb-status { position: absolute; top: calc(83px + var(--safe-top)); left: 50%; transform: translateX(-50%) translateY(-8px); display: flex; align-items: center; gap: 10px; opacity: 0; visibility: hidden; transition: all 0.3s; padding: 7px 18px; border: 1px solid rgba(255,79,82,0.35); background: rgba(26,7,9,0.84); }
.bomb-status.visible { opacity: 1; visibility: visible; transform: translateX(-50%) translateY(0); }
.bomb-status.defusing { border-color: rgba(74,223,255,0.5); background: rgba(4,19,26,0.86); }
.bomb-pulse { width: 8px; height: 8px; background: var(--red); border-radius: 50%; box-shadow: 0 0 10px var(--red); animation: blink 0.8s infinite; }
.bomb-status.defusing .bomb-pulse { background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.bomb-status > div:nth-child(2) { display: grid; grid-template-columns: auto auto; gap: 0 10px; align-items: baseline; }
.bomb-status span { grid-column: 1 / 3; font-size: 5.5px; letter-spacing: 0.17em; color: var(--red); }
.bomb-status.defusing span { color: var(--cyan); }
.bomb-status strong { font-family: var(--display); font-size: 20px; font-weight: 400; line-height: 1; color: var(--ink); }
.bomb-status small { font-size: 5.5px; letter-spacing: 0.1em; color: var(--muted); }
.bomb-defuse-bar { width: 90px; height: 3px; background: rgba(255,255,255,0.1); display: none; }
.bomb-status.defusing .bomb-defuse-bar { display: block; }
.bomb-defuse-bar i { display: block; height: 100%; width: 0; background: var(--cyan); }

.crosshair { position: absolute; top: 50%; left: 50%; width: 46px; height: 46px; transform: translate(-50%,-50%); pointer-events: none; }
.crosshair .ch { position: absolute; background: rgba(240,245,248,0.85); box-shadow: 0 0 2px rgba(0,0,0,0.8); transition: transform 0.08s; }
.crosshair .ch.l, .crosshair .ch.r { width: 7px; height: 1px; top: 23px; }
.crosshair .ch.t, .crosshair .ch.b { width: 1px; height: 7px; left: 23px; }
.crosshair .ch.l { right: 32px; }
.crosshair .ch.r { left: 32px; }
.crosshair .ch.t { bottom: 32px; }
.crosshair .ch.b { top: 32px; }
.ch-dot { position: absolute; width: 2px; height: 2px; background: #fff; left: 22px; top: 22px; border-radius: 50%; box-shadow: 0 0 4px rgba(0,0,0,0.8); }
.crosshair.kick .ch.l { transform: translateX(-4px); }
.crosshair.kick .ch.r { transform: translateX(4px); }
.crosshair.kick .ch.t { transform: translateY(-4px); }
.crosshair.kick .ch.b { transform: translateY(4px); }
.hitmarker { position: absolute; inset: 0; opacity: 0; }
.hitmarker i { position: absolute; width: 7px; height: 1px; background: #fff; left: 20px; top: 23px; }
.hitmarker i:nth-child(1) { transform: rotate(45deg) translateX(-8px); }
.hitmarker i:nth-child(2) { transform: rotate(-45deg) translateX(8px); }
.hitmarker i:nth-child(3) { transform: rotate(-45deg) translateX(-8px); }
.hitmarker i:nth-child(4) { transform: rotate(45deg) translateX(8px); }
.hitmarker.show { animation: hit 0.2s; }
.hitmarker-head { position: absolute; top: 58px; left: 50%; transform: translateX(-50%); font-size: 7px; letter-spacing: 0.2em; color: var(--amber); opacity: 0; text-shadow: 0 0 8px var(--amber); }
.hitmarker-head.show { animation: hit 0.4s; }
@keyframes hit { 0% { opacity: 1; transform: scale(0.7); } 100% { opacity: 0; transform: scale(1.2); } }

.objective-prompt { position: absolute; left: 50%; bottom: 20.5%; transform: translateX(-50%) translateY(10px); display: flex; align-items: center; gap: 11px; opacity: 0; visibility: hidden; transition: all 0.22s; padding: 9px 15px 9px 10px; background: rgba(5,10,15,0.8); border: 1px solid var(--line); backdrop-filter: blur(5px); }
.objective-prompt.visible { opacity: 1; visibility: visible; transform: translateX(-50%) translateY(0); }
.prompt-key { width: 29px; height: 29px; display: grid; place-items: center; border: 1px solid var(--ink-dim); font-size: 11px; font-weight: 600; color: var(--ink); }
.prompt-copy { display: flex; flex-direction: column; gap: 3px; min-width: 185px; }
.prompt-copy strong { font-size: 7px; letter-spacing: 0.14em; }
.prompt-copy small { font-size: 5.5px; letter-spacing: 0.12em; color: var(--muted); }
.prompt-bar { width: 100%; height: 2px; background: rgba(255,255,255,0.1); margin-top: 3px; display: none; }
.prompt-bar i { display: block; height: 100%; width: 0; background: var(--coral); }
.objective-prompt.has-progress .prompt-bar { display: block; }

.hud-bottom-left { position: absolute; left: 22px; bottom: calc(22px + var(--safe-bottom)); display: flex; align-items: flex-end; gap: 12px; }
.agent-badge { width: 42px; height: 52px; display: grid; place-items: center; border: 1px solid rgba(255,99,63,0.4); background: rgba(255,99,63,0.09); font-family: var(--display); font-size: 27px; color: var(--coral); clip-path: polygon(0 0, 100% 0, 100% 80%, 82% 100%, 0 100%); }
.vitals { width: 235px; }
.vital-row { display: grid; grid-template-columns: 14px 1fr 36px; align-items: center; gap: 7px; margin-bottom: 5px; }
.vital-icon { font-size: 10px; color: var(--green); }
.vital-icon.shield { color: var(--cyan); font-size: 13px; }
.vital-bar { height: 5px; background: rgba(255,255,255,0.1); }
.vital-bar i { display: block; height: 100%; width: 100%; background: var(--green); transition: width 0.25s; box-shadow: 0 0 8px rgba(85,240,176,0.2); }
.vital-bar.armor i { background: var(--cyan); width: 0; }
.vital-row strong { font-family: var(--display); font-size: 19px; font-weight: 400; text-align: right; }
.agent-caption { display: flex; align-items: center; gap: 7px; margin-top: 4px; }
.agent-caption strong { font-size: 7px; letter-spacing: 0.16em; font-weight: 600; }
.agent-caption span { font-size: 5.5px; letter-spacing: 0.14em; color: var(--muted); border-left: 1px solid var(--line); padding-left: 7px; }

.hud-abilities { position: absolute; left: 50%; bottom: calc(27px + var(--safe-bottom)); transform: translateX(-50%); display: flex; gap: 6px; }
.ability-card { position: relative; width: 148px; height: 47px; display: flex; align-items: center; gap: 8px; padding: 6px 8px; border: 1px solid rgba(180,205,220,0.15); background: rgba(5,10,15,0.72); overflow: hidden; backdrop-filter: blur(5px); }
.ability-card .ability-key { position: absolute; top: 3px; left: 4px; width: 12px; height: 12px; display: grid; place-items: center; font-size: 6px; color: var(--muted); border: 1px solid var(--line); }
.ability-icon { width: 29px; height: 29px; flex: none; display: grid; place-items: center; border: 1px solid rgba(255,99,63,0.36); color: var(--coral); background: rgba(255,99,63,0.08); font-size: 17px; }
.special-ability .ability-icon { border-color: rgba(255,178,74,0.4); color: var(--amber); background: rgba(255,178,74,0.08); }
.ability-copy { display: flex; flex-direction: column; gap: 3px; z-index: 2; padding-left: 4px; }
.ability-copy strong { font-size: 6.5px; letter-spacing: 0.1em; font-weight: 600; }
.ability-copy small { font-size: 5.5px; color: var(--green); letter-spacing: 0.1em; }
.cooldown-mask { position: absolute; inset: 0; background: rgba(0,0,0,0.6); transform-origin: bottom; transform: scaleY(0); pointer-events: none; }
.cooldown-ring { position: absolute; right: 6px; top: 50%; transform: translateY(-50%); width: 5px; height: 26px; background: rgba(255,255,255,0.1); display: none; }
.cooldown-ring::after { content: ''; display: block; width: 100%; height: var(--cd, 0%); background: var(--coral); }

.hud-bottom-right { position: absolute; right: 22px; bottom: calc(22px + var(--safe-bottom)); display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.weapon-slots { display: flex; gap: 3px; }
.weapon-slots .slot { display: flex; align-items: center; gap: 4px; padding: 3px 6px; border: 1px solid transparent; color: rgba(180,200,212,0.35); font-size: 5.5px; letter-spacing: 0.1em; }
.weapon-slots .slot span { font-size: 6px; color: inherit; }
.weapon-slots .slot i { width: 12px; height: 1px; background: currentColor; }
.weapon-slots .slot.active { color: var(--ink-dim); border-color: var(--line); }
.weapon-info { min-width: 208px; padding: 8px 12px 7px; border-right: 2px solid var(--coral); background: linear-gradient(90deg, rgba(5,10,15,0.2), rgba(5,10,15,0.75)); text-align: right; }
.weapon-top { display: flex; flex-direction: column; gap: 2px; }
.weapon-top span { font-size: 5px; letter-spacing: 0.16em; color: var(--muted); }
.weapon-top strong { font-size: 8px; letter-spacing: 0.13em; }
.ammo-row { display: flex; justify-content: flex-end; align-items: baseline; gap: 4px; margin: 1px 0 4px; }
.ammo-row strong { font-family: var(--display); font-size: 38px; line-height: 0.9; font-weight: 400; }
.ammo-row span { color: var(--muted); font-size: 12px; }
.ammo-row small { font-size: 13px; color: var(--muted); }
.weapon-hint { display: flex; gap: 6px; align-items: center; justify-content: flex-end; font-size: 4.5px; color: var(--muted); }
.weapon-hint span { border: 1px solid var(--line); padding: 1px 3px; }
.reload-track { height: 2px; background: rgba(255,255,255,0.1); margin-bottom: 4px; opacity: 0; }
.reload-track.active { opacity: 1; }
.reload-track i { display: block; height: 100%; width: 0; background: var(--amber); }
.ammo-row.low strong { color: var(--red); }

.round-banner { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: opacity 0.3s, visibility 0.3s; background: radial-gradient(ellipse at center, rgba(5,10,15,0.5), transparent 65%); }
.round-banner.visible { opacity: 1; visibility: visible; }
.banner-kicker { font-size: 8px; letter-spacing: 0.4em; color: var(--muted); margin-bottom: 6px; }
.round-banner h2 { font-family: var(--display); font-size: clamp(55px, 7vw, 96px); font-weight: 400; line-height: 1; margin: 0; letter-spacing: 0.02em; }
.round-banner p { font-size: 9px; letter-spacing: 0.16em; color: var(--ink-dim); margin: 8px 0 0; text-align: center; }
.banner-line { width: 120px; height: 2px; background: var(--coral); margin-top: 18px; box-shadow: 0 0 14px var(--coral); }
.countdown { position: absolute; left: 50%; top: 46%; transform: translate(-50%, -50%); font-family: var(--display); font-size: 110px; color: var(--ink); opacity: 0; transition: opacity 0.2s; text-shadow: 0 0 50px rgba(255,99,63,0.35); }
.countdown.visible { opacity: 1; animation: countPop 0.9s ease infinite; }
@keyframes countPop { 0% { transform: translate(-50%, -50%) scale(1.18); opacity: 0.1; } 25% { opacity: 1; } 100% { transform: translate(-50%, -50%) scale(0.92); opacity: 0.25; } }
.round-alert { position: absolute; left: 50%; top: 24%; transform: translateX(-50%) translateY(-10px); display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 12px 28px; border-top: 1px solid var(--coral); border-bottom: 1px solid var(--coral); background: rgba(13,6,7,0.72); opacity: 0; visibility: hidden; transition: all 0.3s; }
.round-alert.visible { opacity: 1; visibility: visible; transform: translateX(-50%) translateY(0); }
.round-alert span { font-size: 6px; letter-spacing: 0.3em; color: var(--red); }
.round-alert strong { font-family: var(--display); font-size: 25px; letter-spacing: 0.1em; font-weight: 400; }
.round-alert small { font-size: 6px; letter-spacing: 0.15em; color: var(--muted); }
.notify-stack { position: absolute; left: 50%; bottom: 34%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 4px; pointer-events: none; }
.notify { padding: 5px 12px; background: rgba(5,10,15,0.78); border-left: 2px solid var(--coral); font-size: 6.5px; letter-spacing: 0.15em; animation: notifyIn 0.25s ease; white-space: nowrap; }
@keyframes notifyIn { from { transform: translateY(8px); opacity: 0; } }
.damage-overlay { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 40%, rgba(255,25,38,0.55) 100%); transition: opacity 0.25s; }
.damage-overlay.hit { opacity: 1; }
.damage-indicator { position: absolute; inset: 0; pointer-events: none; }
.damage-indicator::before { content: ''; position: absolute; left: 50%; top: 50%; width: 190px; height: 190px; margin: -95px; border-radius: 50%; border-top: 3px solid rgba(255,45,55,0.9); transform: rotate(var(--dmg-angle, 0deg)); filter: blur(1px); opacity: var(--dmg-opacity, 0); transition: opacity 0.4s; }
.kill-popup { position: absolute; right: 24%; top: 46%; display: flex; flex-direction: column; align-items: flex-end; opacity: 0; transform: translateX(10px); transition: all 0.2s; }
.kill-popup.show { opacity: 1; transform: translateX(0); animation: killPop 1.2s forwards; }
.kill-popup strong { font-family: var(--display); font-size: 20px; letter-spacing: 0.14em; color: var(--coral); }
.kill-popup span { font-size: 6px; letter-spacing: 0.13em; color: var(--muted); }
@keyframes killPop { 0% { opacity: 0; transform: translateX(12px); } 12% { opacity: 1; transform: translateX(0); } 72% { opacity: 1; } 100% { opacity: 0; } }
.death-screen { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(ellipse at center, rgba(20,5,7,0.48), rgba(3,5,8,0.84)); opacity: 0; visibility: hidden; transition: all 0.4s; }
.death-screen.visible { opacity: 1; visibility: visible; }
.death-kicker { font-size: 7px; letter-spacing: 0.35em; color: var(--red); }
.death-screen h2 { font-family: var(--display); font-size: clamp(48px, 6vw, 78px); font-weight: 400; letter-spacing: 0.03em; margin: 5px 0 4px; }
.death-screen p { font-size: 8px; letter-spacing: 0.17em; color: var(--muted); }
.spectate-line { display: flex; align-items: center; gap: 8px; margin-top: 26px; font-size: 6px; letter-spacing: 0.16em; color: var(--ink-dim); }
.spectate-line i { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); animation: blink 1.2s infinite; }

.round-result { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(ellipse at center, rgba(5,10,15,0.58), rgba(3,6,10,0.9)); opacity: 0; visibility: hidden; transition: all 0.35s; }
.round-result.visible { opacity: 1; visibility: visible; }
.result-kicker { font-size: 7px; letter-spacing: 0.34em; color: var(--muted); }
.round-result h2 { font-family: var(--display); font-size: clamp(55px, 8vw, 108px); font-weight: 400; line-height: 0.9; margin: 4px 0 6px; letter-spacing: 0.02em; }
.round-result p { font-size: 8px; letter-spacing: 0.22em; color: var(--ink-dim); }
.result-score { display: flex; gap: 16px; align-items: baseline; margin-top: 17px; font-family: var(--display); font-size: 45px; }
.result-score i { font-style: normal; font-size: 24px; color: var(--muted); }
.result-score span:first-child { color: var(--coral); }
.result-score span:last-child { color: var(--cyan); }
.result-next { margin-top: 24px; font-size: 6px; letter-spacing: 0.17em; color: var(--muted); }
.result-next strong { color: var(--ink); font-family: var(--display); font-size: 16px; margin-left: 4px; }

.match-result { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: all 0.45s; }
.match-result.visible { opacity: 1; visibility: visible; }
.match-result-bg { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(32,14,11,0.55), rgba(3,6,10,0.95)); backdrop-filter: blur(4px); }
.match-result-panel { position: relative; width: min(680px, 90vw); max-height: 88vh; overflow: auto; padding: 36px 42px; border: 1px solid var(--line-bright); background: rgba(7,12,18,0.9); text-align: center; box-shadow: 0 30px 120px rgba(0,0,0,0.6); }
.match-result-panel::before { content: ''; position: absolute; top: 0; left: 20%; right: 20%; height: 2px; background: linear-gradient(90deg, transparent, var(--coral), transparent); }
.match-result-panel h2 { font-family: var(--display); font-size: 84px; line-height: 0.9; font-weight: 400; margin: 7px 0 3px; }
.match-result-panel p { font-size: 8px; letter-spacing: 0.2em; color: var(--muted); margin: 0; }
.match-scoreline { display: flex; align-items: center; justify-content: center; gap: 16px; margin: 20px 0 13px; font-size: 7px; letter-spacing: 0.13em; color: var(--muted); }
.match-scoreline i { font-style: normal; color: rgba(255,255,255,0.18); font-size: 20px; }
.match-scoreline span { display: flex; align-items: center; gap: 9px; }
.match-scoreline strong { font-family: var(--display); font-size: 31px; font-weight: 400; }
.match-scoreline .atk strong { color: var(--coral); }
.match-scoreline .def strong { color: var(--cyan); }
.scoreboard { border-top: 1px solid var(--line); margin: 12px 0 21px; }
.scoreboard-row { display: grid; grid-template-columns: 1fr 45px 45px; gap: 8px; padding: 7px 2px; border-bottom: 1px solid rgba(255,255,255,0.05); font-size: 7px; letter-spacing: 0.08em; text-align: left; color: var(--muted); }
.scoreboard-row.head { font-size: 5.5px; letter-spacing: 0.17em; color: rgba(127,141,152,0.6); padding-top: 9px; }
.scoreboard-row .sb-name { display: flex; align-items: center; gap: 7px; }
.scoreboard-row .sb-name i { width: 2px; height: 13px; background: var(--coral); }
.scoreboard-row.defender .sb-name i { background: var(--cyan); }
.scoreboard-row .sb-name strong { color: var(--ink-dim); font-weight: 500; }
.scoreboard-row .sb-name span { color: var(--muted); font-size: 5.5px; }
.scoreboard-row .you { color: var(--green); font-size: 5px; border: 1px solid rgba(85,240,176,0.4); padding: 1px 3px; }
.match-actions { display: flex; justify-content: center; gap: 8px; }
.match-actions .btn-ghost { padding: 0 25px; }

.pause-menu { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: rgba(3,6,10,0.72); backdrop-filter: blur(10px); opacity: 0; visibility: hidden; transition: all 0.3s; pointer-events: none; }
.pause-menu.visible { opacity: 1; visibility: visible; pointer-events: auto; }
.pause-card { width: 340px; padding: 31px; text-align: center; border: 1px solid var(--line-bright); background: rgba(8,14,20,0.92); }
.pause-card h2 { font-family: var(--display); font-size: 60px; font-weight: 400; line-height: 0.9; margin: 6px 0; }
.pause-card p { font-size: 8px; line-height: 1.6; color: var(--muted); margin-bottom: 20px; }
.pause-card .btn-primary { width: 100%; margin-bottom: 10px; }
.pause-card .text-button { display: block; margin: 11px auto 0; }
.pause-hint { font-size: 5.5px; letter-spacing: 0.13em; color: rgba(127,141,152,0.55); margin-top: 20px; }
.pointer-hint { position: absolute; left: 50%; bottom: 12%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 8px 14px; background: rgba(5,10,15,0.72); border: 1px solid var(--line); font-size: 7px; letter-spacing: 0.16em; color: var(--ink-dim); opacity: 0; visibility: hidden; transition: all 0.3s; }
.pointer-hint.visible { opacity: 1; visibility: visible; }
.pointer-hint small { font-size: 5px; color: var(--muted); letter-spacing: 0.1em; }

/* ---------- MOBILE ---------- */
.mobile-controls { display: none; position: absolute; inset: 0; pointer-events: none; }
body.touch-device .mobile-controls { display: block; }
.mobile-controls button { pointer-events: auto; }
.look-zone { position: absolute; top: 0; right: 0; bottom: 0; left: 42%; pointer-events: auto; touch-action: none; }
.joystick-zone { position: absolute; left: 4.2%; bottom: calc(6% + var(--safe-bottom)); width: 128px; height: 128px; border-radius: 50%; pointer-events: auto; touch-action: none; }
.joystick-ring { position: absolute; inset: 0; border: 1px solid rgba(230,240,245,0.2); border-radius: 50%; background: radial-gradient(circle, rgba(7,12,18,0.25), rgba(7,12,18,0.45)); }
.joystick-ring::before, .joystick-ring::after { content: ''; position: absolute; background: rgba(230,240,245,0.12); }
.joystick-ring::before { width: 1px; height: 70%; top: 15%; left: 50%; }
.joystick-ring::after { height: 1px; width: 70%; top: 50%; left: 15%; }
.joystick-knob { position: absolute; left: 50%; top: 50%; width: 52px; height: 52px; margin: -26px; border-radius: 50%; border: 1px solid rgba(255,99,63,0.7); background: radial-gradient(circle at 40% 35%, rgba(255,99,63,0.45), rgba(255,99,63,0.1)); box-shadow: 0 0 15px rgba(255,99,63,0.2); transition: transform 0.06s; }
.joystick-knob.active { background: radial-gradient(circle at 40% 35%, rgba(255,99,63,0.8), rgba(255,99,63,0.2)); }
.joystick-zone > span { position: absolute; bottom: -17px; left: 50%; transform: translateX(-50%); font-size: 5px; letter-spacing: 0.18em; color: rgba(220,235,242,0.5); }
.mobile-actions { position: absolute; right: 3.5%; bottom: calc(4% + var(--safe-bottom)); width: 245px; height: 190px; pointer-events: none; }
.mobile-btn { position: absolute; display: flex; flex-direction: column; align-items: center; justify-content: center; border-radius: 50%; border: 1px solid rgba(230,240,245,0.22); background: rgba(7,12,18,0.52); color: var(--ink-dim); backdrop-filter: blur(5px); font-size: 6px; letter-spacing: 0.04em; touch-action: none; }
.mobile-btn span { font-size: 10px; font-weight: 600; color: var(--ink); }
.mobile-btn b { font-weight: 400; font-size: 14px; color: var(--coral); line-height: 1; }
.mobile-btn.pressed { background: rgba(255,99,63,0.35); border-color: var(--coral); }
.mobile-btn.fire { width: 74px; height: 74px; right: 5px; bottom: 12px; border-color: rgba(255,99,63,0.6); background: radial-gradient(circle, rgba(255,99,63,0.28), rgba(7,12,18,0.5)); }
.mobile-btn.fire i { width: 25px; height: 25px; border: 2px solid var(--coral); border-radius: 50%; box-shadow: 0 0 10px rgba(255,99,63,0.3); }
.mobile-btn.ads { width: 45px; height: 45px; right: 84px; bottom: 75px; font-size: 5px; }
.mobile-btn.jump { width: 45px; height: 45px; right: 90px; bottom: 18px; font-size: 12px; }
.mobile-btn.reload { width: 44px; height: 44px; right: 140px; bottom: 64px; }
.mobile-btn.interact { width: 48px; height: 48px; right: 170px; bottom: 133px; border-color: rgba(255,178,74,0.45); }
.mobile-btn.interact span { color: var(--amber); }
.mobile-btn.ability { width: 48px; height: 48px; right: 135px; bottom: 135px; border-color: rgba(74,223,255,0.4); }
.mobile-btn.ability b { color: var(--cyan); }
.mobile-btn.special { width: 43px; height: 43px; right: 89px; bottom: 143px; border-color: rgba(255,99,63,0.4); }
.mobile-btn.special b { color: var(--coral); }
.mobile-btn i { position: absolute; inset: 0; display: grid; place-items: center; border-radius: 50%; font-style: normal; font-size: 12px; color: var(--ink); background: rgba(0,0,0,0.65); }
.mobile-weapon-switch { position: absolute; right: 15px; bottom: 99px; display: flex; flex-direction: column; gap: 4px; pointer-events: auto; }
