436:   update(dt, speed = 0, aiming = false) {
437:     this.clock += dt;
438:     const t = this.clock;
439:     const moving = speed > 0.1;
440:     const run = speed > 4.5;
441:     this.walkCycle += dt * (run ? 12 : moving ? 8 : 1.8);
442: 
443:     if (this.menuPose) {
444:       const breath = Math.sin(t * 1.55) * 0.012;
445:       this.torso.position.y = 1.11 * (this.data.model.height / 1.74) + breath;
446:       this.head.rotation.y = Math.sin(t * 0.42) * 0.11;
447:       this.head.rotation.x = Math.sin(t * 0.6) * 0.025;
448:       this.leftArm.rotation.z = -0.13 - Math.sin(t * 0.8) * 0.025;
449:       this.rightArm.rotation.z = 0.13 + Math.sin(t * 0.8 + 0.8) * 0.02;
450:       this.leftArm.rotation.x = Math.sin(t * 0.7) * 0.03;
451:       this.rightArm.rotation.x = -Math.sin(t * 0.7) * 0.03;
452:       if (this.data.model.hairStyle === 'long-braid') this.head.rotation.z = Math.sin(t * 0.5) * 0.015;
453:       this.leftLeg.rotation.z = -0.02;
454:       this.rightLeg.rotation.z = 0.02;
455:       return;
456:     }
457: 
458:     const swing = moving ? Math.sin(this.walkCycle) * (run ? 0.58 : 0.36) : 0;
459:     const counter = moving ? Math.cos(this.walkCycle) * (run ? 0.1 : 0.06) : 0;
460:     this.leftLeg.rotation.x = THREE.MathUtils.lerp(this.leftLeg.rotation.x, swing, 0.55);
461:     this.rightLeg.rotation.x = THREE.MathUtils.lerp(this.rightLeg.rotation.x, -swing, 0.55);
462:     this.leftArm.rotation.x = THREE.MathUtils.lerp(this.leftArm.rotation.x, -swing * 0.62, 0.4);
463:     this.rightArm.rotation.x = THREE.MathUtils.lerp(this.rightArm.rotation.x, swing * 0.45, 0.4);
464:     this.leftArm.rotation.z = -0.13;
465:     this.rightArm.rotation.z = 0.13;
466:     this.torso.position.y = 1.11 * (this.data.model.height / 1.74) + (moving ? Math.abs(Math.sin(this.walkCycle * 2)) * 0.018 : Math.sin(t * 1.7) * 0.006);
467:     this.torso.rotation.y = counter * 0.35;
468:     this.head.rotation.y = -counter * 0.18;
469:     this.root.rotation.z = moving ? Math.sin(this.walkCycle) * 0.018 : 0;
470:     if (aiming) {
