    const { game, app } = window.__vc;
    return {
      gameActive: app.gameActive,
      matchActive: game.matchActive,
      paused: game.paused,
      elapsed: game.elapsed,
      controls: game.controlsEnabled,
      playerAlive: game.player?.isAlive,
      playerPos: game.player?.position?.toArray?.().map((n) => +n.toFixed(2)),
      roundState: game.roundManager?.state,
      phaseTimer: game.roundManager?.phaseTimer,
      roundTime: game.roundManager?.roundTime,
      roundNumber: game.roundManager?.roundNumber,
      bombState: game.bombController?.state,
      botsAlive: game.bots?.filter((b) => b.isAlive).length,
      errors: window.__errors || []
    };
  });
  console.log(JSON.stringify(state));
}
await browser.close();

