});

for (let i = 0; i < 4; i++) {
  await page.waitForTimeout(5000);
  const info = await page.evaluate(() => {
    const { game } = window.__vc;
    const world = game.world;
    const atk = world.getSpawn('attackers', 0);
    const def = world.getSpawn('defenders', 0);
    const p1 = world.findPath(atk, world.sites.A.center);
    const p2 = world.findPath(def, world.sites.A.center);
    return {
      navCells: world.nav?.length || world.grid?.length || 'n/a',
      pathAtkToA: p1.map((n) => [n.x, n.z].map((v) => +v.toFixed(1))),
      pathDefToA_len: p2.length,
      bots: game.bots.map((b) => ({
        team: b.team[0], x: +b.position.x.toFixed(1), z: +b.position.z.toFixed(1),
        path: b.path?.length || 0, dest: b.destination ? [+b.destination.x.toFixed(0), +b.destination.z.toFixed(0)] : null
