// Probe bomb-plant pipeline: bot positions vs site radius.
import { createRequire } from 'module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/node_modules/');
const { chromium } = require('playwright-core');

const browser = await chromium.launch({
  args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--disable-gpu-sandbox', '--no-sandbox']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('pageerror', (e) => console.log(`[pageerror] ${e.message}`));
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(2500);
await page.evaluate(() => {
  document.querySelector('#play-button').click();
  window.__vc.game.timeScale = 12;
});
for (let i = 0; i < 8; i++) {
  await page.waitForTimeout(5000);
  const info = await page.evaluate(() => {
    const { game } = window.__vc;
    const bc = game.bombController;
    return {
      t: +game.elapsed.toFixed(0),
      st: game.roundManager.state.slice(0, 6),
      bomb: bc.state,
      planter: bc.botPlanter?.name || null,
      progress: +bc.plantProgress.toFixed(1),
      sites: Object.entries(game.world.sites).map(([k, s]) => `${k} r=${s.radius} c=${s.center.x.toFixed(0)},${s.center.z.toFixed(0)}`),
      atkBots: game.bots.filter((b) => b.team === 'attackers').map((b) => {
        const dA = +b.position.distanceTo(game.world.sites.A.center).toFixed(1);
        const dB = +b.position.distanceTo(game.world.sites.B.center).toFixed(1);
        return `${b.name}@${b.position.x.toFixed(0)},${b.position.z.toFixed(0)} dA=${dA} dB=${dB} path=${b.path.length} tgt=${b.target ? b.target.name : '-'}`;
      })
    };
  });
  console.log(JSON.stringify(info, null, 0).slice(0, 700));
}
